  const cache = new Map();

  function sleep(ms) {
    return new Promise(function (resolve) { setTimeout(resolve, ms); });
  }

  function num(v) {
    const n = Number(v);
    return isFinite(n) ? n : null;
  }

  function copyBars(src) {
    const out = src.map(function (b) { return Object.assign({}, b); });
    out.symbolName = src.symbolName || "";
    return out;
  }

  function parseBars(klines) {
    return (klines || []).map(function (line) {
      const p = String(line).split(",");
      return {
        t: p[0],
        o: num(p[1]),
        c: num(p[2]),
        h: num(p[3]),
        l: num(p[4]),
        v: num(p[5]) || 0
      };
    }).filter(function (b) { return b.c != null && b.c > 0; });
  }

  function trimBars(bars, spec) {
    let out = bars.slice();
    if (spec.day) {
      const day = String(spec.day).slice(0, 10);
      out = out.filter(function (b) { return String(b.t).slice(0, 10) === day; });
    } else if (spec.session === "last" && out.length) {
      const day = out[out.length - 1].t.slice(0, 10);
      out = out.filter(function (b) { return b.t.slice(0, 10) === day; });
    }
    if (spec.days) {
      const seen = [];
      for (let i = out.length - 1; i >= 0; i--) {
        const d = out[i].t.slice(0, 10);
        if (seen.indexOf(d) < 0) seen.push(d);
        if (seen.length >= spec.days) break;
      }
      const keep = {};
      seen.forEach(function (d) { keep[d] = true; });
      out = out.filter(function (b) { return keep[b.t.slice(0, 10)]; });
    }
    return out;
  }

  async function kline(secid, klt, lmt, endDay) {
    const end = endDay ? String(endDay).replace(/-/g, "") : "20500101";
    const key = secid + "|" + klt + "|" + lmt + "|" + end;
    if (cache.has(key)) return copyBars(cache.get(key));
    const url = "https://push2his.eastmoney.com/api/qt/stock/kline/get?secid=" + encodeURIComponent(secid) +
      "&klt=" + klt + "&fqt=1&lmt=" + lmt + "&end=" + end + "&fields1=f1,f2,f3,f4,f5,f6&fields2=f51,f52,f53,f54,f55,f56";
    let last = null;
    for (let attempt = 0; attempt < 3; attempt++) {
      try {
        const res = await fetch(url);
        if (!res.ok) throw new Error("行情站回應 " + res.status);
        const json = await res.json();
        const bars = parseBars(json.data && json.data.klines);
        if (!bars.length) throw new Error("沒有這段行情");
        bars.symbolName = toTW((json.data && json.data.name) || "");
        cache.set(key, bars);
        return copyBars(bars);
      } catch (err) {
        last = err;
        await sleep(350 * (attempt + 1));
      }
    }
    throw last || new Error("行情讀取失敗");
  }

  function clipBars(bars, from, to) {
    if (!from && !to) return bars;
    const out = bars.filter(function (b) {
      const d = b.t.slice(0, 10);
      if (from && d < from) return false;
      if (to && d > to) return false;
      return true;
    });
    out.symbolName = bars.symbolName || "";
    return out;
  }

  function spanDays(from, to) {
    const a = Date.parse(from + "T00:00:00");
    const b = Date.parse(to + "T00:00:00");
    if (!isFinite(a) || !isFinite(b) || b < a) return 20;
    return Math.max(1, Math.round((b - a) / 86400000) + 1);
  }

  function customSpec(from, to) {
    const days = spanDays(from, to);
    if (days <= 1) return { klt: 5, lmt: 120, session: "day", day: String(to || from).slice(0, 10), align: "index" };
    if (days <= 5) return { klt: 15, lmt: 240, days: days, align: "index" };
    if (days <= 400) return { klt: 101, lmt: Math.min(1300, days + 40), align: "date" };
    return { klt: 102, lmt: Math.min(400, Math.ceil(days / 5) + 20), align: "index" };
  }

  function wantsIntraday(rangeId, from, to) {
    if (from && to) return spanDays(from, to) <= 1;
    return rangeId === "1d";
  }

  function emSecid(secid) {
    const id = String(secid || "");
    if (id.indexOf("tw.") === 0) return "178." + id.slice(3);
    return id;
  }

  function formatTaipeiTs(sec) {
    const d = new Date(Number(sec) * 1000);
    if (!isFinite(d.getTime())) return "";
    const parts = new Intl.DateTimeFormat("en-CA", {
      timeZone: "Asia/Taipei",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      hour12: false
    }).formatToParts(d);
    const get = function (type) {
      const hit = parts.find(function (p) { return p.type === type; });
      return hit ? hit.value : "";
    };
    const hour = get("hour") === "24" ? "00" : get("hour");
    return get("year") + "-" + get("month") + "-" + get("day") + " " + hour + ":" + get("minute");
  }

  function parseYahooOhlcv(json) {
    const result = json && json.chart && json.chart.result && json.chart.result[0];
    if (!result) return [];
    const ts = result.timestamp || [];
    const q = ((result.indicators || {}).quote || [])[0] || {};
    const out = [];
    for (let i = 0; i < ts.length; i++) {
      const c = num(q.close && q.close[i]);
      if (!(c > 0)) continue;
      const o = num(q.open && q.open[i]);
      const h = num(q.high && q.high[i]);
      const l = num(q.low && q.low[i]);
      const t = formatTaipeiTs(ts[i]);
      if (!t) continue;
      out.push({
        t: t,
        o: o != null ? o : c,
        h: h != null ? h : c,
        l: l != null ? l : c,
        c: c,
        v: num(q.volume && q.volume[i]) || 0
      });
    }
    out.symbolName = toTW((result.meta && result.meta.shortName) || (result.meta && result.meta.symbol) || "");
    return out;
  }

  function yahooTwSymbols(secid) {
    const list = [];
    function addSyms(id) {
      yahooCandidates(id).forEach(function (s) {
        if (s && list.indexOf(s) < 0) list.push(s);
      });
    }
    addSyms(secid);
    addSyms(emSecid(secid));
    const code = twStockId(secid, "");
    if (code) {
      if (list.indexOf(code + ".TW") < 0) list.push(code + ".TW");
      if (list.indexOf(code + ".TWO") < 0) list.push(code + ".TWO");
    }
    return list;
  }

  async function yahooIntradayBars(secid, interval, day) {
    const dayStr = String(day || "").slice(0, 10);
    const iv = interval === "1m" ? "1m" : "5m";
    const list = yahooTwSymbols(secid);
    let periodQuery = "interval=" + iv + "&range=1d";
    if (dayStr && /^\d{4}-\d{2}-\d{2}$/.test(dayStr)) {
      const start = Date.parse(dayStr + "T00:00:00+08:00");
      const end = Date.parse(dayStr + "T23:59:59+08:00");
      if (isFinite(start) && isFinite(end)) {
        periodQuery = "interval=" + iv + "&period1=" + Math.floor(start / 1000) +
          "&period2=" + Math.floor(end / 1000);
      }
    }
    let lastErr = null;
    for (let i = 0; i < list.length; i++) {
      try {
        const json = await yahooChart(list[i], periodQuery);
        let rows = parseYahooOhlcv(json);
        if (dayStr) rows = rows.filter(function (b) { return b.t.slice(0, 10) === dayStr; });
        if (rows.length) {
          rows.symbolName = rows.symbolName || list[i];
          return rows;
        }
      } catch (err) {
        lastErr = err;
      }
    }
    if (lastErr) throw lastErr;
    return [];
  }

  async function yahooFiveMinBars(secid, day) {
    return yahooIntradayBars(secid, "5m", day);
  }

  async function yahooOneMinBars(secid, day) {
    return yahooIntradayBars(secid, "1m", day);
  }

  function flatOhlcRatio(bars) {
    if (!bars || !bars.length) return 1;
    let flat = 0;
    bars.forEach(function (b) {
      if (Math.abs(Number(b.h) - Number(b.l)) < 1e-9) flat++;
    });
    return flat / bars.length;
  }

  async function fiveMinBars(secid, day) {
    const dayStr = String(day || "").slice(0, 10);
    const id = emSecid(secid);
    let em = null;
    // 東財 5 分 K（台股／指數／美股等）；常開＝高＝低＝收，必要時改用 Yahoo
    if (/^(100|105|106|176|177|178|251)\./.test(id)) {
      try {
        const raw = await kline(id, 5, 120, dayStr || undefined);
        let cut = raw;
        if (dayStr) cut = raw.filter(function (b) { return String(b.t).slice(0, 10) === dayStr; });
        else cut = trimBars(raw, { session: "last" });
        if (cut.length) {
          cut.symbolName = raw.symbolName || cut.symbolName || "";
          em = cut;
        }
      } catch (err) { /* Yahoo 備援 */ }
    }
    let yahoo = null;
    try {
      yahoo = await yahooFiveMinBars(secid, dayStr);
    } catch (err) { /* ignore */ }
    if (em && em.length) {
      if (!yahoo || !yahoo.length) return em;
      // 東財幾乎全平棒時優先 Yahoo（仍可能偏平，畫布會用前收合成）
      if (flatOhlcRatio(em) > 0.85 && flatOhlcRatio(yahoo) < flatOhlcRatio(em)) return yahoo;
      return em;
    }
    if (yahoo && yahoo.length) return yahoo;
    throw new Error("沒有這天的五分 K");
  }

  async function bars(secid, rangeId, window) {
    const id = String(secid || "");
    const from = window && window.from;
    const to = window && window.to;
    if (wantsIntraday(rangeId, from, to)) {
      const day = (to || from || "").slice(0, 10);
      if (id === "fx.USDTWD") {
        const rows = await fxBars("1d", day ? { from: day, to: day } : null);
        return day ? clipBars(rows, day, day) : rows;
      }
      if (id === "fut.WTX") {
        const rows = await txfBars("1d", day ? { from: day, to: day } : null);
        return day ? clipBars(rows, day, day) : rows;
      }
      return fiveMinBars(id, day || undefined);
    }
    if (id === "fx.USDTWD") {
      const rows = await fxBars(rangeId, from && to ? { from: from, to: to } : null);
      return from && to ? clipBars(rows, from, to) : rows;
    }
    if (id === "fut.WTX") {
      const rows = await txfBars(rangeId, from && to ? { from: from, to: to } : null);
      return from && to ? clipBars(rows, from, to) : rows;
    }
    const stockId = twStockId(id, id.indexOf(".") >= 0 ? id.slice(id.indexOf(".") + 1) : "");
    if (stockId) {
      let want = 120;
      if (from && to) want = spanDays(from, to) + 20;
      else {
        const spec = RANGES[rangeId] || RANGES["20d"];
        if (spec.klt === 102) want = Math.min(1300, (spec.lmt || 160) * 7);
        else want = Math.max(20, spec.lmt || 20);
      }
      try {
        const rows = await historyBars(id, stockId, want);
        if (from && to) {
          const cut = clipBars(rows, from, to);
          if (cut.length) return cut;
        } else if (rows.length) {
          const spec = RANGES[rangeId] || {};
          let keep = rows.length;
          // 五日等：台股日線只留最近 N 個交易日（先前 klt≠101 會整段回傳，起迄會變成近一年）
          if (spec.days) keep = Math.max(1, spec.days);
          else if (spec.klt === 101) keep = Math.max(1, spec.lmt || rows.length);
          else if (spec.klt === 102) keep = rows.length;
          else if (spec.lmt) keep = Math.max(1, spec.lmt);
          const out = rows.slice(-keep);
          out.symbolName = rows.symbolName || stockId;
          return out;
        }
      } catch (err) {
        if (id.indexOf("tw.") === 0) throw err;
      }
      if (id.indexOf("tw.") === 0) throw new Error("這檔目前只有報價，沒有走勢");
    }
    if (from && to) {
      const spec = customSpec(from, to);
      const raw = await kline(secid, spec.klt, spec.lmt, to);
      const cut = clipBars(trimBars(raw, spec), from, to);
      if (!cut.length) throw new Error("這段日期沒有行情");
      return cut;
    }
    const spec = RANGES[rangeId] || RANGES["20d"];
    const raw = await kline(secid, spec.klt, spec.lmt);
    return trimBars(raw, spec);
  }

  function bustLiveCaches(secids) {
    quoteFresh.clear();
    // MIS 快取另受 5 秒限流保護，這裡不強制清空，避免高頻打到被鎖 IP
    const ids = (secids || []).filter(Boolean);
    if (!ids.length) {
      cache.clear();
      return;
    }
    Array.from(cache.keys()).forEach(function (key) {
      for (let i = 0; i < ids.length; i++) {
        if (key.indexOf(ids[i] + "|") === 0) {
          cache.delete(key);
          break;
        }
      }
    });
  }

  async function mapPool(items, limit, fn) {
    const ret = new Array(items.length);
    let cursor = 0;
    async function worker() {
      while (cursor < items.length) {
        const idx = cursor++;
        ret[idx] = await fn(items[idx], idx);
      }
    }
    const n = Math.min(limit, items.length);
    const jobs = [];
    for (let i = 0; i < n; i++) jobs.push(worker());
    await Promise.all(jobs);
    return ret;
  }

  function searchOnce(query) {
    return new Promise(function (resolve, reject) {
      const cb = "sjcb_" + Date.now() + "_" + Math.floor(Math.random() * 1000);
      const script = document.createElement("script");
      let done = false;
      const timer = setTimeout(function () { finish(new Error("搜尋逾時")); }, 8000);
      function finish(err, rows) {
        if (done) return;
        done = true;
        clearTimeout(timer);
        try { delete global[cb]; } catch (e) { global[cb] = undefined; }
        if (script.parentNode) script.parentNode.removeChild(script);
        if (err) reject(err);
        else resolve(rows || []);
      }
      global[cb] = function (data) {
        const list = (((data || {}).QuotationCodeTable || {}).Data) || [];
        const allow = { "美股": 1, "台股": 1, "日股": 1, "韓股": 1, "指数": 1 };
        const rows = [];
        list.forEach(function (item) {
          const kind = item.SecurityTypeName || "";
          if (!allow[kind]) return;
          if (/Notes|票据|债券|基金|票據|債券/.test(item.Name || "")) return;
          if (/ETF/i.test(item.Name || "") && String(item.Code || "").toUpperCase() !== query.toUpperCase()) return;
          const code = item.Code || "";
          const market = kind === "指数" || kind === "指數" ? indexRegion(code) : toTW(kind);
          rows.push({
            secid: item.QuoteID,
            code: code,
            name: toTW(item.Name || code),
            market: market
          });
        });
        rows.sort(function (a, b) {
          function rank(row) {
            const exact = row.code.toUpperCase() === query.toUpperCase() ? 0 : 5;
            const local = (/^\d{4}$/.test(query) && row.market === "台股") || (/^\d{6}$/.test(query) && row.market === "韓股") ? -1 : 0;
            return exact + local;
          }
          return rank(a) - rank(b);
        });
        finish(null, rows.slice(0, 8));
      };
      script.onerror = function () { finish(new Error("搜尋失敗")); };
      script.src = "https://searchapi.eastmoney.com/api/suggest/get?cb=" + cb +
        "&input=" + encodeURIComponent(query) + "&type=14&count=8";
      document.head.appendChild(script);
    });
  }

  async function twSymbol(code) {
    const url = "https://ws.api.cnyes.com/ws/api/v1/quote/quotes/TWS:" + encodeURIComponent(code) + ":STOCK";
    const res = await fetch(url);
    if (!res.ok) return null;
    const json = await res.json();
    const row = Array.isArray(json.data) ? json.data[0] : null;
    if (!row || String(row["200010"] || "").toUpperCase() !== code.toUpperCase()) return null;
    const shown = String(row["200010"]).toUpperCase();
    return { secid: "tw." + shown, code: shown, name: toTW(row["200009"] || shown), market: "台股" };
  }

  async function search(q) {
    const query = String(q || "").trim();
    if (!query) return [];
    const queries = [query];
    const cn = toCN(query);
    if (cn !== query) queries.push(cn);
    let rows = [];
    for (let i = 0; i < queries.length; i++) {
      const part = await searchOnce(queries[i]);
      part.forEach(function (row) {
        if (!rows.some(function (item) { return item.secid === row.secid; })) rows.push(row);
      });
      if (rows.some(function (row) { return row.market === "台股"; })) break;
    }
    const codeLike = /^\d{4,6}[A-Za-z]?$/.test(query);
    if (codeLike && !rows.some(function (row) {
      return row.market === "台股" && row.code.toUpperCase() === query.toUpperCase();
    })) {
      try {
        const extra = await twSymbol(query);
        if (extra) rows.unshift(extra);
      } catch (err) { /* 查不到就留東財的結果 */ }
    }
    const named = rows.filter(function (row) { return row.market === "台股"; }).slice(0, 5);
    await Promise.all(named.map(async function (row) {
      try {
        const tw = await twSymbol(row.code);
        if (tw && tw.name) row.name = tw.name;
        else row.name = toTW(row.name);
      } catch (err) {
        row.name = toTW(row.name);
      }
    }));
    rows.forEach(function (row) { row.name = toTW(row.name); row.market = toTW(row.market); });
    return rows.slice(0, 8);
  }

