  async function cnyesQuotes(codes) {
    const ids = (codes || []).map(function (c) { return String(c || "").toUpperCase(); }).filter(Boolean);
    const out = {};
    if (!ids.length) return out;
    const uniq = [];
    ids.forEach(function (c) { if (uniq.indexOf(c) < 0) uniq.push(c); });
    const chunks = [];
    for (let i = 0; i < uniq.length; i += 8) chunks.push(uniq.slice(i, i + 8));
    await mapPool(chunks, 2, async function (part) {
      const q = part.map(function (c) { return "TWS:" + c + ":STOCK"; }).join(",");
      const res = await fetch("https://ws.api.cnyes.com/ws/api/v1/quote/quotes/" + q);
      if (!res.ok) throw new Error("台股報價讀取失敗");
      const json = await res.json();
      const rows = Array.isArray(json.data) ? json.data : [];
      rows.forEach(function (row) {
        const parsed = parseCnyesQuote(row);
        if (parsed) out[parsed.code] = parsed;
      });
    });
    return out;
  }

  function sma(values, n) {
    const out = new Array(values.length).fill(null);
    let sum = 0;
    for (let i = 0; i < values.length; i++) {
      sum += values[i];
      if (i >= n) sum -= values[i - n];
      if (i >= n - 1) out[i] = sum / n;
    }
    return out;
  }

  function ema(values, n) {
    const out = new Array(values.length).fill(null);
    const k = 2 / (n + 1);
    let prev = null;
    let sum = 0;
    for (let i = 0; i < values.length; i++) {
      sum += values[i];
      if (i === n - 1) {
        prev = sum / n;
        out[i] = prev;
      } else if (i >= n) {
        prev = values[i] * k + prev * (1 - k);
        out[i] = prev;
      }
    }
    return out;
  }

  function rsi(values, n) {
    const out = new Array(values.length).fill(null);
    if (values.length <= n) return out;
    let gain = 0;
    let loss = 0;
    for (let i = 1; i <= n; i++) {
      const d = values[i] - values[i - 1];
      if (d >= 0) gain += d;
      else loss -= d;
    }
    gain /= n;
    loss /= n;
    out[n] = loss === 0 ? 100 : 100 - 100 / (1 + gain / loss);
    for (let i = n + 1; i < values.length; i++) {
      const d = values[i] - values[i - 1];
      const g = d > 0 ? d : 0;
      const l = d < 0 ? -d : 0;
      gain = (gain * (n - 1) + g) / n;
      loss = (loss * (n - 1) + l) / n;
      out[i] = loss === 0 ? 100 : 100 - 100 / (1 + gain / loss);
    }
    return out;
  }

  function macd(values) {
    const e12 = ema(values, 12);
    const e26 = ema(values, 26);
    const line = values.map(function (_, i) {
      return e12[i] == null || e26[i] == null ? null : e12[i] - e26[i];
    });
    const compact = [];
    const index = [];
    line.forEach(function (v, i) {
      if (v != null) {
        compact.push(v);
        index.push(i);
      }
    });
    const signalCompact = ema(compact, 9);
    const signal = new Array(values.length).fill(null);
    const hist = new Array(values.length).fill(null);
    signalCompact.forEach(function (v, j) {
      if (v == null) return;
      const i = index[j];
      signal[i] = v;
      hist[i] = line[i] - v;
    });
    return { line: line, signal: signal, hist: hist };
  }

  function atr(bars, n) {
    const tr = bars.map(function (b, i) {
      if (i === 0) return (b.h != null && b.l != null) ? b.h - b.l : 0;
      const prev = bars[i - 1].c;
      return Math.max(b.h - b.l, Math.abs(b.h - prev), Math.abs(b.l - prev));
    });
    return sma(tr, n);
  }

  function closesOf(bars) {
    return bars.map(function (b) { return b.c; });
  }

  function lastValid(arr) {
    for (let i = arr.length - 1; i >= 0; i--) if (arr[i] != null) return arr[i];
    return null;
  }

  function swings(bars, span) {
    const highs = [];
    const lows = [];
    for (let i = span; i < bars.length - span; i++) {
      let isH = true;
      let isL = true;
      for (let j = i - span; j <= i + span; j++) {
        if (bars[j].h > bars[i].h) isH = false;
        if (bars[j].l < bars[i].l) isL = false;
      }
      if (isH) highs.push(bars[i].h);
      if (isL) lows.push(bars[i].l);
    }
    return { highs: highs, lows: lows };
  }

  function slopeText(values) {
    const n = values.length;
    if (n < 10) return "樣本太短，看不出趨勢線。";
    let sx = 0, sy = 0, sxx = 0, sxy = 0;
    for (let i = 0; i < n; i++) {
      sx += i; sy += values[i]; sxx += i * i; sxy += i * values[i];
    }
    const den = n * sxx - sx * sx;
    const slope = den ? (n * sxy - sx * sy) / den : 0;
    const pct = values[0] ? (slope / values[0]) * 100 : 0;
    if (pct > 0.08) return "近 " + n + " 根收盤的回歸線向上，每根約 " + pct.toFixed(2) + "%。";
    if (pct < -0.08) return "近 " + n + " 根收盤的回歸線向下，每根約 " + pct.toFixed(2) + "%。";
    return "近 " + n + " 根收盤的回歸線接近走平，每根約 " + pct.toFixed(2) + "%。";
  }

  function roundPx(n) {
    if (!isFinite(n)) return null;
    if (Math.abs(n) >= 1000) return Math.round(n * 100) / 100;
    if (Math.abs(n) >= 100) return Math.round(n * 100) / 100;
    return Math.round(n * 1000) / 1000;
  }

  function capText(cap) {
    if (!isFinite(cap) || cap <= 0) return "";
    if (cap >= 1e12) return "市值約 " + (cap / 1e12).toFixed(2) + " 兆";
    if (cap >= 1e8) return "市值約 " + (cap / 1e8).toFixed(0) + " 億";
    return "市值約 " + Math.round(cap).toLocaleString("zh-Hant");
  }

  function fundLine(q) {
    if (!q) return "報價站沒有本益比或市值，這次只看技術面。";
    const bits = [];
    if (isFinite(q.pe) && q.pe > 0) {
      let tone = "本益比 " + q.pe.toFixed(1);
      if (q.pe < 12) tone += "，獲利收益率偏高";
      else if (q.pe > 40) tone += "，評價偏貴，部位應以技術結構為主";
      else tone += "，評價落在常見區間";
      bits.push(tone);
    } else bits.push("沒有可用本益比");
    if (isFinite(q.pb) && q.pb > 0) bits.push("股價淨值 " + q.pb.toFixed(2));
    const cap = capText(q.cap);
    if (cap) bits.push(cap);
    return bits.join("，") + "。";
  }

  function scoreOne(meta, bars) {
    const c = closesOf(bars);
    const i = c.length - 1;
    if (i < 60) return null;
    const s20 = sma(c, 20);
    const s60 = sma(c, 60);
    const s120 = sma(c, Math.min(120, c.length));
    const rv = rsi(c, 14);
    const md = macd(c);
    const at = atr(bars, 14);
    const close = c[i];
    const rsiNow = rv[i];
    const atrNow = at[i] || close * 0.02;
    let hh = -Infinity;
    let volSum = 0;
    let volN = 0;
    for (let k = i - 20; k < i; k++) {
      if (k < 0) continue;
      hh = Math.max(hh, bars[k].h);
      volSum += bars[k].v || 0;
      volN++;
    }
    const avgVol = volN ? volSum / volN : 0;
    const vol = bars[i].v || 0;
    let swing = close;
    for (let k = Math.max(0, i - 7); k <= i; k++) swing = Math.min(swing, bars[k].l);
    let stop = Math.min(swing, close - 1.5 * atrNow);
    if (!(stop < close * 0.995)) stop = close - 1.5 * atrNow;
    if (!(stop < close)) stop = close * 0.97;
    const risk = close - stop;
    const target = close + 2 * risk;
    const dist = s20[i] ? Math.abs(close - s20[i]) / s20[i] : 1;
    let score = 48;
    const upTrend = s20[i] != null && s60[i] != null && close > s60[i] && s20[i] > s60[i];
    const breakout = isFinite(hh) && close > hh && close > (s60[i] || 0) && avgVol > 0 && vol > avgVol * 1.35;
    const pullback = upTrend && dist < 0.025 && rsiNow >= 38 && rsiNow <= 62;
    const bounce = rsiNow != null && rsiNow < 35 && s120[i] != null && close > s120[i] && md.hist[i] != null && md.hist[i - 1] != null && md.hist[i] > md.hist[i - 1];
    if (close > (s60[i] || close)) score += 8; else score -= 12;
    if (s20[i] != null && s60[i] != null && s20[i] > s60[i]) score += 8; else score -= 8;
    if (rsiNow >= 40 && rsiNow <= 62) score += 8;
    if (rsiNow != null && rsiNow < 30) score -= 4;
    if (breakout) score += 14;
    if (pullback) score += 12;
    if (bounce) score += 6;
    let setup = "沒有明確結構";
    if (breakout) setup = "區間突破";
    else if (pullback) setup = "均線回檔";
    else if (bounce) setup = "超賣反彈";
    const tradable = score >= 68 && (breakout || pullback);
    const reasons = [];
    reasons.push(upTrend ? "日線收在 60 日均線上，20 日均線也在 60 日之上，趨勢仍偏多。" : "日線還沒有 20 日與 60 日均線同時向上的多頭排列。");
    if (breakout) reasons.push("收盤突破前 20 根高點，量能高於 20 日均量，屬於突破結構。");
    else if (pullback) reasons.push("價格回到 20 日均線附近（距離 " + (dist * 100).toFixed(1) + "%），RSI " + rsiNow.toFixed(0) + "，是順勢回檔而不是追高。");
    else if (bounce) reasons.push("RSI " + rsiNow.toFixed(0) + " 進入超賣，MACD 柱狀轉強，但仍要等站回短均線。");
    else reasons.push("RSI " + (rsiNow == null ? "—" : rsiNow.toFixed(0)) + "，與 20 日均線距離 " + (dist * 100).toFixed(1) + "%，沒有同時滿足突破或回檔。");
    reasons.push("停損放在近 8 根低點與 1.5 倍 ATR 的較低者，停利先以 2 倍風險計算。");
    return {
      secid: meta.secid,
      code: meta.code,
      name: meta.name,
      market: meta.market,
      badge: tradable ? "可進場" : "僅觀察",
      setup: setup,
      score: score,
      entry: roundPx(close),
      stop: roundPx(stop),
      target: roundPx(target),
      rr: risk > 0 ? 2 : null,
      atr: atrNow,
      reasons: reasons
    };
  }

  async function scan(opts) {
    opts = opts || {};
    const capital = Number(opts.capital) > 0 ? Number(opts.capital) : 1000000;
    const riskPct = Number(opts.riskPct) > 0 ? Number(opts.riskPct) : 1;
    const market = opts.market || "台股";
    const limit = Math.max(1, Math.min(20, Math.floor(Number(opts.limit) || 5)));
    const pool = UNIVERSE.filter(function (meta) {
      return !market || market === "全部" || meta.market === market;
    });
    let done = 0;
    const rows = await mapPool(pool, 3, async function (meta) {
      try {
        const raw = await kline(meta.secid, 101, 180);
        const idea = scoreOne(meta, raw);
        done++;
        if (opts.onProgress) opts.onProgress(done, pool.length, meta.name);
        return idea;
      } catch (err) {
        done++;
        if (opts.onProgress) opts.onProgress(done, pool.length, meta.name);
        return null;
      }
    });
    const ideas = rows.filter(Boolean).sort(function (a, b) { return b.score - a.score; }).slice(0, limit);
    let quotes = {};
    try { quotes = await quoteMap(ideas.map(function (item) { return item.secid; })); } catch (e) { quotes = {}; }
    ideas.forEach(function (item, idx) {
      item.rank = idx + 1;
      const risk = item.entry - item.stop;
      item.shares = risk > 0 ? Math.floor(capital * (riskPct / 100) / risk) : 0;
      item.fundamental = fundLine(quotes[item.secid]);
      item.riskCash = capital * (riskPct / 100);
    });
    return {
      scanned: pool.length,
      kept: ideas.length,
      tradable: ideas.filter(function (item) { return item.badge === "可進場"; }).length,
      ideas: ideas
    };
  }

  async function technical(secid) {
    const daily = await kline(secid, 101, 260);
    const weekly = await kline(secid, 102, 80);
    const name = daily.symbolName || secid;
    const c = closesOf(daily);
    const i = c.length - 1;
    const close = c[i];
    const s5 = sma(c, 5);
    const s20 = sma(c, 20);
    const s60 = sma(c, 60);
    const s120 = sma(c, 120);
    const rv = rsi(c, 14);
    const md = macd(c);
    const sw = swings(daily, 3);
    const wc = closesOf(weekly);
    const w20 = sma(wc, 20);
    const wClose = wc[wc.length - 1];
    const wMa = lastValid(w20);
    const weeklyUp = wMa != null && wClose > wMa;
    const maUp = s20[i] != null && s60[i] != null && close > s20[i] && s20[i] > s60[i];
    const macdUp = md.hist[i] != null && md.hist[i] > 0;
    const rsiOk = rv[i] != null && rv[i] >= 45 && rv[i] <= 70;
    const rsiWeak = rv[i] != null && rv[i] < 45;
    const maDown = s20[i] != null && s60[i] != null && close < s20[i] && s20[i] < s60[i];
    const macdDown = md.hist[i] != null && md.hist[i] < 0;
    let verdict = "觀望";
    if (maUp && macdUp && rsiOk && weeklyUp) verdict = "買進";
    else if (maDown && macdDown && rsiWeak && !weeklyUp) verdict = "賣出";
    const steps = [
      { name: "週線方向", pass: weeklyUp, detail: weeklyUp ? "週線收在 20 週均線上。" : "週線還沒站上 20 週均線。" },
      { name: "日線均線", pass: maUp, detail: maUp ? "收盤 > 20 日 > 60 日。" : "日線沒有多頭排列。" },
      { name: "MACD", pass: macdUp, detail: macdUp ? "MACD 柱狀在零軸上。" : "MACD 柱狀還在零軸下或剛走平。" },
      { name: "RSI", pass: rsiOk, detail: "RSI(14) 為 " + (rv[i] == null ? "—" : rv[i].toFixed(1)) + "。買進區看 45 到 70。" }
    ];
    if (verdict === "賣出") {
      steps.push({ name: "空頭確認", pass: true, detail: "均線空頭、MACD 為負、RSI 低於 45，週線也沒有轉強。" });
    }
    const supports = sw.lows.filter(function (p) { return p < close; }).slice(-3);
    const resistances = sw.highs.filter(function (p) { return p > close; }).slice(-3);
    const mas = [
      { name: "5 日", value: s5[i], above: s5[i] != null && close >= s5[i] },
      { name: "20 日", value: s20[i], above: s20[i] != null && close >= s20[i] },
      { name: "60 日", value: s60[i], above: s60[i] != null && close >= s60[i] },
      { name: "120 日", value: s120[i], above: s120[i] != null && close >= s120[i] }
    ];
    const histNow = md.hist[i];
    const histPrev = md.hist[i - 1];
    let momentum = "RSI " + (rv[i] == null ? "—" : rv[i].toFixed(1)) + "。";
    if (histNow != null) {
      momentum += " MACD 柱 " + histNow.toFixed(2);
      if (histPrev != null) momentum += histNow > histPrev ? "，柱狀放大。" : "，柱狀縮小。";
      else momentum += "。";
    }
    return {
      secid: secid,
      name: name,
      close: roundPx(close),
      verdict: verdict,
      steps: steps,
      supports: supports.map(roundPx),
      resistances: resistances.map(roundPx),
      trend: slopeText(c.slice(-60)),
      mas: mas.map(function (m) { return { name: m.name, value: roundPx(m.value), above: m.above }; }),
      momentum: momentum,
      weekly: weeklyUp ? "週線偏多，日線信號可以順著做。" : "週線尚未轉多，日線反彈先當反彈看。"
    };
  }

  function splitNews(text) {
    return String(text || "").split(/[\n。！？!?；;]+/).map(function (s) { return s.trim(); }).filter(Boolean).slice(0, 8);
  }

  async function newsPlan(opts) {
    opts = opts || {};
    const daily = await kline(opts.secid, 101, 180);
    const c = closesOf(daily);
    const i = c.length - 1;
    const close = c[i];
    const at = atr(daily, 14);
    const atrNow = at[i] || close * 0.02;
    const back5 = c[Math.max(0, i - 5)];
    const back20 = c[Math.max(0, i - 20)];
    const ret5 = back5 ? close / back5 - 1 : 0;
    const ret20 = back20 ? close / back20 - 1 : 0;
    const atrPct = close ? atrNow / close : 0;
    const priced = Math.abs(ret5) > atrPct * 2;
    const sentences = splitNews(opts.text);
    const seen = [];
    const unseen = [];
    sentences.forEach(function (line) {
      if (/將|預計|下季|明年|計畫|計劃|預期|將於/.test(line)) unseen.push(line);
      else if (/已|公布|公告|昨日|今天|本日|上季|去年/.test(line)) seen.push(line);
    });
    const posWords = (opts.text || "").match(/成長|上修|優於|買回|增產|利多|超預期|beat|raise|訂單/ig) || [];
    const negWords = (opts.text || "").match(/下修|衰退|調查|裁員|不如|利空|虧損|miss|延遲|禁令/ig) || [];
    let bias = "中性";
    if (posWords.length > negWords.length) bias = "偏多";
    else if (negWords.length > posWords.length) bias = "偏空";
    const capital = Number(opts.capital) > 0 ? Number(opts.capital) : 1000000;
    const riskPct = Number(opts.riskPct) > 0 ? Number(opts.riskPct) : 1;
    const stop = close - 1.5 * atrNow;
    const shares = stop < close ? Math.floor(capital * (riskPct / 100) / (close - stop)) : 0;
    let quotes = {};
    try { quotes = await quoteMap([opts.secid]); } catch (e) { quotes = {}; }
    return {
      name: daily.symbolName || opts.secid,
      close: roundPx(close),
      bias: bias,
      shortRange: [roundPx(close - 1.2 * atrNow), roundPx(close + 1.2 * atrNow)],
      longRange: [roundPx(close - 3 * atrNow), roundPx(close + 3 * atrNow)],
      ret5: ret5,
      ret20: ret20,
      priced: priced,
      pricedText: priced
        ? "近 5 日漲跌 " + (ret5 * 100).toFixed(1) + "%，已超過兩倍單日 ATR，短線消息有一部分可能已經反映在價格裡。"
        : "近 5 日漲跌 " + (ret5 * 100).toFixed(1) + "%，還在約一個 ATR 的平常波動裡，價格還沒有明顯消化這則消息。",
      seen: seen,
      unseen: unseen,
      noTime: !seen.length && !unseen.length,
      shares: shares,
      stop: roundPx(stop),
      riskCash: capital * (riskPct / 100),
      fundamental: fundLine(quotes[opts.secid]),
      weeklyNote: "20 日漲跌 " + (ret20 * 100).toFixed(1) + "%。長期區間用 3 倍 ATR，約一個月的平常擺動，不是目標價。"
    };
  }

  function tradeMetrics(bars, kind) {
    const c = closesOf(bars);
    const s5 = sma(c, 5);
    const s20 = sma(c, 20);
    const s60 = sma(c, 60);
    const rv = rsi(c, 14);
    const trades = [];
    let inPos = false;
    let entry = 0;
    let entryEquity = 1;
    let equity = 1;
    let peak = 1;
    let maxDD = 0;
    function mark(px) {
      const mtm = inPos ? entryEquity * (px / entry) : equity;
      peak = Math.max(peak, mtm);
      maxDD = Math.min(maxDD, mtm / peak - 1);
    }
    for (let i = 60; i < bars.length; i++) {
      let enter = false;
      let exit = false;
      if (kind === "cross") {
        enter = s5[i - 1] != null && s20[i - 1] != null && s5[i] != null && s20[i] != null && s5[i - 1] <= s20[i - 1] && s5[i] > s20[i];
        exit = s5[i - 1] != null && s20[i - 1] != null && s5[i] != null && s20[i] != null && s5[i - 1] >= s20[i - 1] && s5[i] < s20[i];
      } else if (kind === "rsi") {
        enter = rv[i - 1] != null && rv[i] != null && rv[i - 1] < 30 && rv[i] >= 30;
        exit = rv[i] != null && rv[i] > 70;
      } else {
        let hh = -Infinity;
        let ll = Infinity;
        for (let j = i - 20; j < i; j++) hh = Math.max(hh, bars[j].h);
        for (let j = i - 10; j < i; j++) ll = Math.min(ll, bars[j].l);
        enter = c[i] > hh && s60[i] != null && c[i] > s60[i];
        exit = c[i] < ll;
      }
      if (inPos && exit) {
        const ret = c[i] / entry - 1;
        trades.push(ret);
        equity = entryEquity * (1 + ret);
        inPos = false;
        mark(c[i]);
      } else if (!inPos && enter) {
        inPos = true;
        entry = c[i];
        entryEquity = equity;
        mark(c[i]);
      } else mark(c[i]);
    }
    const wins = trades.filter(function (r) { return r > 0; });
    const losses = trades.filter(function (r) { return r <= 0; });
    const grossWin = wins.reduce(function (s, r) { return s + r; }, 0);
    const grossLoss = losses.reduce(function (s, r) { return s + r; }, 0);
    const avg = trades.length ? trades.reduce(function (s, r) { return s + r; }, 0) / trades.length : 0;
    return {
      trades: trades.length,
      open: inPos,
      winRate: trades.length ? wins.length / trades.length : null,
      profitFactor: grossLoss < 0 ? grossWin / Math.abs(grossLoss) : (grossWin > 0 ? null : 0),
      maxDD: maxDD,
      avg: avg,
      equity: equity
    };
  }

  async function backtest(opts) {
    opts = opts || {};
    const lmt = opts.range === "5y" ? 1300 : opts.range === "3y" ? 780 : 260;
    const daily = await kline(opts.secid, 101, lmt);
    const kind = opts.strategy || "cross";
    const m = tradeMetrics(daily, kind);
    const names = { cross: "5 日與 20 日均線交叉", rsi: "RSI 跌破 30 回升、70 出場", breakout: "突破 20 日高、跌破 10 日低出場" };
    const tips = [];
    if (m.trades < 8) tips.push("完成的交易不到 8 筆，勝率還不穩。拉長到三年或五年，或改看突破策略。");
    if (m.profitFactor != null && m.profitFactor < 1) tips.push("獲利因子小於 1。只在收盤站上 60 日均線時允許進場，並把停損收在 1.5 倍 ATR。");
    if (m.winRate != null && m.winRate >= 0.6 && m.profitFactor != null && m.profitFactor < 1.3) tips.push("勝率不低，但賺的單太小。停利至少放到 2 倍停損，不要一有利潤就平倉。");
    if (m.maxDD < -0.25) tips.push("最大回撤超過 25%。同樣信號把部位減半，或加一條「週線在 20 週均線下不做多」。");
    if (m.winRate != null && m.winRate < 0.4 && m.trades >= 8) tips.push("勝率低於四成。進場改成只做突破，並要求量能高於 20 日均量。");
    if (!tips.length) tips.push("這組數字還站得住。下一步用另一個市場的同類股票再跑一次，確認不是單一標的的巧合。");
    return {
      name: daily.symbolName || opts.secid,
      strategy: names[kind] || kind,
      rangeLabel: opts.range === "5y" ? "五年" : opts.range === "3y" ? "三年" : "一年",
      bars: daily.length,
      metrics: m,
      tips: tips
    };
  }

  function returnsMap(bars) {
    const map = new Map();
    for (let i = 1; i < bars.length; i++) {
      const prev = bars[i - 1].c;
      if (prev) map.set(bars[i].t.slice(0, 10), bars[i].c / prev - 1);
    }
    return map;
  }

  function aligned(a, b) {
    const xs = [];
    const ys = [];
    a.forEach(function (v, day) {
      if (b.has(day)) {
        xs.push(v);
        ys.push(b.get(day));
      }
    });
    return { xs: xs, ys: ys };
  }

  function betaOf(xs, ys) {
    const n = xs.length;
    if (n < 30) return null;
    let mx = 0, my = 0;
    for (let i = 0; i < n; i++) { mx += xs[i]; my += ys[i]; }
    mx /= n; my /= n;
    let num = 0, den = 0;
    for (let i = 0; i < n; i++) {
      num += (xs[i] - mx) * (ys[i] - my);
      den += (ys[i] - my) * (ys[i] - my);
    }
    if (!den) return null;
    return num / den;
  }

  function pearson(xs, ys) {
    const n = xs.length;
    if (n < 30) return null;
    let mx = 0, my = 0;
    for (let i = 0; i < n; i++) { mx += xs[i]; my += ys[i]; }
    mx /= n; my /= n;
    let num = 0, dx = 0, dy = 0;
    for (let i = 0; i < n; i++) {
      const a = xs[i] - mx;
      const b = ys[i] - my;
      num += a * b; dx += a * a; dy += b * b;
    }
    if (!dx || !dy) return null;
    return num / Math.sqrt(dx * dy);
  }

  async function historyBars(secid, code, days) {
    const want = Math.max(40, Number(days) || 180);
    const stockId = twStockId(secid, code);
    if (stockId) {
      const rows = await finMind("TaiwanStockPrice", stockId, isoDaysAgo(Math.ceil(want * 1.7) + 40)).catch(function () { return []; });
      const bars = rows.map(function (row) {
        return {
          t: row.date,
          o: num(row.open),
          c: num(row.close),
          h: num(row.max),
          l: num(row.min),
          v: num(row.Trading_Volume) || 0
        };
      }).filter(function (b) { return b.c != null && b.c > 0; });
      if (bars.length >= 20) {
        const cut = bars.slice(-want);
        cut.symbolName = toTW(code || stockId);
        return cut;
      }
    }
    if (String(secid || "").indexOf("tw.") === 0) {
      throw new Error("沒有這段行情");
    }
    const series = await kline(secid, 101, want);
    if (!series.length) throw new Error("沒有這段行情");
    if (series.symbolName) series.symbolName = toTW(series.symbolName);
    return series;
  }

  async function riskReport(opts) {
    opts = opts || {};
    const holdings = (opts.holdings || []).filter(function (h) { return h.secid && Number(h.shares) > 0; });
    if (holdings.length < 1) throw new Error("先加入至少一檔持股");
    const cap = { "保守": 0.15, "穩健": 0.25, "積極": 0.4 }[opts.profile] || 0.25;
    const loadedAll = await mapPool(holdings, 3, async function (h) {
      try {
        const series = await historyBars(h.secid, h.code, 180);
        return {
          holding: h,
          bars: series,
          name: toTW(h.name || series.symbolName || h.code),
          ok: true
        };
      } catch (err) {
        return {
          holding: h,
          bars: null,
          name: toTW(h.name || h.code),
          ok: false,
          reason: err && err.message ? err.message : "沒有行情"
        };
      }
    });
    const failed = loadedAll.filter(function (row) { return !row.ok; });
    const loaded = loadedAll.filter(function (row) { return row.ok; });
    if (!loaded.length) throw new Error("持股都讀不到行情，請稍後再試");
    const market = await kline("100.SPX", 101, 180);
    const mkt = returnsMap(market);
    const priced = loaded.map(function (row) {
      const qBars = row.bars;
      const last = qBars[qBars.length - 1].c;
      const shares = Number(row.holding.shares);
      const value = last * shares;
      const cost = Number(row.holding.cost);
      const pack = aligned(returnsMap(qBars), mkt);
      return {
        secid: row.holding.secid,
        code: row.holding.code,
        name: row.name,
        shares: shares,
        cost: isFinite(cost) ? cost : null,
        price: last,
        value: value,
        pnl: isFinite(cost) ? (last - cost) * shares : null,
        beta: betaOf(pack.xs, pack.ys),
        rets: returnsMap(qBars)
      };
    });
    const total = priced.reduce(function (s, row) { return s + row.value; }, 0);
    priced.forEach(function (row) { row.weight = total ? row.value / total : 0; });
    const portBeta = priced.reduce(function (s, row) { return s + row.weight * (row.beta || 1); }, 0);
    const pairs = [];
    for (let a = 0; a < priced.length; a++) {
      for (let b = a + 1; b < priced.length; b++) {
        const pack = aligned(priced[a].rets, priced[b].rets);
        const rho = pearson(pack.xs, pack.ys);
        if (rho != null && rho >= 0.75) {
          pairs.push({ a: priced[a].code, b: priced[b].code, rho: rho });
        }
      }
    }
    const heavy = priced.filter(function (row) { return row.weight > cap; });
    const weak = [];
    if (failed.length) {
      weak.push("以下持股暫時讀不到足夠行情，這次先略過：" + failed.map(function (row) {
        return (row.holding.code || row.name) + (row.reason ? "（" + row.reason + "）" : "");
      }).join("、") + "。");
    }
    if (heavy.length) weak.push("單一帶超過「" + (opts.profile || "穩健") + "」上限 " + Math.round(cap * 100) + "%：" + heavy.map(function (row) { return row.code; }).join("、") + "。");
    if (pairs.length) weak.push("這些組合走勢幾乎綁在一起，分散效果有限：" + pairs.map(function (p) { return p.a + "/" + p.b; }).join("、") + "。");
    const oneMarket = {};
    holdings.forEach(function (h) { oneMarket[toTW(h.market || "未標")] = (oneMarket[toTW(h.market || "未標")] || 0) + 1; });
    const regions = Object.keys(oneMarket);
    if (regions.length === 1) weak.push("持股都在" + regions[0] + "，地區風險沒有分開。");
    if (!weak.length) weak.push("權重沒有明顯超過上限，也沒有相關係數高於 0.75 的配對。");
    const weights = priced.map(function (row) { return row.weight; });
    let room = weights.map(function (w) { return Math.min(w, cap); });
    let leftover = 1 - room.reduce(function (s, w) { return s + w; }, 0);
    const under = room.map(function (w) { return Math.max(0, cap - w); });
    const underSum = under.reduce(function (s, w) { return s + w; }, 0);
    if (leftover > 0.001 && underSum > 0) {
      room = room.map(function (w, i) { return w + leftover * (under[i] / underSum); });
      leftover = 0;
    }
    const plan = priced.map(function (row, i) {
      return { code: row.code, from: row.weight, to: room[i] };
    });
    const drop = portBeta * 0.2;
    let cashFrac = null;
    if (portBeta > 0.5) cashFrac = Math.max(0, Math.min(0.9, 1 - 0.5 / portBeta));
    return {
      profile: opts.profile || "穩健",
      cap: cap,
      total: total,
      beta: portBeta,
      drop: drop,
      cashFrac: cashFrac,
      rows: priced,
      pairs: pairs,
      weak: weak,
      plan: plan,
      cashLeft: leftover
    };
  }

  function reviewJournal(trades) {
    const rows = (trades || []).slice().sort(function (a, b) {
      return String(b.date || "").localeCompare(String(a.date || "")) || String(b.id || "").localeCompare(String(a.id || ""));
    }).slice(0, 20);
    const filled = rows.filter(function (t) { return !t.missed && isFinite(Number(t.entry)) && isFinite(Number(t.exit)); });
    const missed = rows.filter(function (t) { return t.missed || /錯過/.test(t.note || ""); });
    const pnls = filled.map(function (t) {
      const qty = Number(t.qty) > 0 ? Number(t.qty) : 1;
      const diff = String(t.side) === "放空" ? Number(t.entry) - Number(t.exit) : Number(t.exit) - Number(t.entry);
      return { trade: t, pnl: diff * qty, ret: Number(t.entry) ? diff / Number(t.entry) : 0 };
    });
    const wins = pnls.filter(function (p) { return p.pnl > 0; });
    const losses = pnls.filter(function (p) { return p.pnl <= 0; });
    const avgWin = wins.length ? wins.reduce(function (s, p) { return s + p.ret; }, 0) / wins.length : 0;
    const avgLoss = losses.length ? losses.reduce(function (s, p) { return s + p.ret; }, 0) / losses.length : 0;
    const noStop = filled.filter(function (t) { return !(Number(t.stop) > 0); }).length;
    const chase = rows.filter(function (t) { return t.emotion === "追價"; }).length;
    const fear = rows.filter(function (t) { return t.emotion === "恐懼提早出"; }).length;
    const revenge = rows.filter(function (t) { return t.emotion === "不甘心加碼"; }).length;
    const hesitate = rows.filter(function (t) { return t.emotion === "猶豫沒下"; }).length;
    const byCode = {};
    losses.forEach(function (p) {
      const code = p.trade.code || p.trade.symbol || "未命名";
      byCode[code] = (byCode[code] || 0) + 1;
    });
    let repeatCode = "";
    let repeatN = 0;
    Object.keys(byCode).forEach(function (code) {
      if (byCode[code] > repeatN) { repeatN = byCode[code]; repeatCode = code; }
    });
    const biases = [];
    if (chase >= 3 || (rows.length && chase / rows.length >= 0.3)) biases.push("追價出現 " + chase + " 次，進場常常發生在價格已經離開計畫之後。");
    if (fear >= 2) biases.push("有 " + fear + " 筆因為恐懼提早出場，獲利單容易留不住。");
    if (revenge >= 2) biases.push("不甘心加碼出現 " + revenge + " 次，虧損後擴大部位。");
    if (hesitate >= 2 || missed.length >= 3) biases.push("猶豫或明確記成錯過的有 " + (hesitate + missed.length) + " 筆，條件到了卻沒有執行。");
    if (!biases.length) biases.push(rows.length < 5 ? "最近樣本還少，行為偏誤還不明顯。" : "這 20 筆裡沒有單一情緒反覆超過門檻。");
    const rules = [];
    if (chase >= 2) rules.push("下單前先寫進場價。現價偏離那個價格超過 1%，這筆就放棄。");
    if (noStop >= Math.max(2, Math.ceil(filled.length / 2))) rules.push("沒有寫停損價之前，不送出委託。");
    if (avgLoss && avgWin && Math.abs(avgLoss) > avgWin) rules.push("停損固定用 1 倍 ATR，停利至少放到 2 倍停損，避免虧損單大於獲利單。");
    if (repeatN >= 3) rules.push(repeatCode + " 已連續虧損 " + repeatN + " 筆。這檔先休息 5 個交易日，期間不開新倉。");
    if (missed.length >= 2 || hesitate >= 2) rules.push("條件符合時先掛限價單，不把「再看看」留到收盤。每週檢討一次錯過清單。");
    if (fear >= 2) rules.push("進場當下寫好停利價。碰到停利之前，不因為盤中來回而手動平倉。");
    const fillers = [
      "每一筆先寫進場、停損、停利，三個價格齊了才下單。",
      "同一天虧損兩筆之後，當天不再開新倉。",
      "只做自選股裡週線仍在 20 週均線上的標的。"
    ];
    fillers.forEach(function (line) {
      if (rules.length < 3 && rules.indexOf(line) < 0) rules.push(line);
    });
    return {
      sample: rows.length,
      filled: filled.length,
      missed: missed.length,
      winRate: pnls.length ? wins.length / pnls.length : null,
      avgWin: avgWin,
      avgLoss: avgLoss,
      noStop: noStop,
      biases: biases,
      rules: rules.slice(0, 3),
      small: rows.length < 5
    };
  }

  function normalizeInvCode(token) {
    let s = String(token || "").toUpperCase().replace(/[^0-9A-Z]/g, "");
    if (!s) return "";
    // 常見 OCR：DOSEIA→00981A、OO985A→00985A
    s = s
      .replace(/^DOSEIA$/, "00981A")
      .replace(/^DO981A$/, "00981A")
      .replace(/^OO985A$/, "00985A")
      .replace(/^0O985A$/, "00985A")
      .replace(/^OO403A$/, "00403A");
    const letter = /[A-Z]$/.test(s) ? s.slice(-1) : "";
    let body = letter ? s.slice(0, -1) : s;
    body = body
      .replace(/O/g, "0")
      .replace(/Q/g, "0")
      .replace(/D/g, "0")
      .replace(/I/g, "1")
      .replace(/L/g, "1")
      .replace(/Z/g, "2")
      .replace(/S/g, "5")
      .replace(/B/g, "8")
      .replace(/G/g, "9")
      .replace(/A/g, "5");
    body = body.replace(/[^0-9]/g, "");
    if (letter) {
      if (body.length < 4 || body.length > 6) return "";
      return body + letter;
    }
    if (!/^\d{4}$/.test(body)) return "";
    return body;
  }

  function isTwInvCode(code) {
    if (/^\d{4,6}[A-Z]$/.test(code)) return true;
    if (!/^\d{4}$/.test(code)) return false;
    const n = Number(code);
    // 避開把損益／淨值片段誤當代號（如 1019、1384、3604）
    return n >= 1101 && n <= 9950;
  }

  function lookLikeShare(n) {
    if (!(n > 0) || n > 200000) return false;
    if (n === 100 || n === 200 || n === 500) return true;
    if (n >= 1000 && n % 1000 === 0) return true;
    if (n >= 100 && n % 100 === 0 && n <= 50000) return true;
    return false;
  }

  const INV_ALIASES = [
    { re: /00403A|主動統一升級|統一升級/i, code: "00403A", name: "主動統一升級50" },
    { re: /00981A|統一台股增長|統一台設增長/i, code: "00981A", name: "主動統一台股增長" },
    { re: /00985A|野村台灣/i, code: "00985A", name: "主動野村台灣50" },
    { re: /00757|統一\s*FANG|統一FANG|FANG\+|FANG＋/i, code: "00757", name: "統一FANG+" },
    { re: /00878|國泰永續|永續高股息/i, code: "00878", name: "國泰永續高股息" },
    { re: /00929|復華台灣科技|科技優息/i, code: "00929", name: "復華台灣科技優息" },
    { re: /00919|群益台灣精選|精選高息/i, code: "00919", name: "群益台灣精選高息" },
    { re: /0050|元大台灣50/i, code: "0050", name: "元大台灣50" },
    { re: /0056|元大高股息/i, code: "0056", name: "元大高股息" },
    { re: /2345|智邦/, code: "2345", name: "智邦" },
    { re: /2382|廣達/, code: "2382", name: "廣達" },
    { re: /3037|欣興/, code: "3037", name: "欣興" },
    { re: /2727|王品/, code: "2727", name: "王品" },
    { re: /2330|台積電/, code: "2330", name: "台積電" },
    { re: /2308|台達電/, code: "2308", name: "台達電" },
    { re: /2312|金寶/, code: "2312", name: "金寶" },
    { re: /1587|吉茂/, code: "1587", name: "吉茂" },
    { re: /2890|永豐金/, code: "2890", name: "永豐金" },
    { re: /2881|富邦金/, code: "2881", name: "富邦金" },
    { re: /2882|國泰金/, code: "2882", name: "國泰金" },
    { re: /2317|鴻海/, code: "2317", name: "鴻海" },
    { re: /2454|聯發科/, code: "2454", name: "聯發科" }
  ];

  function numLoose(v) {
    if (v == null || v === "") return null;
    const n = Number(String(v).replace(/,/g, "").replace(/%/g, "").trim());
    return isFinite(n) ? n : null;
  }

  // 貼上「商品名稱 / 股數 / 成本價 / 現價…」明細（含代號括號）
  function parseHoldingsTable(raw) {
    let text = String(raw || "");
    text = text.replace(/[０-９]/g, function (ch) {
      return String.fromCharCode(ch.charCodeAt(0) - 0xFEE0);
    });
    const lines = text.split(/\r?\n/).map(function (line) { return line.trim(); }).filter(Boolean);
    const out = [];
    const seen = {};
    lines.forEach(function (line) {
      if (/商品名稱|未實現損益|^名稱\b|損益率/.test(line) && !/[\(（]\s*\d{4}/.test(line)) return;
      if (/^合計|^總計|^筆數|^損益\s*:/.test(line)) return;
      const cells = line.split(/\t+/).map(function (c) { return c.trim(); }).filter(Boolean);
      let name = "";
      let code = "";
      let shares = null;
      let cost = null;
      let pct = null;
      let pnl = null;
      if (cells.length >= 4) {
        const head = cells[0];
        const hm = head.match(/^(.+?)\s*[\(（]\s*([0-9]{4,6}[A-Za-z]?)\s*[\)）]\s*$/);
        if (hm) {
          name = hm[1].trim();
          code = hm[2].toUpperCase();
        } else {
          name = head;
        }
        shares = numLoose(cells[1]);
        cost = numLoose(cells[2]);
        if (cells.length >= 6) pnl = numLoose(String(cells[5]).replace(/^\+/, "+"));
        if (cells.length >= 7) {
          const p = numLoose(cells[6]);
          if (p != null) pct = p;
        }
      } else {
        let m = line.match(/^(.+?)\s*[\(（]\s*([0-9]{4,6}[A-Za-z]?)\s*[\)）]\s+([\d,]+(?:\.\d+)?)\s+([\d,]+(?:\.\d+)?)/);
        if (m) {
          name = m[1].trim();
          code = m[2].toUpperCase();
          shares = numLoose(m[3]);
          cost = numLoose(m[4]);
        } else {
          m = line.match(/^([\u4e00-\u9fffA-Za-z0-9+＋]{2,30})\s+([\d,]+(?:\.\d+)?)\s+([\d,]+(?:\.\d+)?)\s+([\d,]+(?:\.\d+)?)/);
          if (!m) return;
          name = m[1].trim();
          shares = numLoose(m[2]);
          cost = numLoose(m[3]);
        }
        const pctM = line.match(/([+-]?\d+(?:\.\d+)?)\s*%\s*$/);
        if (pctM) pct = Number(pctM[1]);
        const pnlM = line.match(/([+-]\d[\d,]*(?:\.\d+)?)\s+[+-]?\d+(?:\.\d+)?\s*%/);
        if (pnlM) pnl = numLoose(pnlM[1]);
      }
      if (!(shares > 0) || shares > 200000) return;
      if (!code) {
        for (let i = 0; i < INV_ALIASES.length; i++) {
          if (INV_ALIASES[i].re.test(name)) {
            code = INV_ALIASES[i].code;
            name = INV_ALIASES[i].name;
            break;
          }
        }
      }
      if (!code) return;
      if (seen[code]) return;
      seen[code] = true;
      if (!(cost > 0)) cost = null;
      out.push({
        code: code,
        name: name || code,
        shares: shares,
        cost: cost,
        pnl: pnl,
        pct: pct
      });
    });
    return out;
  }

  // StockJason／富邦匯出：{ source, holdings:[{code,todayQty,tradableQty,costPrice,raw}] }
  function parseFubonHoldingsJson(raw) {
    let data = raw;
    if (typeof raw === "string") {
      try { data = JSON.parse(raw); } catch (err) { return []; }
    }
    if (!data || typeof data !== "object") return [];
    const list = Array.isArray(data.holdings) ? data.holdings
      : (Array.isArray(data) ? data : []);
    const out = [];
    const seen = {};
    list.forEach(function (row) {
      if (!row || typeof row !== "object") return;
      const code = String(row.code || row.stock_no || (row.raw && row.raw.stock_no) || "")
        .trim().toUpperCase();
      if (!code || seen[code]) return;
      const todayQty = Number(row.todayQty != null ? row.todayQty
        : (row.raw && row.raw.today_qty));
      const tradableQty = Number(row.tradableQty != null ? row.tradableQty
        : (row.raw && row.raw.tradable_qty));
      const shares = Math.max(
        isFinite(todayQty) && todayQty > 0 ? todayQty : 0,
        isFinite(tradableQty) && tradableQty > 0 ? tradableQty : 0
      );
      if (!(shares > 0)) return;
      let cost = Number(row.costPrice != null ? row.costPrice
        : (row.raw && row.raw.cost_price));
      if (!(cost > 0) && row.raw && Number(row.raw.buy_value) > 0) {
        cost = Number(row.raw.buy_value) / shares;
      }
      // 避免浮點顯示成 4.4350000001
      if (cost > 0) cost = Math.round(cost * 10000) / 10000;
      let pnl = null;
      const topPnl = Number(row.unrealizedPnl != null ? row.unrealizedPnl : row.pnl);
      if (isFinite(topPnl)) {
        pnl = topPnl;
      } else if (row.raw) {
        const up = Number(row.raw.unrealized_profit);
        const down = Number(row.raw.unrealized_loss);
        const pl = Number(row.raw.profit_or_loss);
        if (isFinite(pl) && (pl !== 0 || row.raw.profit_or_loss != null)) pnl = pl;
        else if (up > 0) pnl = up;
        else if (down > 0) pnl = -down;
      }
      seen[code] = true;
      out.push({
        code: code,
        name: String(row.name || "").trim(),
        shares: shares,
        cost: cost > 0 ? cost : null,
        pnl: pnl,
        pct: null
      });
    });
    return out;
  }

  function parseInventory(raw) {
    let text = String(raw || "");
    text = text.replace(/[０-９]/g, function (ch) {
      return String.fromCharCode(ch.charCodeAt(0) - 0xFEE0);
    });
    text = text.replace(/[—–−]/g, "-");
    text = text.replace(/([\u4e00-\u9fff])\s+(?=[\u4e00-\u9fff])/g, "$1");
    text = text.replace(/[|「」“”"'【】\[\]_。]/g, " ");
    text = text.replace(/(\d),(?=\d{3}(\D|$))/g, "$1");
    // 千分位小數（淨值）不要併成假代號：36.291 → 保留
    text = text.replace(/(\d)\.(\d{3})(?!\d)/g, function (m, a, b) {
      // 僅當像「10.000」股數寫法才合併；淨值／成本維持空白隔開
      if (Number(a + b) <= 100000 && /000$/.test(b)) return a + b;
      return a + " " + b;
    });
    const noiseName = /返回|庫存|說明|帳務|損益|股票|交易|頁次|筆數|調整|成本|配息|融資|首頁|行情|桃園|反沖|重查|現買|現賣|現股|現設|現投|股數|均價|類別|名稱|餘額|試算|利率|真次|淨值|付出|查詢|更新|總計|功能|商品|下單|明細|帳面|市值|投資|幣別|台幣/;
    const aliasCodes = {};
    INV_ALIASES.forEach(function (a) { aliasCodes[a.code] = a; });
    const isUnrealizedShot = /未實現損益|損益率|帳面市值|成本價/.test(text);

    function cleanName(source) {
      const found = String(source || "").match(/[\u4e00-\u9fff][\u4e00-\u9fff0-9A-Za-z+＋]{1,20}/g) || [];
      for (let i = found.length - 1; i >= 0; i--) {
        const name = found[i].replace(/現股|現設|現投/g, "");
        if (name.length >= 2 && !noiseName.test(name)) return name;
      }
      return "";
    }

    // 用投資成本反推哪個是成本價（券商欄常見：股數 現價 成本價 投資成本）
    function resolveCostPrice(shares, a, b, invest) {
      if (!(shares > 0)) return { cost: null, price: null };
      if (invest > 0) {
        const implied = invest / shares;
        const da = Math.abs(a - implied);
        const db = Math.abs(b - implied);
        if (da <= db && (da / implied <= 0.15 || da < 2)) {
          return { cost: Math.round(a * 100) / 100, price: b };
        }
        if (db < da && (db / implied <= 0.15 || db < 2)) {
          return { cost: Math.round(b * 100) / 100, price: a };
        }
        return {
          cost: Math.round(implied * 100) / 100,
          price: da < db ? b : a
        };
      }
      // 無投資成本時：未實現畫面多為 現價、成本價
      return {
        cost: b > 0 && b < 100000 ? Math.round(b * 100) / 100 : null,
        price: a
      };
    }

    // 未實現損益列：現股 股數 現價 成本價 投資成本 …
    function pickUnrealizedRow(after) {
      const src = String(after || "").replace(/(\d),(?=\d{3}(\D|$))/g, "$1");
      let m = src.match(/現[股設投]\s*(\d{1,7}(?:\.\d+)?)\s+(\d+(?:\.\d+)?)\s+(\d+(?:\.\d+)?)(?:\s+(\d+(?:\.\d+)?))?/);
      if (!m) {
        m = src.match(/^\D{0,12}(\d{1,7})\s+(\d+(?:\.\d+)?)\s+(\d+(?:\.\d+)?)(?:\s+(\d+(?:\.\d+)?))?/);
      }
      if (!m) return { shares: null, pnl: null, cost: null, pct: null };
      const shares = Number(m[1]);
      if (!(shares > 0) || shares > 200000 || shares !== Math.round(shares)) {
        return { shares: null, pnl: null, cost: null, pct: null };
      }
      // 零股／碎股也要收（1、12、1111）
      const a = Number(m[2]);
      const b = Number(m[3]);
      const invest = m[4] != null ? Number(m[4]) : null;
      const pair = resolveCostPrice(shares, a, b, invest);
      let pct = null;
      const pctM = src.match(/([+-]?)(\d+(?:\.\d+)?)\s*%/);
      if (pctM) {
        // 有小數的獲利率不要再亂縮
        pct = pctM[2].indexOf(".") >= 0
          ? (pctM[1] === "-" ? -Math.abs(Number(pctM[2])) : Number(pctM[2]) * (pctM[1] === "+" || !pctM[1] ? 1 : 1))
          : parsePctToken(pctM[1], pctM[2]);
        if (pctM[1] === "+") pct = Math.abs(pct);
        if (pctM[1] === "-") pct = -Math.abs(pct);
        if (!pctM[1] && pctM[2].indexOf(".") >= 0) pct = Number(pctM[2]);
      }
      let pnl = null;
      const pnlAll = [];
      const signedRe = /([+-])\s*(\d{1,3}(?:,\d{3})*|\d+)(?:\.\d+)?/g;
      let sm;
      while ((sm = signedRe.exec(src))) {
        if (/%/.test(src.slice(sm.index, sm.index + sm[0].length + 2))) continue;
        const v = Number((sm[1] + sm[2]).replace(/,/g, ""));
        if (isFinite(v) && Math.abs(v) >= 1) pnlAll.push(v);
      }
      if (pnlAll.length) pnl = pnlAll[0];
      if (pnl != null && pct != null) {
        if (pct < 0 && pnl > 0) pnl = -pnl;
        if (pct > 0 && pnl < 0) pnl = Math.abs(pnl);
      }
      return {
        shares: shares,
        cost: pair.cost,
        pnl: pnl,
        pct: pct
      };
    }

    function parsePctToken(sign, num) {
      let p = Number(num);
      // OCR 常丟小數點：+115%→1.15、+24%→2.4、+281%→2.81
      if (!/\./.test(num)) {
        if (p >= 100) p = p / 100;
        else if (p >= 10) p = p / 10;
      }
      if (sign === "-") p = -Math.abs(p);
      else if (sign === "+") p = Math.abs(p);
      return p;
    }

    // 成本均價＝買入價（欄尾單價；以淨值／付出成本成對校準，避免把 1500 當總額）
    function pickAvgCost(nums, shares) {
      if (!(shares > 0) || !nums || !nums.length) return null;
      const totals = nums.filter(function (n) {
        return n !== shares && n >= shares * 2 && n / shares >= 0.5 && n / shares <= 20000;
      }).sort(function (a, b) { return b - a; });
      let paid = null;
      for (let i = 0; i < totals.length - 1; i++) {
        if (totals[i + 1] / totals[i] >= 0.9) {
          paid = totals[i + 1];
          break;
        }
      }
      if (paid == null) {
        for (let i = 0; i < totals.length; i++) {
          const n = totals[i];
          if (n >= Math.max(shares * 30, 20000) || (shares >= 1000 && n >= shares * 3)) {
            paid = n;
            break;
          }
        }
      }
      let paidAvg = null;
      if (paid != null) {
        const avg = paid / shares;
        if (avg >= 0.2 && avg <= 20000) paidAvg = avg;
      }
      // 1) 欄尾單價：須接近付出成本均價（防下一列小數混入）
      for (let i = nums.length - 1; i >= 0; i--) {
        const n = nums[i];
        if (n === shares || n < 0.2 || n > 20000) continue;
        if (paid != null && n >= paid * 0.9) continue;
        if (paidAvg != null) {
          if (Math.abs(n - paidAvg) / paidAvg <= 0.08) return Math.round(n * 100) / 100;
        } else if (Math.abs(n - Math.round(n)) > 1e-9) {
          return n;
        }
      }
      // 2) 沒印出均價時用付出成本 ÷ 股數
      if (paidAvg != null) return Math.round(paidAvg * 100) / 100;
      // 3) OCR 常丟小數：886→8.86、2404→24.04、30043→300.43
      for (let i = nums.length - 1; i >= 0; i--) {
        const n = nums[i];
        if (n === shares || n !== Math.round(n)) continue;
        if (n >= 10000 && n <= 9999999) {
          const c = n / 100;
          if (c >= 0.5 && c <= 20000) return Math.round(c * 100) / 100;
        }
        if (shares >= 1000 && n >= 100 && n < 100000) {
          const c = n / 100;
          if (c >= 0.5 && c <= 500) return Math.round(c * 100) / 100;
        }
      }
      // 4) 整數單價（如 1500、750）
      for (let i = nums.length - 1; i >= 0; i--) {
        const n = nums[i];
        if (n !== shares && n >= 1 && n <= 20000 && !lookLikeShare(n)) return n;
      }
      return null;
    }

    // fromEnd：代號在後時，取最靠近代號的股數／％
    function pickSharesAndPnl(source, fromEnd) {
      const src = String(source || "");
      let pct = null;
      const pctAll = [];
      const pctRe = /([+-]?)(\d+(?:\.\d+)?)\s*%/g;
      let pm;
      while ((pm = pctRe.exec(src))) pctAll.push(parsePctToken(pm[1], pm[2]));
      if (pctAll.length) pct = fromEnd ? pctAll[pctAll.length - 1] : pctAll[0];

      const cleaned = src.replace(/[+-]?\d+(?:\.\d+)?\s*%/g, " ");
      const tokens = cleaned.match(/[+-]?\d+(?:\.\d+)?/g) || [];
      const signed = [];
      const nums = [];
      tokens.forEach(function (token) {
        const value = Number(token.replace(/,/g, ""));
        if (!isFinite(value) || value === 0) return;
        if (token.charAt(0) === "-" || token.charAt(0) === "+") {
          if (Math.abs(value) < 100 && token.indexOf(".") >= 0) return;
          signed.push(value);
          return;
        }
        nums.push(value);
      });
      const shareCands = nums.filter(function (n) {
        if (!(n > 0) || n > 200000 || n !== Math.round(n)) return false;
        // 未實現損益常有零股／碎股，不強制整張倍數
        if (isUnrealizedShot) return true;
        return lookLikeShare(n) && n <= 100000;
      });
      const shares = shareCands.length
        ? (fromEnd ? shareCands[shareCands.length - 1] : shareCands[0])
        : null;
      if (!(shares > 0)) {
        return { shares: null, pnl: signed.length ? (fromEnd ? signed[signed.length - 1] : signed[0]) : null, cost: null, pct: pct };
      }
      let pnl = signed.length ? (fromEnd ? signed[signed.length - 1] : signed[0]) : null;
      if (pct != null) {
        const near = nums.filter(function (n) {
          return n !== shares && n < Math.max(shares * 20, 50000) && n >= 1;
        });
        if (pnl == null && near.length) {
          pnl = fromEnd ? near[near.length - 1] : (near.find(function (n) { return n < 100000; }) || near[0]);
        }
        if (pnl != null && pct < 0 && pnl > 0) pnl = -pnl;
        if (pnl != null && pct > 0 && pnl < 0) pnl = Math.abs(pnl);
      }
      // 沒有獲利率時，過小損益多半是 OCR 碎片（如 30、3）
      if (pnl != null && pct == null && Math.abs(pnl) < 20) pnl = null;
      const cost = pickAvgCost(nums, shares);
      return { shares: shares, pnl: pnl, cost: cost, pct: pct };
    }

    function parseBlock(block) {
      const lines = String(block || "").split(/\n/).map(function (line) {
        return line.replace(/\s+/g, " ").trim();
      }).filter(function (line) {
        return line && !/帳號|總損益|頁次|返回|重查|成本扣息|調整帳務|其他庫存|帳務模式|先進先出|首頁|自選報價|交易帳務|市場行情|新增自選|損益試算方式|---PSM/.test(line);
      });
      const joined = lines.join("\n");
      const found = {};

      function put(code, name, money, score) {
        if (!code || !(money && money.shares > 0)) return;
        const prev = found[code];
        if (!prev || score > prev.score) {
          found[code] = {
            code: code,
            name: name || "",
            shares: money.shares,
            pnl: money.pnl,
            cost: money.cost,
            pct: money.pct,
            score: score
          };
        }
      }

      // 含 OCR 變形：DOSEIA、OO985A、00ogaA
      const codeRe = /(?<![0-9A-Za-z])((?:(?:00|DO|OO|0O)[0-9OQIlSGBZodgaD]{3,5}[A-Za-z])|(?:[0-9]{4}))(?![0-9A-Za-z])/gi;
      let match;
      while ((match = codeRe.exec(joined))) {
        const rawCode = match[1];
        const prev2 = joined.slice(Math.max(0, match.index - 2), match.index);
        if (/[+]/.test(prev2)) continue;
        if (joined.charAt(match.index - 1) === "-") continue;
        const code = normalizeInvCode(rawCode);
        if (!isTwInvCode(code)) continue;
        if (/^(?:100|200|500|1000|2000|3000|5000|10000)$/.test(code)) continue;
        // 元大列：股數…淨值、付出成本、成本均價約 50～70 字；均價用付出成本校準防吃下一檔
        const afterNear = joined.slice(match.index + rawCode.length, match.index + rawCode.length + 72);
        const afterFar = joined.slice(match.index + rawCode.length, match.index + rawCode.length + 100);
        const head = joined.slice(Math.max(0, match.index - 24), match.index);
        const before = joined.slice(Math.max(0, match.index - 100), match.index);
        const known = aliasCodes[code];
        // 代號後短距沒數字 → 視為列尾代號，優先往前取，避免吃到下一檔
        const afterHasNum = /\d/.test(joined.slice(match.index + rawCode.length, match.index + rawCode.length + 12));
        let money = { shares: null, pnl: null, cost: null, pct: null };
        let fromBefore = false;
        if (afterHasNum) money = pickSharesAndPnl(afterNear, false);
        if (!(money.shares > 0) && (known || /現[股設投]/.test(before) || /[A-Z]$/.test(code))) {
          money = pickSharesAndPnl(before, true);
          fromBefore = !!(money.shares > 0);
        }
        if (!(money.shares > 0) && afterHasNum) money = pickSharesAndPnl(afterFar, false);
        if (!(money.shares > 0)) money = pickSharesAndPnl(afterFar, false);
        if (!(money.shares > 0)) continue;
        const isEtf = /[A-Z]$/.test(code);
        const marked = /現[股設投買]|主動/.test(head + before.slice(-30) + afterNear.slice(0, 20));
        // 純四碼：必須是已知持股，或緊鄰「現股／現設」標記
        if (!isEtf && !known && !marked) continue;
        if (!isEtf && !known && money.shares > 20000) continue;
        let score = isEtf ? 6 : 4;
        if (known) score += 3;
        if (marked) score += 2;
        if (money.pct != null) score += 1;
        if (!fromBefore) score += 1;
        put(code, known ? known.name : cleanName(head + before), money, score);
      }

      INV_ALIASES.forEach(function (alias) {
        if (found[alias.code]) return;
        const m = alias.re.exec(joined);
        if (!m) return;
        const after = joined.slice(m.index + m[0].length, m.index + m[0].length + 140);
        const before = joined.slice(Math.max(0, m.index - 100), m.index);
        let money = pickUnrealizedRow(after);
        if (!(money.shares > 0)) money = pickSharesAndPnl(after, false);
        if (!(money.shares > 0)) money = pickSharesAndPnl(before, true);
        if (!(money.shares > 0)) return;
        put(alias.code, alias.name, money, isUnrealizedShot ? 7 : 3);
      });

      // 未實現損益：掃「名稱 + 現股 + 股數 現價 成本價 [投資成本]」
      if (isUnrealizedShot) {
        const rowRe = /([\u4e00-\u9fffA-Za-z0-9+＋]{2,24})\s*現[股設投]\s*(\d{1,7})\s+(\d+(?:\.\d+)?)\s+(\d+(?:\.\d+)?)(?:\s+(\d+(?:\.\d+)?))?/g;
        let rm;
        while ((rm = rowRe.exec(joined))) {
          const rawName = String(rm[1] || "").replace(/下單|明細|功能|商品/g, "").trim();
          if (!rawName || noiseName.test(rawName)) continue;
          const shares = Number(rm[2]);
          if (!(shares > 0) || shares > 200000) continue;
          let code = "";
          let name = rawName;
          for (let i = 0; i < INV_ALIASES.length; i++) {
            if (INV_ALIASES[i].re.test(rawName)) {
              code = INV_ALIASES[i].code;
              name = INV_ALIASES[i].name;
              break;
            }
          }
          if (!code) continue;
          const pair = resolveCostPrice(shares, Number(rm[3]), Number(rm[4]), rm[5] != null ? Number(rm[5]) : null);
          const after = joined.slice(rm.index + rm[0].length, rm.index + rm[0].length + 80);
          const money = {
            shares: shares,
            cost: pair.cost,
            pnl: null,
            pct: null
          };
          const pctM = after.match(/([+-]?)(\d+(?:\.\d+)?)\s*%/) ||
            (rm[0] + after).match(/([+-]?)(\d+(?:\.\d+)?)\s*%/);
          if (pctM) {
            money.pct = pctM[2].indexOf(".") >= 0
              ? Number((pctM[1] === "-" ? "-" : "") + pctM[2])
              : parsePctToken(pctM[1], pctM[2]);
          }
          put(code, name, money, 8);
        }
      }

      return Object.keys(found).map(function (k) { return found[k]; });
    }

    // 多 PSM 分開解析再投票，避免串行
    const blocks = text.split(/---PSM\d*---/i).filter(function (b) { return b.trim(); });
    const vote = {};
    (blocks.length ? blocks : [text]).forEach(function (block) {
      parseBlock(block).forEach(function (row) {
        if (!vote[row.code]) vote[row.code] = [];
        vote[row.code].push(row);
      });
    });

    const rows = [];
    Object.keys(vote).forEach(function (code) {
      const list = vote[code];
      const shareCount = {};
      list.forEach(function (r) {
        shareCount[r.shares] = (shareCount[r.shares] || 0) + 1 + (r.score || 0) * 0.01;
      });
      let bestShares = list[0].shares;
      let bestN = -1;
      Object.keys(shareCount).forEach(function (s) {
        if (shareCount[s] > bestN) {
          bestN = shareCount[s];
          bestShares = Number(s);
        }
      });
      const pick = list.filter(function (r) { return r.shares === bestShares; })
        .sort(function (a, b) {
          const ca = a.cost > 0 ? 2 : 0;
          const cb = b.cost > 0 ? 2 : 0;
          return (cb + (b.score || 0)) - (ca + (a.score || 0));
        })[0] || list[0];
      // 非別名的四碼：至少要被兩個區塊看到，或分數夠高
      const known = aliasCodes[code];
      if (!known && !/[A-Z]$/.test(code) && list.length < 2 && (pick.score || 0) < 6) return;
      let cost = pick.cost;
      if (!(cost > 0)) {
        const withCost = list.find(function (r) { return r.shares === bestShares && r.cost > 0; });
        if (withCost) cost = withCost.cost;
      }
      rows.push({
        code: code,
        name: pick.name || (known ? known.name : ""),
        shares: bestShares,
        pnl: pick.pnl,
        cost: cost,
        pct: pick.pct
      });
    });

    // 未實現損益／別名持股已齊：丟掉無名雜訊代號
    const aliasHits = rows.filter(function (r) { return aliasCodes[r.code]; }).length;
    if (isUnrealizedShot || aliasHits >= 3) {
      return rows.filter(function (r) {
        return aliasCodes[r.code] || /[A-Z]$/.test(r.code);
      });
    }
    return rows;
  }

  function twStockId(secid, code) {
    const id = String(secid || "");
    const c = String(code || "").toUpperCase();
    if (id.indexOf("178.") === 0 || id.indexOf("tw.") === 0) return c || id.slice(id.indexOf(".") + 1);
    if (/^\d{4,6}[A-Z]?$/.test(c)) return c;
    return "";
  }

  function finMindToken() {
    try {
      const local = localStorage.getItem("sj-finmind-token");
      if (local) return String(local).trim();
    } catch (err) { /* ignore */ }
    return String((global.GOOGLE_CONFIG && global.GOOGLE_CONFIG.finmindToken) || "").trim();
  }

  async function finMind(dataset, stockId, start) {
    let url = "https://api.finmindtrade.com/api/v4/data?dataset=" + encodeURIComponent(dataset) +
      "&data_id=" + encodeURIComponent(stockId) + "&start_date=" + encodeURIComponent(start);
    const tok = finMindToken();
    if (tok) url += "&token=" + encodeURIComponent(tok);
    const res = await fetch(url);
    if (!res.ok) throw new Error(dataset + " 讀取失敗");
    const json = await res.json();
    return Array.isArray(json.data) ? json.data : [];
  }

  function chipTone(net, vol) {
    const r = vol > 0 ? net / vol : 0;
    if (r >= 0.08) return { label: "大買", cls: "up" };
    if (r >= 0.02) return { label: "中買", cls: "up" };
    if (r > -0.02) return { label: "中立", cls: "" };
    if (r > -0.08) return { label: "中賣", cls: "down" };
    return { label: "大賣", cls: "down" };
  }

  function rateTrend(now, prev) {
    if (now == null || prev == null || !isFinite(now) || !isFinite(prev)) return { text: "", cls: "" };
    const d = now - prev;
    if (Math.abs(d) < 0.05) return { text: "－", cls: "" };
    return d > 0 ? { text: "▲", cls: "up" } : { text: "▼", cls: "down" };
  }

  function yearEps(rows) {
    const byYear = {};
    rows.forEach(function (row) {
      if (row.type !== "EPS" || row.value == null) return;
      const y = String(row.date).slice(0, 4);
      if (!byYear[y]) byYear[y] = { year: y, sum: 0, n: 0, dates: [] };
      byYear[y].sum += Number(row.value);
      byYear[y].n += 1;
      byYear[y].dates.push(row.date);
    });
    return Object.keys(byYear).sort().map(function (y) { return byYear[y]; });
  }

  function quarterBag(rows) {
    const byDate = {};
    rows.forEach(function (row) {
      if (!byDate[row.date]) byDate[row.date] = { date: row.date };
      byDate[row.date][row.type] = num(row.value);
    });
    return Object.keys(byDate).sort().map(function (d) { return byDate[d]; });
  }

  function tickSize(price) {
    const p = Math.abs(price);
    if (p < 10) return 0.01;
    if (p < 50) return 0.05;
    if (p < 100) return 0.1;
    if (p < 500) return 0.5;
    if (p < 1000) return 1;
    return 5;
  }

  function ceilTick(price) {
    const t = tickSize(price);
    return Math.round(Math.ceil(price / t - 1e-9) * t * 10000) / 10000;
  }

  function floorTick(price) {
    const t = tickSize(price);
    return Math.round(Math.floor(price / t + 1e-9) * t * 10000) / 10000;
  }

  function formatLevelPx(price) {
    if (!(price > 0)) return "—";
    const t = tickSize(price);
    if (t >= 1) return Math.round(price).toLocaleString("zh-Hant");
    if (t >= 0.1) return price.toFixed(1);
    return price.toFixed(2);
  }

  function avgRange(bars, n) {
    const take = bars.slice(-Math.min(n, bars.length));
    if (!take.length) return 0;
    let sum = 0;
    take.forEach(function (b) { sum += Math.max((b.h || 0) - (b.l || 0), 0); });
    const avg = sum / take.length;
    return avg > 0 ? avg : tickSize(bars[bars.length - 1].c);
  }

  function pushAbove(list, close, level, why) {
    if (!(level > close)) return;
    list.push({ level: level, why: why });
  }

  function pushBelow(list, close, level, why) {
    if (!(level < close)) return;
    list.push({ level: level, why: why });
  }

  function pickNearest(cands, close, minGap, aboveClose) {
    if (!cands.length) return null;
    const far = aboveClose
      ? cands.filter(function (c) { return c.level >= close + minGap; })
      : cands.filter(function (c) { return c.level <= close - minGap; });
    const pool = far.length ? far : cands;
    return pool.reduce(function (best, cur) {
      if (!best) return cur;
      return aboveClose
        ? (cur.level < best.level ? cur : best)
        : (cur.level > best.level ? cur : best);
    }, null);
  }

  /** 與桌面版 TrendAnalyzer.FindLevels 對齊的簡化版（不含成交量輪廓）。 */
  function findLevels(bars) {
    if (!bars || bars.length < 5) return { breakout: null, support: null };
    const close = bars[bars.length - 1].c;
    const atr14 = avgRange(bars, 14);
    const minGap = Math.max(atr14 * 0.15, tickSize(close));
    const n20 = Math.min(20, bars.length);
    const n60 = Math.min(60, bars.length);
    const last20 = bars.slice(-n20);
    const last60 = bars.slice(-n60);
    let hi20 = -Infinity;
    let lo20 = Infinity;
    let hi60 = -Infinity;
    let lo60 = Infinity;
    last20.forEach(function (b) {
      hi20 = Math.max(hi20, b.h);
      lo20 = Math.min(lo20, b.l);
    });
    last60.forEach(function (b) {
      hi60 = Math.max(hi60, b.h);
      lo60 = Math.min(lo60, b.l);
    });
    const closes = closesOf(bars);
    const ma20 = sma(closes, 20);
    const ma60 = sma(closes, 60);
    const m20 = ma20[ma20.length - 1];
    const m60 = ma60[ma60.length - 1];
    const rangeLike = m20 != null && m60 != null && Math.abs(m20 - m60) / close < 0.02;
    const boxHi = rangeLike ? hi20 : hi60;
    const boxLo = rangeLike ? lo20 : lo60;
    const above = [];
    const below = [];
    pushAbove(above, close, boxHi, rangeLike ? "箱型上緣" : "近" + n60 + "日高");
    if (Math.abs(hi20 - boxHi) > minGap) pushAbove(above, close, hi20, "近" + n20 + "日高");
    if (m20 != null) pushAbove(above, close, m20, "MA20");
    if (m60 != null) pushAbove(above, close, m60, "MA60");
    pushBelow(below, close, boxLo, rangeLike ? "箱型下緣" : "近" + n60 + "日低");
    if (Math.abs(lo20 - boxLo) > minGap) pushBelow(below, close, lo20, "近" + n20 + "日低");
    if (m20 != null) pushBelow(below, close, m20, "MA20");
    if (m60 != null) pushBelow(below, close, m60, "MA60");

    let brkCand = pickNearest(above, close, minGap, true);
    let supCand = pickNearest(below, close, minGap, false);
    if (rangeLike) {
      const exactHi = above.find(function (c) { return Math.abs(c.level - boxHi) < 1e-6; });
      if (exactHi) brkCand = exactHi;
      if (close - boxLo <= Math.max(atr14 * 2.5, close * 0.08)) {
        const exactLo = below.find(function (c) { return Math.abs(c.level - boxLo) < 1e-6; });
        if (exactLo) supCand = exactLo;
      }
    }

    let breakout;
    if (brkCand) {
      let focus = ceilTick(brkCand.level + minGap);
      if (focus <= close) focus = ceilTick(close + tickSize(close));
      breakout = { focus: focus, text: formatLevelPx(focus), why: brkCand.why };
    } else {
      let focus = ceilTick(Math.max(hi20, close) + minGap);
      if (focus <= close) focus = ceilTick(close + tickSize(close));
      breakout = { focus: focus, text: formatLevelPx(focus), why: "站上近高" };
    }

    let support;
    if (supCand) {
      const half = Math.max(atr14 * 0.25, tickSize(supCand.level) * 2);
      let low = floorTick(supCand.level - half);
      let high = floorTick(Math.min(supCand.level + half, close - tickSize(close)));
      if (high < low) high = low;
      if (high >= close) {
        high = floorTick(close - tickSize(close));
        if (high < low) high = low;
      }
      const focus = Math.min(Math.max(floorTick(supCand.level), low), high);
      support = {
        low: low,
        high: high,
        focus: focus,
        focusText: formatLevelPx(focus),
        text: low === high ? formatLevelPx(low) : formatLevelPx(low) + "–" + formatLevelPx(high),
        why: supCand.why
      };
    } else {
      const half = Math.max(atr14 * 0.25, tickSize(lo20) * 2);
      let low = floorTick(lo20 - minGap);
      let high = floorTick(Math.min(lo20 + half, close - tickSize(close)));
      if (high < low) high = low;
      const focus = floorTick(lo20);
      support = {
        low: low,
        high: high,
        focus: focus,
        focusText: formatLevelPx(focus),
        text: low === high ? formatLevelPx(low) : formatLevelPx(low) + "–" + formatLevelPx(high),
        why: "近低支撐"
      };
    }
    return { breakout: breakout, support: support };
  }

  let targetsCache = null;
  let targetsCachePromise = null;

  async function loadTargetsCache() {
    if (targetsCache) return targetsCache;
    if (!targetsCachePromise) {
      targetsCachePromise = fetch("targets-cache.json")
        .then(function (res) { return res.ok ? res.json() : { items: {} }; })
        .then(function (json) {
          targetsCache = json && json.items ? json : { items: {} };
          return targetsCache;
        })
        .catch(function () {
          targetsCache = { items: {} };
          return targetsCache;
        });
    }
    return targetsCachePromise;
  }

  function parseFactsetTargets(html) {
    if (!html) return null;
    const m = String(html).match(/"targetValuation":\{[^}]+\}/);
    if (!m) return null;
    try {
      const tv = JSON.parse(m[0].slice('"targetValuation":'.length));
      const high = num(tv.feHigh);
      const mean = num(tv.feMean);
      const low = num(tv.feLow);
      if (!(high > 0) && !(mean > 0) && !(low > 0)) return null;
      return {
        high: high,
        mean: mean,
        low: low,
        median: num(tv.feMedian),
        asOf: tv.rateDate || "",
        source: "cnyes"
      };
    } catch (err) {
      return null;
    }
  }

  async function fetchCnyesTargetsLive(code) {
    const target = "https://www.cnyes.com/twstock/" + encodeURIComponent(code);
    const urls = [
      "https://api.allorigins.win/raw?url=" + encodeURIComponent(target),
      "https://api.codetabs.com/v1/proxy?quest=" + encodeURIComponent(target),
      "https://corsproxy.io/?" + encodeURIComponent(target)
    ];
    for (let i = 0; i < urls.length; i++) {
      try {
        const ctrl = typeof AbortController !== "undefined" ? new AbortController() : null;
        const timer = ctrl ? setTimeout(function () { ctrl.abort(); }, 9000) : 0;
        const res = await fetch(urls[i], ctrl ? { signal: ctrl.signal } : undefined);
        if (timer) clearTimeout(timer);
        if (!res.ok) continue;
        const text = await res.text();
        const hit = parseFactsetTargets(text);
        if (hit) return hit;
      } catch (err) { /* 下一個代理 */ }
    }
    return null;
  }

  async function foreignTargets(code) {
    const id = String(code || "").toUpperCase();
    if (!id) return null;
    const cache = await loadTargetsCache();
    const hit = cache.items && cache.items[id];
    if (hit && (hit.high > 0 || hit.mean > 0 || hit.low > 0)) {
      return {
        high: num(hit.high),
        mean: num(hit.mean),
        low: num(hit.low),
        median: num(hit.median),
        asOf: hit.asOf || "",
        source: "cache"
      };
    }
    const live = await fetchCnyesTargetsLive(id);
    if (live) {
      if (!cache.items) cache.items = {};
      cache.items[id] = live;
    }
    return live;
  }

  async function dayBarsForLevels(secid, code) {
    const stockId = twStockId(secid, code);
    if (stockId) {
      const rows = await finMind("TaiwanStockPrice", stockId, isoDaysAgo(140)).catch(function () { return []; });
      const out = rows.map(function (row) {
        return {
          t: row.date,
          o: num(row.open),
          c: num(row.close),
          h: num(row.max),
          l: num(row.min),
          v: num(row.Trading_Volume) || 0
        };
      }).filter(function (b) { return b.c != null && b.c > 0 && b.h != null && b.l != null; });
      if (out.length >= 5) return out;
    }
    if (String(secid || "").indexOf("tw.") === 0 || String(secid || "").indexOf("fx.") === 0) return [];
    const em = await kline(secid, 101, 80).catch(function () { return []; });
    return em.length >= 5 ? em : [];
  }

  const watchLevelCache = {};
  const WATCH_LEVEL_TTL = 15 * 60 * 1000;

  async function watchLevels(items) {
    const list = items || [];
    if (!list.length) return [];
    return mapPool(list, 3, async function (item) {
      const key = String((item && (item.code || item.secid)) || "").toUpperCase();
      if (!key) return { breakout: null, support: null };
      const hit = watchLevelCache[key];
      if (hit && Date.now() - hit.at < WATCH_LEVEL_TTL) {
        return { breakout: hit.breakout, support: hit.support };
      }
      try {
        const bars = await dayBarsForLevels(item && item.secid, item && item.code);
        const levels = findLevels(bars);
        watchLevelCache[key] = {
          at: Date.now(),
          breakout: levels.breakout,
          support: levels.support
        };
        return levels;
      } catch (err) {
        return { breakout: null, support: null };
      }
    });
  }

  async function watchMetrics(item) {
    const secid = item && item.secid;
    const code = item && item.code;
    const stockId = twStockId(secid, code);
    const empty = {
      name: toTW(item && item.name || ""),
      price: null,
      change: null,
      pct: null,
      open: null,
      high: null,
      low: null,
      ref: null,
      avg: null,
      amplitude: null,
      volumeLots: null,
      limitUp: null,
      limitDown: null,
      pe: null,
      targetHigh: null,
      targetMean: null,
      targetLow: null,
      breakout: null,
      support: null
    };
    if (!secid) return empty;
    const jobs = [
      quoteMap([secid]).catch(function () { return {}; }),
      stockId ? cnyesQuotes([stockId]).catch(function () { return {}; }) : Promise.resolve({}),
      stockId
        ? finMind("TaiwanStockPER", stockId, isoDaysAgo(40)).catch(function () { return []; })
        : Promise.resolve([]),
      dayBarsForLevels(secid, code),
      stockId ? foreignTargets(stockId) : Promise.resolve(null)
    ];
    const got = await Promise.all(jobs);
    const q = got[0][secid] || null;
    const board = stockId && got[1][stockId] ? got[1][stockId] : null;
    const pers = got[2];
    const dayBars = got[3];
    const targets = got[4];
    const per = pers.length ? num(pers[pers.length - 1].PER) : null;
    const levels = findLevels(dayBars);
    const src = board || q || {};
    return {
      name: toTW(src.name || (item && item.name) || code || ""),
      price: src.price != null ? src.price : null,
      change: src.change != null ? src.change : (src.price != null && src.pct != null ? src.price * src.pct / (100 + src.pct) : null),
      pct: src.pct != null ? src.pct : null,
      open: src.open != null ? src.open : null,
      high: src.high != null ? src.high : null,
      low: src.low != null ? src.low : null,
      ref: src.ref != null ? src.ref : null,
      avg: src.avg != null ? src.avg : null,
      amplitude: src.amplitude != null ? src.amplitude : null,
      volumeLots: src.volumeLots != null ? src.volumeLots : null,
      limitUp: src.limitUp != null ? src.limitUp : null,
      limitDown: src.limitDown != null ? src.limitDown : null,
      pe: per,
      targetHigh: targets ? targets.high : null,
      targetMean: targets ? targets.mean : null,
      targetLow: targets ? targets.low : null,
      breakout: levels.breakout,
      support: levels.support
    };
  }

  // ── TWSE MIS 基本市況報導（約 5 秒快照；本站每 10 秒問一次）────────
  const MIS_MIN_GAP_MS = 10000;
  const MIS_CACHE_MS = 10000;
  // 台灣 08:00～14:00：強制只用 MIS，抓不到就間隔重試，不改走 Yahoo／鉅亨
  const MIS_FORCE_RETRY_MS = 3500;
  const MIS_FORCE_ATTEMPTS = 4;
  const misQuoteCache = new Map();
  const misExHint = Object.create(null);
  let misLastFetchAt = 0;
  let misQueue = Promise.resolve();
  // 登入後：雲端硬碟只保留最新一筆 MIS 快照，多裝置共用、少打證交所
  const MIS_DRIVE_MAX_AGE_MS = 25000;
  // 盤後／剛登入：仍可用較舊快照先填自選成交價（最多 7 天）
  const MIS_DRIVE_SEED_MAX_AGE_MS = 7 * 86400000;
  const MIS_DRIVE_WRITE_GAP_MS = 12000;
  const MIS_DRIVE_READ_GAP_MS = 8000;
  let misDriveSnap = null;
  let misDriveReadAt = 0;
  let misDriveWriteAt = 0;
  let misDriveWriteTimer = 0;
  let misDriveWriteBusy = false;

  function misDriveApi() {
    const D = global.SJDrive;
    if (!D || !D.account || !D.account()) return null;
    if (D.isAllowed && !D.isAllowed((D.account().email) || "")) return null;
    if (!D.readMisSnapshot || !D.writeMisSnapshot) return null;
    return D;
  }

  function fubonDriveApi() {
    const D = global.SJDrive;
    if (!D || !D.account || !D.account()) return null;
    if (D.isAllowed && !D.isAllowed((D.account().email) || "")) return null;
    if (!D.readFubonLive) return null;
    return D;
  }

  function fubonLiveBridgeApi() {
    const B = global.SJLiveBridge;
    if (!B || !B.readFubonLive) return null;
    // 報價／分時：有 Tailscale URL 即可（免 Google）；庫存仍走 canUse
    const reach = !!(B.canReach && B.canReach());
    const auth = !!(B.canUse && B.canUse());
    if (!reach && !auth) return null;
    return B;
  }

  const FUBON_DRIVE_MAX_AGE_MS = 60_000;
  const FUBON_DRIVE_SEED_MAX_AGE_MS = 30 * 60_000;
  const TW_QUOTE_SRC_KEY = "sj-twii-source";
  let fubonDriveSnap = null;
  let fubonDriveReadAt = 0;

  /** 與頁首加權來源同步：選富邦時台股報價／足跡優先 Live Bridge */
  function preferFubonQuotes() {
    try {
      return String(localStorage.getItem(TW_QUOTE_SRC_KEY) || "").toLowerCase() === "fubon";
    } catch (err) {
      return false;
    }
  }

  function slimFubonQuote(q, sourceTag) {
    if (!q || !(q.price > 0)) return null;
    return {
      code: q.code || "",
      name: q.name || "",
      price: q.price,
      change: q.change,
      pct: q.pct,
      open: q.open,
      high: q.high,
      low: q.low,
      ref: q.ref,
      bid: q.bid,
      ask: q.ask,
      volumeLots: q.volumeLots,
      asOf: q.asOf,
      tradeTime: q.asOf || "",
      source: sourceTag || "fubon-drive"
    };
  }

  function applyFubonDriveSnap(snap, preferAgeMs, sourceTag, opts) {
    opts = opts || {};
    if (!snap || !snap.byCode || typeof snap.byCode !== "object") return 0;
    const age = snap.at != null ? Date.now() - Number(snap.at) : Infinity;
    if (!(age >= 0) || age > (preferAgeMs != null ? preferAgeMs : FUBON_DRIVE_MAX_AGE_MS)) return 0;
    const cacheAt = Number(snap.at) || Date.now();
    const tag = sourceTag || "fubon-drive";
    const forceOverwrite = !!opts.forceOverwrite;
    let n = 0;
    Object.keys(snap.byCode).forEach(function (code) {
      const id = String(code || "").toUpperCase();
      const q = slimFubonQuote(snap.byCode[code], tag);
      if (!id || !q) return;
      q.code = id;
      const hit = misQuoteCache.get(id);
      // 選富邦時強制覆寫 MIS；否則僅富邦較新才覆寫
      if (!forceOverwrite) {
        if (hit && !hit.fromDrive && hit.at >= cacheAt) return;
        if (hit && hit.fromFubonDrive && hit.at >= cacheAt) return;
      }
      misQuoteCache.set(id, { at: cacheAt, quote: q, fromDrive: true, fromFubonDrive: true });
      n += 1;
    });
    fubonDriveSnap = snap;
    return n;
  }

  async function hydrateFubonFromDrive(needIds, opts) {
    opts = opts || {};
    if (!(needIds && needIds.length)) return 0;
    const now = Date.now();
    const applyOpts = { forceOverwrite: !!(opts.forceOverwrite || preferFubonQuotes()) };
    if (!opts.force && now - fubonDriveReadAt < 5000 && fubonDriveSnap) {
      return applyFubonDriveSnap(
        fubonDriveSnap,
        opts.maxAgeMs || FUBON_DRIVE_MAX_AGE_MS,
        null,
        applyOpts
      );
    }
    fubonDriveReadAt = now;

    // 優先 Tailscale Live Bridge，其次 Google Drive（已知離線則跳過橋，避免手機卡住）
    const B = fubonLiveBridgeApi();
    const bridgeKnown = B && B.isOnline ? B.isOnline() : null;
    if (B && bridgeKnown !== false) {
      try {
        const snap = await B.readFubonLive();
        if (snap) {
          return applyFubonDriveSnap(
            snap,
            opts.maxAgeMs || FUBON_DRIVE_MAX_AGE_MS,
            "fubon-tailscale",
            applyOpts
          );
        }
      } catch (err) { /* fall through */ }
    }

    const D = fubonDriveApi();
    if (!D) return 0;
    try {
      const snap = await D.readFubonLive();
      if (!snap) return 0;
      return applyFubonDriveSnap(
        snap,
        opts.maxAgeMs || FUBON_DRIVE_MAX_AGE_MS,
        "fubon-drive",
        applyOpts
      );
    } catch (err) {
      return 0;
    }
  }

  async function fetchFubonTapeFromDrive(code, dateYmd) {
    function usable(tape) {
      return !!(tape && Array.isArray(tape.ticks) && tape.ticks.length >= 4);
    }
    const B = fubonLiveBridgeApi();
    const D = fubonDriveApi();
    const bridgeKnownOnline = B && B.isOnline ? B.isOnline() : null;
    // 手機常連不到 Tailscale：已知離線或未知時先／並行打 Drive，避免卡死
    const driveFirst = bridgeKnownOnline === false;

    async function fromBridge() {
      if (!B || !B.readFubonTape) return null;
      if (bridgeKnownOnline === false) return null;
      try {
        const tape = await B.readFubonTape(code, dateYmd);
        return usable(tape) ? tape : null;
      } catch (err) {
        return null;
      }
    }
    async function fromDrive() {
      if (!D || !D.readFubonTape) return null;
      try {
        const tape = await D.readFubonTape(code, dateYmd);
        return usable(tape) ? tape : null;
      } catch (err) {
        return null;
      }
    }

    if (driveFirst) {
      const d = await fromDrive();
      if (d) return d;
      return fromBridge();
    }
    if (B && D) {
      const pair = await Promise.all([fromBridge(), fromDrive()]);
      if (usable(pair[0])) return pair[0];
      if (usable(pair[1])) return pair[1];
      return null;
    }
    return (await fromBridge()) || (await fromDrive());
  }

  function slimMisQuote(q) {
    if (!q || !(q.price > 0)) return null;
    return {
      code: q.code || "",
      name: q.name || "",
      price: q.price,
      change: q.change,
      pct: q.pct,
      open: q.open,
      high: q.high,
      low: q.low,
      ref: q.ref,
      limitUp: q.limitUp,
      limitDown: q.limitDown,
      volumeLots: q.volumeLots,
      asOf: q.asOf,
      source: "mis"
    };
  }

  function applyMisDriveSnap(snap, preferAgeMs, opts) {
    opts = opts || {};
    if (!snap || !snap.byCode || typeof snap.byCode !== "object") return 0;
    const age = snap.at != null ? Date.now() - Number(snap.at) : Infinity;
    if (!(age >= 0) || age > (preferAgeMs != null ? preferAgeMs : MIS_DRIVE_MAX_AGE_MS)) return 0;
    const freshen = !!opts.freshen;
    const cacheAt = freshen ? Date.now() : (Number(snap.at) || Date.now());
    let n = 0;
    Object.keys(snap.byCode).forEach(function (code) {
      const id = String(code || "").toUpperCase();
      const q = slimMisQuote(snap.byCode[code]);
      if (!id || !q) return;
      q.code = id;
      if (!freshen) q.source = q.source || "mis-drive";
      else q.source = "mis-drive";
      const hit = misQuoteCache.get(id);
      // 本機有更新的 MIS 就保留；灌種時可覆寫過期快取
      if (hit && !hit.fromDrive && hit.at >= cacheAt) return;
      if (hit && hit.fromDrive && hit.at >= Number(snap.at) && !freshen) return;
      misQuoteCache.set(id, { at: cacheAt, quote: q, fromDrive: true });
      n += 1;
    });
    misDriveSnap = snap;
    return n;
  }

  async function hydrateMisFromDrive(needIds, opts) {
    opts = opts || {};
    const D = misDriveApi();
    if (!D || !(needIds && needIds.length)) return 0;
    const now = Date.now();
    const forceWindow = isMisForceWindow();
    const maxAge = opts.maxAgeMs != null
      ? opts.maxAgeMs
      : (forceWindow ? MIS_DRIVE_MAX_AGE_MS : MIS_DRIVE_SEED_MAX_AGE_MS);
    const freshen = opts.freshen != null ? !!opts.freshen : !forceWindow;
    const forceRead = !!opts.force;

    function missing() {
      return needIds.some(function (id) {
        const hit = misQuoteCache.get(String(id || "").toUpperCase());
        return !(hit && hit.quote && hit.quote.price > 0);
      });
    }

    if (misDriveSnap) {
      applyMisDriveSnap(misDriveSnap, maxAge, { freshen: freshen });
      if (!missing()) return needIds.length;
    }
    if (!forceRead && now - misDriveReadAt < MIS_DRIVE_READ_GAP_MS && misDriveSnap) {
      applyMisDriveSnap(misDriveSnap, maxAge, { freshen: freshen });
      return missing() ? 0 : needIds.length;
    }
    misDriveReadAt = now;
    try {
      const snap = await withTimeout(D.readMisSnapshot(), 4000);
      if (snap) return applyMisDriveSnap(snap, maxAge, { freshen: freshen });
    } catch (err) { /* 雲端慢就改打 MIS */ }
    return 0;
  }

  function scheduleMisDriveWrite() {
    const D = misDriveApi();
    if (!D) return;
    if (misDriveWriteTimer) clearTimeout(misDriveWriteTimer);
    misDriveWriteTimer = setTimeout(function () {
      misDriveWriteTimer = 0;
      flushMisDriveWrite();
    }, 600);
  }

  async function flushMisDriveWrite() {
    const D = misDriveApi();
    if (!D || misDriveWriteBusy) return;
    const now = Date.now();
    if (now - misDriveWriteAt < MIS_DRIVE_WRITE_GAP_MS) return;
    const byCode = {};
    let newest = 0;
    misQuoteCache.forEach(function (hit, code) {
      if (!hit || !hit.quote || !(hit.quote.price > 0)) return;
      // 只上傳本機剛從 MIS 抓到的，避免把過舊雲端資料再寫回去循環
      if (hit.fromDrive && now - hit.at > MIS_CACHE_MS) return;
      if (hit.fromDrive) return;
      const slim = slimMisQuote(hit.quote);
      if (!slim) return;
      byCode[code] = slim;
      if (hit.at > newest) newest = hit.at;
    });
    if (!Object.keys(byCode).length) return;
    // 與雲端舊快照合併：同一檔覆寫、其餘保留（多裝置不同自選）
    let merged = byCode;
    if (misDriveSnap && misDriveSnap.byCode) {
      merged = Object.assign({}, misDriveSnap.byCode, byCode);
    }
    const payload = {
      at: newest || now,
      byCode: merged,
      source: "mis"
    };
    misDriveWriteBusy = true;
    misDriveWriteAt = now;
    try {
      await D.writeMisSnapshot(payload);
      misDriveSnap = payload;
    } catch (err) { /* 寫入失敗不影響行情 */ }
    misDriveWriteBusy = false;
  }

  function taipeiMinutesNow(now) {
    const parts = new Intl.DateTimeFormat("en-US", {
      timeZone: "Asia/Taipei",
      hour: "2-digit",
      minute: "2-digit",
      hour12: false
    }).formatToParts(now || new Date());
    const map = {};
    parts.forEach(function (p) { if (p.type !== "literal") map[p.type] = p.value; });
    return Number(map.hour) * 60 + Number(map.minute);
  }

  function isMisForceWindow(now) {
    const mins = taipeiMinutesNow(now);
    return mins >= 8 * 60 && mins < 14 * 60;
  }

  function misBoardHasPrice(board, codes) {
    const ids = (codes || []).map(function (c) {
      return String(c || "").toUpperCase();
    }).filter(Boolean);
    if (!ids.length) return false;
    for (let i = 0; i < ids.length; i++) {
      const q = board && board[ids[i]];
      if (q && q.price > 0) return true;
    }
    return false;
  }

  async function misQuotesForced(codes, opts) {
    opts = opts || {};
    const attempts = Math.max(1, opts.attempts != null ? opts.attempts : MIS_FORCE_ATTEMPTS);
    const gap = opts.gapMs != null ? opts.gapMs : MIS_FORCE_RETRY_MS;
    const requireAll = !!opts.requireAll;
    const ids = [];
    (codes || []).forEach(function (c) {
      const id = String(c || "").toUpperCase();
      if (id && ids.indexOf(id) < 0) ids.push(id);
    });
    let last = {};
    for (let i = 0; i < attempts; i++) {
      try {
        last = await misQuotes(ids);
      } catch (err) {
        last = last || {};
      }
      if (ids.length) {
        const hit = ids.filter(function (id) {
          return last[id] && last[id].price > 0;
        }).length;
        if (requireAll ? hit >= ids.length : hit > 0) return last;
      } else if (misBoardHasPrice(last, ids)) {
        return last;
      }
      if (i < attempts - 1) await sleep(gap);
    }
    return last;
  }

  function misNum(raw) {
    const s = String(raw == null ? "" : raw).trim();
    if (!s || s === "-" || s === "--") return null;
    return num(s.replace(/,/g, ""));
  }

  function misAsOf(row) {
    const tl = num(row && row.tlong);
    if (tl != null && Math.abs(Date.now() - tl) < 172800000) return tl;
    const d = String((row && row.d) || "").replace(/\D/g, "");
    const t = String((row && row.t) || "00:00:00").trim();
    if (d.length !== 8) return null;
    const iso = d.slice(0, 4) + "-" + d.slice(4, 6) + "-" + d.slice(6, 8) + "T" +
      (t.length >= 8 ? t : (t + ":00").slice(0, 8)) + "+08:00";
    const ms = Date.parse(iso);
    return isFinite(ms) ? ms : null;
  }

  function misLastPrice(row) {
    let z = misNum(row && row.z);
    if (z == null && row && row.trade && typeof row.trade === "object") z = misNum(row.trade.z);
    if (z != null) return z;
    const bid = String((row && row.b) || "").split("_").map(misNum).filter(function (v) { return v != null; })[0];
    const ask = String((row && row.a) || "").split("_").map(misNum).filter(function (v) { return v != null; })[0];
    if (bid != null && ask != null) return (bid + ask) / 2;
    if (bid != null) return bid;
    if (ask != null) return ask;
    return misNum(row && row.y);
  }

  function misSplitNums(raw) {
    return String(raw == null ? "" : raw).split("_").map(misNum).filter(function (v) {
      return v != null && isFinite(v);
    });
  }

  function misBookLevels(prices, sizes, n) {
    const out = [];
    const lim = n || 5;
    for (let i = 0; i < lim; i++) {
      const p = prices[i];
      if (!(p > 0)) break;
      out.push({ price: p, size: sizes[i] != null ? sizes[i] : null });
    }
    return out;
  }

  function parseMisRow(row) {
    if (!row) return null;
    const code = String(row.c || "").toUpperCase();
    if (!code) return null;
    const ref = misNum(row.y);
    const price = misLastPrice(row);
    if (!(price > 0) && !(ref > 0)) return null;
    const px = price > 0 ? price : ref;
    const change = (px != null && ref > 0) ? px - ref : null;
    const pct = (change != null && ref > 0) ? change / ref * 100 : null;
    const high = misNum(row.h);
    const low = misNum(row.l);
    const open = misNum(row.o);
    const amplitude = (high != null && low != null && ref > 0) ? (high - low) / ref * 100 : null;
    const ex = String(row.ex || "").toLowerCase();
    if (ex === "tse" || ex === "otc") misExHint[code] = ex;
    const askPx = misSplitNums(row.a);
    const askSz = misSplitNums(row.f);
    const bidPx = misSplitNums(row.b);
    const bidSz = misSplitNums(row.g);
    return {
      secid: code === "T00" ? "100.TWII" : ("tw." + code),
      code: code,
      name: toTW(row.n || code),
      price: px,
      change: change,
      pct: pct,
      open: open,
      high: high,
      low: low,
      ref: ref,
      limitUp: misNum(row.u),
      limitDown: misNum(row.w),
      volumeLots: misNum(row.v),
      lastLot: misNum(row.tv),
      tradeTime: String(row.t || "").trim() || null,
      asks: misBookLevels(askPx, askSz, 5),
      bids: misBookLevels(bidPx, bidSz, 5),
      amount: null,
      avg: null,
      amplitude: amplitude,
      pe: null,
      cap: null,
      pb: null,
      asOf: misAsOf(row),
      delayMin: 0,
      source: "mis",
      ex: ex || null
    };
  }

  async function misBook(code) {
    const id = String(code || "").trim().toUpperCase();
    if (!id) return null;
    const board = await misQuotes([id]);
    return board[id] || null;
  }

  // 分價量：用當日 1 分 K 量價近似（非逐筆撮合）；盤中可再疊 MIS 成交累積
  async function stockPriceVolume(code) {
    const id = String(code || "").trim().toUpperCase();
    if (!id) return { ok: false, rows: [], open: null, high: null, low: null, price: null };
    const symbols = [id + ".TW", id + ".TWO"];
    let bars = [];
    let meta = null;
    for (let i = 0; i < symbols.length; i++) {
      try {
        const json = await yahooChart(symbols[i], "interval=1m&range=1d");
        const result = json && json.chart && json.chart.result && json.chart.result[0];
        if (!result) continue;
        meta = result.meta || {};
        const q = ((result.indicators || {}).quote || [])[0] || {};
        const closes = q.close || [];
        const vols = q.volume || [];
        for (let j = 0; j < closes.length; j++) {
          const px = num(closes[j]);
          const vol = num(vols[j]);
          if (!(px > 0) || !(vol > 0)) continue;
          bars.push({ price: px, lots: vol / 1000 });
        }
        if (bars.length) break;
      } catch (err) { /* next symbol */ }
    }
    const map = Object.create(null);
    bars.forEach(function (b) {
      const key = String(Math.round(b.price * 100) / 100);
      map[key] = (map[key] || 0) + b.lots;
    });
    const rows = Object.keys(map).map(function (k) {
      return { price: Number(k), lots: Math.round(map[k] * 10) / 10 };
    }).sort(function (a, b) { return b.price - a.price; });
    return {
      ok: !!rows.length,
      rows: rows,
      open: meta ? num(meta.regularMarketOpen || meta.chartPreviousClose) : null,
      high: meta ? num(meta.regularMarketDayHigh) : null,
      low: meta ? num(meta.regularMarketDayLow) : null,
      price: meta ? num(meta.regularMarketPrice) : null,
      source: "yahoo1m"
    };
  }

  /** 解析 MIS 成交時間 → 當日秒數 */
  function tapeTimeSec(raw) {
    const s = String(raw == null ? "" : raw).trim();
    if (!s) return null;
    const colon = s.match(/^(\d{1,2}):(\d{2})(?::(\d{2}))?/);
    if (colon) {
      return Number(colon[1]) * 3600 + Number(colon[2]) * 60 + Number(colon[3] || 0);
    }
    const digits = s.replace(/\D/g, "");
    if (digits.length >= 6) {
      return Number(digits.slice(0, 2)) * 3600 + Number(digits.slice(2, 4)) * 60 + Number(digits.slice(4, 6));
    }
    if (digits.length === 4) {
      return Number(digits.slice(0, 2)) * 3600 + Number(digits.slice(2, 4)) * 60;
    }
    return null;
  }

  function inTapeWindow(sec, h0, m0, h1, m1) {
    if (sec == null) return false;
    const a = h0 * 3600 + m0 * 60;
    const b = h1 * 3600 + m1 * 60;
    return sec >= a && sec <= b;
  }

  function isRoundLot(lots) {
    const n = Math.round(Number(lots) || 0);
    return n >= 20 && n % 10 === 0;
  }

  function isOddishLot(lots) {
    const n = Math.round(Number(lots) || 0);
    if (n < 2 || n > 40) return false;
    if (n % 10 === 0 || n % 5 === 0) return false;
    return true;
  }

  /**
   * 依分時成交（張數／時間／價位推升）近似判讀參與者。
   * 非真實歸戶；僅規則試算。
   * ticks: [{ time, price, lots, change }]
   * ctx: { pct, limitUp, price, ref }
   */
  function analyzeTapeActors(tape, ctx) {
    ctx = ctx || {};
    const raw = (tape || []).filter(function (t) {
      return t && Number(t.lots) > 0 && t.price > 0;
    });
    if (raw.length < 4) {
      return {
        ok: false,
        reason: "成交明細不足（盤中刷新會累積）",
        sample: raw.length,
        actors: [],
        signals: [],
        note: "需至少數筆分時成交才能近似判讀；非券商分點歸戶。"
      };
    }

    const ticks = [];
    for (let i = 0; i < raw.length; i++) {
      const t = raw[i];
      // 保留小數張（零股／1 分Ｋ合成）；勿先四捨五入成 0
      const lots = Math.round(Number(t.lots) * 1000) / 1000;
      if (!(lots > 0)) continue;
      const prev = ticks.length ? ticks[ticks.length - 1] : null;
      let side = 0;
      if (prev && t.price > prev.price + 1e-9) side = 1;
      else if (prev && t.price < prev.price - 1e-9) side = -1;
      else if (t.change != null && isFinite(t.change)) {
        side = t.change > 0 ? 1 : t.change < 0 ? -1 : 0;
      }
      ticks.push({
        time: t.time || "",
        sec: tapeTimeSec(t.time),
        price: Number(t.price),
        lots: lots,
        side: side,
        change: t.change
      });
    }

    const n = ticks.length;
    const scores = {
      overnight: 0,
      daytrade: 0,
      trust: 0,
      foreign: 0,
      dealer: 0
    };
    const evidence = {
      overnight: [],
      daytrade: [],
      trust: [],
      foreign: [],
      dealer: []
    };
    function bump(key, pts, line) {
      scores[key] += pts;
      if (line && evidence[key].length < 4) evidence[key].push(line);
    }

    const lotFreq = Object.create(null);
    ticks.forEach(function (t) {
      const rounded = t.lots >= 1 ? Math.round(t.lots) : Math.round(t.lots * 10) / 10;
      const k = String(rounded);
      lotFreq[k] = (lotFreq[k] || 0) + 1;
    });
    const topLots = Object.keys(lotFreq).map(function (k) {
      return { lots: Number(k), count: lotFreq[k] };
    }).sort(function (a, b) { return b.count - a.count || b.lots - a.lots; });

    // 固定張數 + 固定間隔 → 程式拆單（外資／投信）
    let algoHits = 0;
    let trustish = 0;
    let foreignish = 0;
    for (let i = 0; i < topLots.length && i < 5; i++) {
      const row = topLots[i];
      if (row.count < 3) continue;
      const same = ticks.filter(function (t) { return Math.round(t.lots) === row.lots && t.sec != null; });
      if (same.length < 3) continue;
      const gaps = [];
      for (let j = 1; j < same.length; j++) gaps.push(same[j].sec - same[j - 1].sec);
      const validGaps = gaps.filter(function (g) { return g > 0 && g <= 180; });
      if (validGaps.length < 2) continue;
      const avg = validGaps.reduce(function (s, g) { return s + g; }, 0) / validGaps.length;
      const mad = validGaps.reduce(function (s, g) { return s + Math.abs(g - avg); }, 0) / validGaps.length;
      if (avg >= 8 && avg <= 90 && mad <= Math.max(4, avg * 0.35)) {
        algoHits += 1;
        const line = "每隔約 " + Math.round(avg) + " 秒出現 " + row.lots + " 張（" + row.count + " 筆）";
        if (isRoundLot(row.lots)) {
          trustish += 1;
          bump("trust", 18, line);
        } else {
          foreignish += 1;
          bump("foreign", 20, line);
        }
      } else if (row.count >= 5 && (row.lots === 13 || row.lots === 17 || row.lots === 24 ||
        row.lots === 48 || row.lots === 26 || row.lots === 36 || (row.lots > 10 && row.lots % 10 !== 0))) {
        foreignish += 1;
        bump("foreign", 12, "反覆出現固定 " + row.lots + " 張（" + row.count + " 筆）");
      }
    }
    if (algoHits >= 1) bump("foreign", 6, "疑似 TWAP／時間加權拆單");

    // 499／大單鎖碼
    const bigBuys = ticks.filter(function (t) { return t.lots >= 100 && t.side >= 0; });
    const huge = ticks.filter(function (t) { return t.lots >= 200; });
    const nearLimit = (ctx.pct != null && ctx.pct >= 8) ||
      (ctx.limitUp != null && ctx.price != null && ctx.limitUp > 0 &&
        ctx.price >= ctx.limitUp * 0.995);
    if (nearLimit && bigBuys.length >= 2) {
      bump("overnight", 28, "近漲停連續大單敲進（" + bigBuys.length + " 筆≥100張）");
    }
    if (huge.some(function (t) { return t.lots >= 400; })) {
      bump("foreign", 10, "出現接近單筆上限之大單");
      bump("overnight", 8, "巨量鎖碼跡象");
    }

    // 散戶隔日沖：1～10 張、尾盤外盤／早盤內盤
    let smallBuyPm = 0;
    let smallSellAm = 0;
    let smallN = 0;
    ticks.forEach(function (t) {
      if (t.lots > 10) return;
      smallN += 1;
      if (t.side > 0 && inTapeWindow(t.sec, 13, 0, 13, 25)) smallBuyPm += 1;
      if (t.side < 0 && inTapeWindow(t.sec, 9, 0, 9, 20)) smallSellAm += 1;
    });
    if (smallN >= Math.max(3, n * 0.35)) {
      bump("overnight", 10, "以 1～10 張零碎單為主");
    }
    if (smallBuyPm >= 2) bump("overnight", 14, "尾盤零碎外盤追價");
    if (smallSellAm >= 2) bump("overnight", 12, "開盤零碎內盤倒貨");

    // 當沖：整數倍大單急拉急殺、早盤／尾盤平倉
    let roundBig = 0;
    let flip = 0;
    for (let i = 1; i < ticks.length; i++) {
      if (ticks[i].side && ticks[i - 1].side && ticks[i].side !== ticks[i - 1].side) flip += 1;
    }
    ticks.forEach(function (t) {
      const L = Math.round(t.lots);
      if ((L === 30 || L === 50 || L === 100 || L === 150 || L === 200) ||
        (L >= 30 && L <= 100 && L % 10 === 0)) {
        if (inTapeWindow(t.sec, 9, 0, 10, 30) || inTapeWindow(t.sec, 12, 30, 13, 25)) roundBig += 1;
      }
    });
    if (roundBig >= 2) bump("daytrade", 16, "常見 30～100 張整數單");
    if (flip >= Math.max(3, Math.floor(n * 0.25))) {
      bump("daytrade", 14, "內外盤頻繁切換（急拉急殺）");
    }
    let lateSell = 0;
    ticks.forEach(function (t) {
      if (t.side < 0 && t.lots >= 5 && t.lots <= 30 && inTapeWindow(t.sec, 12, 45, 13, 25)) lateSell += 1;
    });
    if (lateSell >= 3) bump("daytrade", 18, "尾盤連續 5～30 張內盤（疑似強制平倉）");

    // 點火＋避險跟單
    for (let i = 0; i < ticks.length - 3; i++) {
      let run = 0;
      for (let j = i; j < Math.min(i + 5, ticks.length); j++) {
        const L = Math.round(ticks[j].lots);
        if (ticks[j].side > 0 && (L === 50 || L === 100 || L === 200 || (L >= 50 && L % 50 === 0))) run += 1;
        else break;
      }
      if (run >= 3) {
        bump("daytrade", 12, "連續大單外盤點火");
        let follow = 0;
        for (let k = i + run; k < Math.min(i + run + 6, ticks.length); k++) {
          if (ticks[k].side > 0 && isOddishLot(ticks[k].lots)) follow += 1;
        }
        if (follow >= 2) bump("dealer", 16, "大單後緊接零碎跟單（疑似權證避險）");
        break;
      }
    }

    // 自營：零碎張數高頻
    const oddN = ticks.filter(function (t) { return isOddishLot(t.lots); }).length;
    if (oddN >= Math.max(4, n * 0.3)) {
      bump("dealer", 10, "非整數零碎張數偏多");
    }

    // 投信：避開開盤亂流、整數單、偏內盤承接
    let trustBuy = 0;
    ticks.forEach(function (t) {
      if (!isRoundLot(t.lots)) return;
      if (inTapeWindow(t.sec, 9, 30, 13, 0) && t.side <= 0) trustBuy += 1;
    });
    if (trustBuy >= 2) bump("trust", 12, "整數張數偏內盤／均價附近承接");
    if (trustish === 0 && isRoundLot(topLots[0] && topLots[0].lots) && (topLots[0].count || 0) >= 4) {
      bump("trust", 8, "反覆整數張數 " + topLots[0].lots + " 張");
    }

    const meta = [
      { key: "overnight", name: "散戶隔日沖", cls: "up" },
      { key: "daytrade", name: "當沖客", cls: "up" },
      { key: "trust", name: "投信", cls: "down" },
      { key: "foreign", name: "外資／程式", cls: "down" },
      { key: "dealer", name: "自營避險", cls: "" }
    ];
    const maxScore = meta.reduce(function (m, row) { return Math.max(m, scores[row.key]); }, 0);
    const actors = meta.map(function (row) {
      const sc = scores[row.key];
      let level = "弱";
      let tone = "";
      if (sc >= 28 || (maxScore > 0 && sc >= maxScore && sc >= 18)) {
        level = "強";
        tone = row.cls || "up";
      } else if (sc >= 14) {
        level = "中";
        tone = row.cls || "";
      }
      return {
        key: row.key,
        name: row.name,
        score: sc,
        level: level,
        tone: tone,
        active: sc >= 14,
        detail: (evidence[row.key] || []).join("；") || "特徵不足"
      };
    }).sort(function (a, b) { return b.score - a.score; });

    const signals = [];
    actors.filter(function (a) { return a.active; }).forEach(function (a) {
      signals.push(a.name + "（" + a.level + "）：" + a.detail);
    });
    if (!signals.length) {
      signals.push("目前累積樣本偏中性，尚無單一參與者特徵突出。");
    }

    const lead = actors[0];
    const bias = lead && lead.active
      ? ("偏 " + lead.name)
      : "足跡不明顯";

    const brief = buildTapeSessionBrief(ticks, ctx, {
      actors: actors,
      topLots: topLots,
      vwapHint: null
    });

    return {
      ok: true,
      sample: n,
      bias: bias,
      actors: actors,
      signals: signals,
      topLots: topLots.slice(0, 5),
      brief: brief,
      note: "依單筆張數規律、成交時段、價位推升／壓低近似判讀；非真實分點歸戶，規則試算非投資建議。"
    };
  }

  /**
   * 類似盤後敘事分析：時段對照、參與者推演、驗證建議。
   * 僅行為推論，非歸戶。
   */
  function buildTapeSessionBrief(ticks, ctx, pack) {
    ctx = ctx || {};
    pack = pack || {};
    if (!ticks || ticks.length < 4) return null;

    let sumPV = 0;
    let sumV = 0;
    let hi = -Infinity;
    let lo = Infinity;
    ticks.forEach(function (t) {
      sumPV += t.price * t.lots;
      sumV += t.lots;
      if (t.price > hi) hi = t.price;
      if (t.price < lo) lo = t.price;
    });
    const vwap = sumV > 0 ? sumPV / sumV : null;
    const openPx = ticks[0].price;
    const closePx = ticks[ticks.length - 1].price;
    const avgLot = sumV / ticks.length;
    const bigThreshold = Math.max(80, avgLot * 2.5);

    function sliceWindow(h0, m0, h1, m1) {
      return ticks.filter(function (t) {
        return inTapeWindow(t.sec, h0, m0, h1, m1);
      });
    }

    function describeSlice(seg) {
      if (!seg || seg.length < 2) return null;
      const p0 = seg[0].price;
      const p1 = seg[seg.length - 1].price;
      const sHi = seg.reduce(function (m, t) { return Math.max(m, t.price); }, -Infinity);
      const sLo = seg.reduce(function (m, t) { return Math.min(m, t.price); }, Infinity);
      const lots = seg.map(function (t) { return t.lots; }).sort(function (a, b) { return b - a; });
      const maxLot = lots[0];
      const top3 = lots.slice(0, 3).map(function (x) {
        return (Math.round(x * 10) / 10);
      });
      const bigN = seg.filter(function (t) { return t.lots >= bigThreshold; }).length;
      const midN = seg.filter(function (t) {
        return t.lots >= 30 && t.lots < bigThreshold;
      }).length;
      const smallN = seg.filter(function (t) { return t.lots > 0 && t.lots < 20; }).length;
      const buyN = seg.filter(function (t) { return t.side > 0; }).length;
      const sellN = seg.filter(function (t) { return t.side < 0; }).length;
      const vol = seg.reduce(function (s, t) { return s + t.lots; }, 0);
      return {
        n: seg.length,
        p0: p0,
        p1: p1,
        sHi: sHi,
        sLo: sLo,
        maxLot: maxLot,
        top3: top3,
        bigN: bigN,
        midN: midN,
        smallN: smallN,
        buyN: buyN,
        sellN: sellN,
        vol: vol,
        up: p1 > p0 + 1e-9,
        down: p1 < p0 - 1e-9
      };
    }

    function fmtPxLocal(p) {
      if (!(p > 0)) return "—";
      if (p >= 100) return String(Math.round(p * 10) / 10);
      if (p >= 10) return String(Math.round(p * 100) / 100);
      return String(Math.round(p * 1000) / 1000);
    }

    function guessForce(d, label) {
      if (!d) return { force: "不明", intent: "樣本不足" };
      const rise = d.up && (d.sHi - d.p0) / d.p0 > 0.01;
      const dump = d.down || (d.sellN > d.buyN * 1.2);
      const bigLift = d.bigN >= 2 && rise;
      const crash = d.bigN >= 2 && d.down && d.maxLot >= bigThreshold;
      const grind = d.midN >= Math.max(3, d.n * 0.35) && Math.abs(d.p1 - d.p0) / d.p0 < 0.02;
      const retail = d.smallN >= d.n * 0.45 && d.bigN === 0;

      if (label.indexOf("09:00") === 0 && bigLift) {
        return {
          force: "隔日沖／短線主力",
          intent: "開盤點火拉高，營造強勢以利後續出貨或誘多。"
        };
      }
      if ((label.indexOf("10:") === 0 || label.indexOf("11:") === 0) && crash) {
        return {
          force: "當沖空單／停損盤",
          intent: "帶量下殺（或摜破均價／關卡），觸發追殺與停損。"
        };
      }
      if (label.indexOf("11:5") === 0 || label.indexOf("12:0") === 0) {
        if (crash || (d.bigN >= 1 && d.down)) {
          return {
            force: "當沖回補／逢低買盤",
            intent: "相對低點爆量換手；空單停利與低接交戰。"
          };
        }
      }
      if ((label.indexOf("12:") === 0 || label.indexOf("13:0") === 0 || label.indexOf("13:1") === 0) && grind) {
        return {
          force: "法人／實戶低接",
          intent: "中小單穩步承接，降低市場衝擊。"
        };
      }
      if (label.indexOf("13:2") === 0 || label.indexOf("13:3") === 0) {
        if (d.bigN >= 1 && (d.up || d.maxLot >= bigThreshold)) {
          return {
            force: "機構法人作價／護盤",
            intent: "尾盤大單急拉或守關，常見作帳／護盤特徵。"
          };
        }
      }
      if (retail) {
        return {
          force: "散戶為主",
          intent: "大戶退場，零碎單承接或停損。"
        };
      }
      if (bigLift) {
        return { force: "短線多頭主力", intent: "大單推升。" };
      }
      if (crash) {
        return { force: "短線空頭／停損", intent: "大單壓低。" };
      }
      if (grind) {
        return { force: "法人／實戶", intent: "穩步進出。" };
      }
      return {
        force: dump ? "偏賣壓" : (rise ? "偏買盤" : "觀望換手"),
        intent: "量能特徵未達強烈門檻。"
      };
    }

    const windows = [
      { label: "09:00–09:32", h0: 9, m0: 0, h1: 9, m1: 32 },
      { label: "09:32–10:20", h0: 9, m0: 32, h1: 10, m1: 20 },
      { label: "10:18–10:40", h0: 10, m0: 18, h1: 10, m1: 40 },
      { label: "11:30–12:10", h0: 11, m0: 30, h1: 12, m1: 10 },
      { label: "12:04–13:10", h0: 12, m0: 4, h1: 13, m1: 10 },
      { label: "13:20–13:30", h0: 13, m0: 20, h1: 13, m1: 30 }
    ];

    const timeline = [];
    windows.forEach(function (w) {
      const seg = sliceWindow(w.h0, w.m0, w.h1, w.m1);
      const d = describeSlice(seg);
      if (!d || d.n < 2) return;
      const g = guessForce(d, w.label);
      const lotHint = d.top3.length
        ? ("最大 " + d.top3.map(function (x) { return x + "張"; }).join("／") +
          (d.bigN ? "，大單 " + d.bigN + " 筆" : ""))
        : "—";
      timeline.push({
        time: w.label,
        price: fmtPxLocal(d.p0) + " → " + fmtPxLocal(d.p1) +
          "（高 " + fmtPxLocal(d.sHi) + "／低 " + fmtPxLocal(d.sLo) + "）",
        volume: lotHint,
        force: g.force,
        intent: g.intent,
        n: d.n
      });
    });

    const narratives = [];
    const openSeg = describeSlice(sliceWindow(9, 0, 9, 32));
    if (openSeg && openSeg.bigN >= 2 && openSeg.up) {
      narratives.push({
        title: "隔日沖／短線主力（開盤衝高）",
        body: "開盤附近由 " + fmtPxLocal(openSeg.p0) + " 推至區間高 " +
          fmtPxLocal(openSeg.sHi) + "，出現 " + openSeg.bigN +
          " 筆偏大單（最大約 " + Math.round(openSeg.maxLot) +
          " 張）。若隨後轉賣壓，符合「拉高誘多／倒貨」常見節奏。"
      });
    }
    const midCrash = describeSlice(sliceWindow(10, 0, 11, 0));
    if (midCrash && midCrash.bigN >= 1 && midCrash.down) {
      const vwapTxt = vwap ? ("（當日均價約 " + fmtPxLocal(vwap) + "）") : "";
      narratives.push({
        title: "當沖客（帶量下殺／破關）",
        body: "10 點前後價格由 " + fmtPxLocal(midCrash.p0) + " 移向 " +
          fmtPxLocal(midCrash.p1) + vwapTxt + "，大單 " + midCrash.bigN +
          " 筆、最大約 " + Math.round(midCrash.maxLot) +
          " 張，偏當沖空單追殺或多方停損潮。"
      });
    }
    const noon = describeSlice(sliceWindow(11, 40, 12, 20));
    if (noon && noon.n >= 3 && (noon.bigN >= 1 || noon.down)) {
      narratives.push({
        title: "底部換手（當沖回補／低接）",
        body: "近午間低檔區（低 " + fmtPxLocal(noon.sLo) + "）出現放量換手，最大約 " +
          Math.round(noon.maxLot) + " 張，常見空單停利與逢低買盤交會。"
      });
    }
    const pm = describeSlice(sliceWindow(12, 0, 13, 15));
    if (pm && pm.midN >= 3 && Math.abs(pm.p1 - pm.p0) / pm.p0 < 0.025) {
      narratives.push({
        title: "法人／實戶（盤中穩步承接）",
        body: "午盤後價格於 " + fmtPxLocal(pm.sLo) + "–" + fmtPxLocal(pm.sHi) +
          " 緩步移動，中單偏多（約 " + pm.midN + " 筆），較像降低衝擊的分批進出。"
      });
    }
    const closeSeg = describeSlice(sliceWindow(13, 15, 13, 30));
    if (closeSeg && closeSeg.bigN >= 1) {
      narratives.push({
        title: "尾盤大單（作價／護盤嫌疑）",
        body: "尾盤最大約 " + Math.round(closeSeg.maxLot) + " 張，價格 " +
          fmtPxLocal(closeSeg.p0) + " → " + fmtPxLocal(closeSeg.p1) +
          "。最後一盤急拉／急殺常帶有作帳或守關意圖，需盤後法人數據驗證。"
      });
    }
    const smallShare = ticks.filter(function (t) { return t.lots > 0 && t.lots <= 10; }).length / ticks.length;
    if (smallShare >= 0.25) {
      narratives.push({
        title: "散戶痕跡（小單穿插）",
        body: "約 " + Math.round(smallShare * 100) +
          "% 筆數為偏小單（≤10 張），多出現在大戶退場後的橫盤或高檔盤跌，屬零星追價／停損。"
      });
    }
    if (!narratives.length) {
      narratives.push({
        title: "綜合",
        body: "樣本可見價量變化，但尚未形成強烈「開盤拉抬／摜破／尾盤作價」等典型段落；請搭配下方時段表觀察。"
      });
    }

    const preamble =
      "單憑分時成交明細無法確認特定外資、投信或券商分點身分；僅能依「單筆張數（大單 vs 小單）」與「時段價量慣性」推敲當沖、隔日沖、法人與散戶痕跡。" +
      "明細通常只有時間、價格、張數與漲跌方向，不含下單券商。" +
      (vwap ? (" 本段估算均價（VWAP）約 " + fmtPxLocal(vwap) + " 元。") : "") +
      " 區間約 " + fmtPxLocal(lo) + "–" + fmtPxLocal(hi) +
      "，開 " + fmtPxLocal(openPx) + " → 末 " + fmtPxLocal(closePx) + "。";

    const verify = [
      "三大法人買賣超日報：核對低接段與尾盤大單是否對得上外資／投信實際買賣超。",
      "券商分點進出：查買超／賣超前列分點，驗證開盤衝高是否為隔日沖券商倒貨。",
      "當沖交易統計：若當沖占比偏高且損益偏虧，早盤追價多方可能在急殺段被洗。"
    ];

    // 活躍者補強敘事
    (pack.actors || []).filter(function (a) { return a && a.active; }).slice(0, 3).forEach(function (a) {
      if (narratives.some(function (n) { return n.title.indexOf(a.name) >= 0; })) return;
      narratives.push({
        title: a.name + "（評級 " + a.level + "）",
        body: a.detail || "特徵觸發。"
      });
    });

    const action = buildTapeActionHint(ticks, ctx, {
      vwap: vwap,
      hi: hi,
      lo: lo,
      open: openPx,
      bigThreshold: bigThreshold
    });

    return {
      preamble: preamble,
      vwap: vwap,
      hi: hi,
      lo: lo,
      open: openPx,
      close: closePx,
      narratives: narratives,
      timeline: timeline,
      verify: verify,
      action: action
    };
  }

  /**
   * 依「截至某時刻」的足跡，給偏買／偏賣／觀望提示（非投資建議）。
   * 例如盤中 10:00：用 09:00–10:00 資料推演是否還適合追。
   */
  function buildTapeActionHint(ticks, ctx, stats) {
    stats = stats || {};
    if (!ticks || ticks.length < 4) return null;

    function fmt(p) {
      if (!(p > 0)) return "—";
      if (p >= 100) return String(Math.round(p * 10) / 10);
      if (p >= 10) return String(Math.round(p * 100) / 100);
      return String(Math.round(p * 1000) / 1000);
    }

    function secToHm(sec) {
      if (sec == null || !isFinite(sec)) return "—";
      const h = Math.floor(sec / 3600);
      const m = Math.floor((sec % 3600) / 60);
      return (h < 10 ? "0" : "") + h + ":" + (m < 10 ? "0" : "") + m;
    }

    function hintAt(cutSec, label) {
      const slice = ticks.filter(function (t) {
        return t.sec == null || t.sec <= cutSec;
      });
      if (slice.length < 4) return null;

      let sumPV = 0;
      let sumV = 0;
      let hi = -Infinity;
      let lo = Infinity;
      slice.forEach(function (t) {
        sumPV += t.price * t.lots;
        sumV += t.lots;
        if (t.price > hi) hi = t.price;
        if (t.price < lo) lo = t.price;
      });
      const vwap = sumV > 0 ? sumPV / sumV : null;
      const open = slice[0].price;
      const last = slice[slice.length - 1].price;
      const avgLot = sumV / slice.length;
      const bigTh = stats.bigThreshold || Math.max(80, avgLot * 2.5);

      const am = slice.filter(function (t) {
        return inTapeWindow(t.sec, 9, 0, 9, 32);
      });
      let amHi = open;
      let amBigUp = 0;
      am.forEach(function (t) {
        if (t.price > amHi) amHi = t.price;
        if (t.lots >= bigTh && t.side >= 0) amBigUp += 1;
      });
      const pumped = am.length >= 3 && amHi >= open * 1.015 && amBigUp >= 2;
      const offHigh = pumped && last <= amHi * 0.985;
      const belowVwap = vwap != null && last < vwap * 0.995;
      const aboveVwap = vwap != null && last > vwap * 1.005;
      const nearLo = last <= lo * 1.008;
      const nearHi = last >= hi * 0.992;

      const recent = slice.slice(-Math.min(12, slice.length));
      const recentSellBig = recent.filter(function (t) {
        return t.lots >= bigTh && t.side <= 0;
      }).length;
      const recentBuyBig = recent.filter(function (t) {
        return t.lots >= bigTh && t.side >= 0;
      }).length;
      const recentDown = recent.length >= 3 &&
        recent[recent.length - 1].price < recent[0].price * 0.992;

      const reasons = [];
      let action = "觀望";
      let tone = "";
      let score = 0; // +買 -賣

      if (pumped) {
        reasons.push("早盤已見大單急拉（高 " + fmt(amHi) + "），隔日沖出貨風險升高");
        score -= 2;
      }
      if (offHigh) {
        reasons.push("價格已離開早盤高點回落，不宜追高");
        score -= 2;
      }
      if (belowVwap && recentDown) {
        reasons.push("位於均價下方且近端偏弱（VWAP≈" + fmt(vwap) + "）");
        score -= 2;
      }
      if (recentSellBig >= 2) {
        reasons.push("近端連續大單偏賣（" + recentSellBig + " 筆）");
        score -= 2;
      }
      if (nearLo && recentBuyBig >= 1 && !recentDown) {
        reasons.push("靠近當日低檔且出現大單承接跡象");
        score += 2;
      }
      if (aboveVwap && !offHigh && recentBuyBig >= 1 && score >= 0) {
        reasons.push("站上均價且近端有買盤");
        score += 1;
      }
      if (nearHi && pumped) {
        reasons.push("仍近當日高檔，追價風險大");
        score -= 1;
      }
      // 破均價急殺後的超賣區：只給「留意」不給猛買
      if (belowVwap && nearLo && cutSec >= 10 * 3600) {
        reasons.push("若要做多僅適合等止穩／站回均價，不建議趕底");
        if (score > -1) score -= 1;
      }

      if (score <= -3) {
        action = "偏賣／勿追";
        tone = "down";
      } else if (score <= -1) {
        action = "觀望偏空";
        tone = "down";
      } else if (score >= 3) {
        action = "偏買／可留意";
        tone = "up";
      } else if (score >= 1) {
        action = "觀望偏多";
        tone = "up";
      } else {
        action = "觀望";
        tone = "";
      }

      if (!reasons.length) {
        reasons.push("截至此時特徵尚未一面倒，優先等待更明確價量轉折");
      }

      return {
        label: label || secToHm(cutSec),
        asOfSec: cutSec,
        asOf: label || secToHm(cutSec),
        action: action,
        tone: tone,
        score: score,
        price: last,
        vwap: vwap,
        open: open,
        hi: hi,
        lo: lo,
        reasons: reasons.slice(0, 4),
        summary: "截至 " + (label || secToHm(cutSec)) + "（現價約 " + fmt(last) +
          (vwap ? "，VWAP≈" + fmt(vwap) : "") + "）→ **" + action + "**"
      };
    }

    const marks = [
      { label: "09:30", sec: 9 * 3600 + 30 * 60 },
      { label: "10:00", sec: 10 * 3600 },
      { label: "10:30", sec: 10 * 3600 + 30 * 60 },
      { label: "11:00", sec: 11 * 3600 },
      { label: "12:00", sec: 12 * 3600 },
      { label: "13:00", sec: 13 * 3600 },
      { label: "13:25", sec: 13 * 3600 + 25 * 60 }
    ];

    const last = ticks[ticks.length - 1];
    const lastSec = last && last.sec != null ? last.sec : (13 * 3600 + 30 * 60);
    const snapshots = [];
    marks.forEach(function (m) {
      if (m.sec > lastSec + 60) return;
      const h = hintAt(m.sec, m.label);
      if (h) snapshots.push(h);
    });

    const current = hintAt(lastSec, secToHm(lastSec));
    // 特別標出 10:00（使用者常問的時點）
    const at1000 = snapshots.filter(function (s) { return s.label === "10:00"; })[0] || null;

    return {
      current: current,
      at1000: at1000,
      snapshots: snapshots,
      disclaimer: "僅依分時價量規則試算的操作傾向，不是投資建議；無法辨識真實法人／券商，下單前請自行承擔風險。"
    };
  }

  function misExTokens(code) {
    const id = String(code || "").toUpperCase();
    if (id === "T00" || id === "TWII") return ["tse_t00.tw"];
    if (id === "O00" || id === "TWOII") return ["otc_o00.tw"];
    const hint = misExHint[id];
    if (hint === "tse") return ["tse_" + id + ".tw"];
    if (hint === "otc") return ["otc_" + id + ".tw"];
    return ["tse_" + id + ".tw", "otc_" + id + ".tw"];
  }

  async function misFetchRaw(exCh) {
    // 瀏覽器直連 MIS 常被 CORS 擋；優先 jina，單次逾時要短，避免加權卡在「讀取中」
    const abs = "https://mis.twse.com.tw/stock/api/getStockInfo.jsp?ex_ch=" +
      encodeURIComponent(exCh) + "&json=1&delay=0";
    const urls = [
      "https://r.jina.ai/" + abs,
      abs,
      "https://api.codetabs.com/v1/proxy?quest=" + encodeURIComponent(abs)
    ];
    let lastErr = null;
    for (let i = 0; i < urls.length; i++) {
      try {
        const ctrl = typeof AbortController !== "undefined" ? new AbortController() : null;
        const timer = ctrl ? setTimeout(function () { ctrl.abort(); }, 5000) : 0;
        const res = await fetch(urls[i], ctrl ? { signal: ctrl.signal } : undefined);
        if (timer) clearTimeout(timer);
        if (!res.ok) continue;
        const text = await res.text();
        const start = text.indexOf("{");
        const end = text.lastIndexOf("}");
        if (start < 0 || end <= start) continue;
        const json = JSON.parse(text.slice(start, end + 1));
        if (json && (json.msgArray || String(json.rtcode) === "0000")) return json;
      } catch (err) {
        lastErr = err;
      }
    }
    throw lastErr || new Error("MIS 報價讀取失敗");
  }

  function misCacheGet(code) {
    const hit = misQuoteCache.get(String(code || "").toUpperCase());
    if (!hit) return null;
    if (Date.now() - hit.at > MIS_CACHE_MS) return null;
    return hit.quote;
  }

  async function misQuotes(codes) {
    const ids = [];
    (codes || []).forEach(function (c) {
      const id = String(c || "").toUpperCase();
      if (id && ids.indexOf(id) < 0) ids.push(id);
    });
    const out = {};
    if (!ids.length) return out;
    let need = [];
    ids.forEach(function (id) {
      const hit = misCacheGet(id);
      if (hit && hit.price > 0) out[id] = hit;
      else need.push(id);
    });
    if (!need.length) return out;

    // 登入者先吃雲端最新快照：優先富邦橋接（近 60 秒），再 MIS
    await hydrateFubonFromDrive(need, { maxAgeMs: FUBON_DRIVE_MAX_AGE_MS });
    await hydrateMisFromDrive(need);
    need = need.filter(function (id) {
      if (out[id]) return false;
      const hit = misCacheGet(id);
      if (hit && hit.price > 0) {
        out[id] = hit;
        return false;
      }
      return true;
    });
    if (!need.length) return out;

    let fetched = false;
    const run = misQueue.then(async function () {
      const still = need.filter(function (id) { return !misCacheGet(id); });
      if (!still.length) return;
      const wait = MIS_MIN_GAP_MS - (Date.now() - misLastFetchAt);
      if (wait > 0) await sleep(wait);
      const tokens = [];
      still.forEach(function (id) {
        misExTokens(id).forEach(function (tok) {
          if (tokens.indexOf(tok) < 0) tokens.push(tok);
        });
      });
      // 單次請求控制量，降低鎖 IP 風險
      for (let i = 0; i < tokens.length; i += 24) {
        if (i > 0) await sleep(MIS_MIN_GAP_MS);
        const part = tokens.slice(i, i + 24);
        misLastFetchAt = Date.now();
        let json = null;
        try {
          json = await misFetchRaw(part.join("|"));
        } catch (err) {
          continue;
        }
        if (!json || String(json.rtcode) !== "0000") continue;
        (json.msgArray || []).forEach(function (row) {
          const parsed = parseMisRow(row);
          if (!parsed || !(parsed.price > 0)) return;
          misQuoteCache.set(parsed.code, { at: Date.now(), quote: parsed });
          fetched = true;
        });
      }
    });
    misQueue = run.catch(function () {});
    await run;
    ids.forEach(function (id) {
      if (out[id]) return;
      const hit = misCacheGet(id) || (misQuoteCache.get(id) && misQuoteCache.get(id).quote) || null;
      if (hit && hit.price > 0) out[id] = hit;
    });
    if (fetched) scheduleMisDriveWrite();
    return out;
  }

  async function misTwiiQuote() {
    const board = await misQuotes(["T00"]);
    const q = board.T00;
    if (!q || !(q.price > 0)) return null;
    return {
      price: q.price,
      change: q.change,
      pct: q.pct,
      name: q.name || "加權指數",
      asOf: q.asOf,
      delayMin: 0,
      source: "mis"
    };
  }

  function withTimeout(promise, ms) {
    return new Promise(function (resolve, reject) {
      let done = false;
      const timer = setTimeout(function () {
        if (done) return;
        done = true;
        reject(new Error("timeout"));
      }, ms);
      Promise.resolve(promise).then(function (value) {
        if (done) return;
        done = true;
        clearTimeout(timer);
        resolve(value);
      }, function (err) {
        if (done) return;
        done = true;
        clearTimeout(timer);
        reject(err);
      });
    });
  }

  function watchItemCode(item) {
    return String((item && item.code) || twStockId(item && item.secid, "") || "").trim().toUpperCase();
  }

  function watchItemSecid(item) {
    if (item && item.secid) return item.secid;
    const code = watchItemCode(item);
    return code ? "178." + code : "";
  }

  async function watchBoard(items) {
    const list = items || [];
    if (!list.length) return [];
    const wantFubon = preferFubonQuotes();
    // 選富邦：台股成交價以 Live Bridge／Drive 富邦為主；否則證交所 MIS
    const codes = [];
    const secids = [];
    list.forEach(function (item) {
      if (!item) return;
      const code = watchItemCode(item);
      if (code) {
        if (!item.code) item.code = code;
        if (codes.indexOf(code) < 0) codes.push(code);
      }
      const secid = watchItemSecid(item);
      if (secid) {
        if (!item.secid) item.secid = secid;
        if (secids.indexOf(secid) < 0) secids.push(secid);
      }
    });
    const forceMis = !wantFubon && isMisForceWindow();
    if (forceMis) bustLiveCaches(secids);
    try {
      await hydrateFubonFromDrive(codes, {
        maxAgeMs: wantFubon ? Math.max(FUBON_DRIVE_SEED_MAX_AGE_MS, 5 * 60_000) : FUBON_DRIVE_SEED_MAX_AGE_MS,
        force: true,
        forceOverwrite: wantFubon
      });
    } catch (errFb) { /* ignore */ }
    if (!wantFubon) {
      try {
        await hydrateMisFromDrive(codes, {
          maxAgeMs: MIS_DRIVE_SEED_MAX_AGE_MS,
          freshen: true,
          force: true
        });
      } catch (errSeed) { /* ignore */ }
    }
    let byCode = {};
    function fillFromCache(ids) {
      (ids || []).forEach(function (id) {
        if (byCode[id] && byCode[id].price > 0) return;
        const hit = misQuoteCache.get(id);
        if (!hit || !hit.quote || !(hit.quote.price > 0)) return;
        if (wantFubon && !hit.fromFubonDrive) return;
        byCode[id] = hit.quote;
      });
    }
    fillFromCache(codes);
    if (wantFubon) {
      const missing = codes.filter(function (id) { return !(byCode[id] && byCode[id].price > 0); });
      if (missing.length) {
        try {
          const mis = await misQuotes(missing) || {};
          missing.forEach(function (id) {
            if (byCode[id] && byCode[id].price > 0) return;
            if (mis[id] && mis[id].price > 0) byCode[id] = mis[id];
          });
        } catch (errMis) { /* ignore */ }
      }
    } else {
      try {
        if (forceMis) byCode = await misQuotesForced(codes) || {};
        else byCode = await misQuotes(codes) || {};
      } catch (err) {
        try { byCode = await misQuotes(codes) || {}; } catch (err2) { byCode = {}; }
      }
      codes.forEach(function (id) {
        if (byCode[id] && byCode[id].price > 0) return;
        const hit = misQuoteCache.get(id);
        if (hit && hit.quote && hit.quote.price > 0) byCode[id] = hit.quote;
      });
    }
    return list.map(function (item) {
      const code = watchItemCode(item);
      const q = (code && byCode[code]) || null;
      const price = q && q.price != null && isFinite(q.price) ? q.price : null;
      const pct = q && q.pct != null && isFinite(q.pct) ? q.pct : null;
      const change = q && q.change != null && isFinite(q.change)
        ? q.change
        : (price != null && pct != null ? price * pct / (100 + pct) : null);
      const src = q && q.source
        ? String(q.source)
        : (q && q.price > 0 ? (wantFubon ? "fubon" : "mis") : "");
      return {
        name: preferTwName(item && item.name, q && q.name, item && item.code),
        price: price,
        change: change,
        pct: pct,
        open: q && q.open != null ? q.open : null,
        high: q && q.high != null ? q.high : null,
        low: q && q.low != null ? q.low : null,
        ref: q && q.ref != null ? q.ref : null,
        avg: q && q.avg != null ? q.avg : null,
        amplitude: q && q.amplitude != null ? q.amplitude : null,
        volumeLots: q && q.volumeLots != null ? q.volumeLots : null,
        limitUp: q && q.limitUp != null ? q.limitUp : null,
        limitDown: q && q.limitDown != null ? q.limitDown : null,
        pe: null,
        targetHigh: null,
        targetMean: null,
        targetLow: null,
        breakout: null,
        support: null,
        asOf: q && q.asOf != null ? q.asOf : null,
        source: src
      };
    });
  }

  function yahooAsOfMs(meta) {
    if (!meta) return null;
    const t = num(meta.regularMarketTime);
    if (t == null) return null;
    // Yahoo 多為秒；偶見毫秒
    return t > 1e12 ? t : t * 1000;
  }

  function quoteFromFubonIndexSnap(snap, sourceTag) {
    if (!snap || !snap.byCode || typeof snap.byCode !== "object") return null;
    const codes = ["IX0001", "TWSE", "T00"];
    for (let i = 0; i < codes.length; i++) {
      const raw = snap.byCode[codes[i]];
      const q = slimFubonQuote(raw, sourceTag || "fubon");
      if (!q || !(q.price > 0)) continue;
      let asOfMs = Date.now();
      if (snap.at != null && isFinite(Number(snap.at))) asOfMs = Number(snap.at);
      else if (q.asOf != null) {
        if (typeof q.asOf === "number" && isFinite(q.asOf)) asOfMs = q.asOf;
        else {
          const parsed = Date.parse(String(q.asOf));
          if (isFinite(parsed)) asOfMs = parsed;
        }
      }
      return {
        price: q.price,
        change: q.change,
        pct: q.pct,
        name: q.name || "加權指數",
        asOf: asOfMs,
        delayMin: 0,
        source: q.source || sourceTag || "fubon"
      };
    }
    return null;
  }

  async function fubonTwiiQuote() {
    const codes = ["IX0001", "TWSE", "T00"];
    // 先直接讀 Live Bridge／Drive 快照（不依賴 cache 年齡閘）
    const B = fubonLiveBridgeApi();
    if (B && B.readFubonLive) {
      try {
        const snap = await B.readFubonLive();
        const hit = quoteFromFubonIndexSnap(snap, "fubon-tailscale");
        if (hit) {
          applyFubonDriveSnap(snap, 5 * 60_000, "fubon-tailscale");
          return hit;
        }
      } catch (err) { /* fall through */ }
    }
    const D = fubonDriveApi();
    if (D && D.readFubonLive) {
      try {
        const snap = await D.readFubonLive();
        const hit = quoteFromFubonIndexSnap(snap, "fubon-drive");
        if (hit) {
          applyFubonDriveSnap(snap, 5 * 60_000, "fubon-drive");
          return hit;
        }
      } catch (err) { /* fall through */ }
    }
    try {
      await hydrateFubonFromDrive(codes, { maxAgeMs: 5 * 60_000, force: true });
    } catch (err) { /* ignore */ }
    for (let i = 0; i < codes.length; i++) {
      const id = codes[i];
      const hit = misQuoteCache.get(id);
      const q = hit && hit.quote;
      if (!q || !(q.price > 0)) continue;
      let asOfMs = Date.now();
      if (q.asOf != null) {
        if (typeof q.asOf === "number" && isFinite(q.asOf)) asOfMs = q.asOf;
        else {
          const parsed = Date.parse(String(q.asOf));
          if (isFinite(parsed)) asOfMs = parsed;
        }
      } else if (hit.at) {
        asOfMs = hit.at;
      }
      return {
        price: q.price,
        change: q.change,
        pct: q.pct,
        name: q.name || "加權指數",
        asOf: asOfMs,
        delayMin: 0,
        source: q.source || "fubon"
      };
    }
    return null;
  }

  async function twiiQuote(preferredSource) {
    const wantFubon = String(preferredSource || "").toLowerCase() === "fubon";
    if (wantFubon) {
      try {
        const fb = await fubonTwiiQuote();
        if (fb && fb.price > 0) return fb;
      } catch (errFb) { /* fall through to MIS */ }
    }
    // 預設／備援：證交所 MIS
    for (let i = 0; i < MIS_FORCE_ATTEMPTS; i++) {
      try {
        const mis = await misTwiiQuote();
        if (mis && mis.price > 0) return mis;
      } catch (errMis) { /* 下一輪 */ }
      if (i < MIS_FORCE_ATTEMPTS - 1) await sleep(MIS_FORCE_RETRY_MS);
    }
    throw new Error(wantFubon ? "富邦加權暫無資料，MIS 也失敗" : "MIS 加權讀取失敗，稍後重試");
  }

  async function stockDetail(secid, code) {
    const stockId = twStockId(secid, code);
    if (!stockId) return { ok: false, reason: "目前只有台股有籌碼與財務明細。" };
    const startChip = isoDaysAgo(120);
    const startShare = isoDaysAgo(400);
    const startFin = isoDaysAgo(2000);
    const startPer = isoDaysAgo(40);
    const startPrice = isoDaysAgo(120);
    const got = await Promise.all([
      finMind("TaiwanStockInstitutionalInvestorsBuySell", stockId, startChip).catch(function () { return []; }),
      finMind("TaiwanStockShareholding", stockId, startShare).catch(function () { return []; }),
      finMind("TaiwanStockFinancialStatements", stockId, startFin).catch(function () { return []; }),
      finMind("TaiwanStockPER", stockId, startPer).catch(function () { return []; }),
      finMind("TaiwanStockPrice", stockId, startPrice).catch(function () { return []; })
    ]);
    const chips = got[0];
    const shares = got[1];
    const fins = got[2];
    const pers = got[3];
    const prices = got[4];

    const byDay = {};
    chips.forEach(function (row) {
      if (!byDay[row.date]) byDay[row.date] = { date: row.date, foreign: 0, trust: 0, dealer: 0 };
      const net = (num(row.buy) || 0) - (num(row.sell) || 0);
      if (row.name === "Foreign_Investor" || row.name === "Foreign_Dealer_Self") byDay[row.date].foreign += net;
      else if (row.name === "Investment_Trust") byDay[row.date].trust += net;
      else if (row.name === "Dealer" || row.name === "Dealer_self" || row.name === "Dealer_Hedging") byDay[row.date].dealer += net;
    });
    const chipDays = Object.keys(byDay).sort().map(function (d) {
      const row = byDay[d];
      row.total = row.foreign + row.trust + row.dealer;
      return row;
    });
    const latestChip = chipDays.length ? chipDays[chipDays.length - 1] : null;
    const priceByDate = {};
    prices.forEach(function (row) { priceByDate[row.date] = row; });
    const latestPrice = prices.length ? prices[prices.length - 1] : null;
    const vol = latestPrice ? (num(latestPrice.Trading_Volume) || 0) : 0;
    const chipCards = latestChip ? [
      { name: "外資", net: latestChip.foreign, tone: chipTone(latestChip.foreign, vol) },
      { name: "投信", net: latestChip.trust, tone: chipTone(latestChip.trust, vol) },
      { name: "自營", net: latestChip.dealer, tone: chipTone(latestChip.dealer, vol) },
      { name: "法人", net: latestChip.total, tone: chipTone(latestChip.total, vol) }
    ] : [];

    const share = shares.length ? shares[shares.length - 1] : null;
    const foreignPct = share ? num(share.ForeignInvestmentSharesRatio) : null;
    const foreignRemain = share ? num(share.ForeignInvestmentRemainRatio) : null;
    const last5 = chipDays.slice(-5);
    const flow5 = {
      foreign: last5.reduce(function (a, r) { return a + r.foreign; }, 0),
      trust: last5.reduce(function (a, r) { return a + r.trust; }, 0),
      dealer: last5.reduce(function (a, r) { return a + r.dealer; }, 0)
    };
    flow5.total = flow5.foreign + flow5.trust + flow5.dealer;

    const q = quarterBag(fins);
    const last = q.length ? q[q.length - 1] : null;
    const prev = q.length > 1 ? q[q.length - 2] : null;
    const prev2 = q.length > 2 ? q[q.length - 3] : null;
    function margin(row, key) {
      if (!row || !(row.Revenue > 0) || row[key] == null) return null;
      return row[key] / row.Revenue * 100;
    }
    function marginHist(key) {
      return [margin(last, key), margin(prev, key), margin(prev2, key)];
    }
    const grossHist = marginHist("GrossProfit");
    const opHist = marginHist("OperatingIncome");
    const netHist = marginHist("IncomeAfterTaxes");
    const margins = {
      date: last ? last.date : "",
      gross: grossHist[0],
      op: opHist[0],
      net: netHist[0],
      grossHist: grossHist,
      opHist: opHist,
      netHist: netHist,
      grossTrend: rateTrend(grossHist[0], grossHist[1]),
      opTrend: rateTrend(opHist[0], opHist[1]),
      netTrend: rateTrend(netHist[0], netHist[1])
    };

    const years = yearEps(fins);
    const nowY = new Date().getFullYear();
    const want = [nowY - 2, nowY - 1, nowY, nowY + 1, nowY + 2];
    const actual = {};
    years.forEach(function (row) { actual[Number(row.year)] = row; });
    const y1 = actual[nowY - 1] ? actual[nowY - 1].sum : null;
    const y2 = actual[nowY - 2] ? actual[nowY - 2].sum : null;
    // 低基期暴衝（如景碩 0.11→3.51）不可直接複利外推；限幅且基期過低就不估後兩年
    let growthRaw = (y1 != null && y2 != null && y2 !== 0) ? (y1 / y2 - 1) : null;
    const growthUsable = growthRaw != null && isFinite(growthRaw) && Math.abs(y2) >= 0.5
      && growthRaw >= -0.6 && growthRaw <= 1.0;
    const growth = growthUsable
      ? Math.max(-0.5, Math.min(0.8, growthRaw))
      : null;
    const cur = actual[nowY];
    let yearNow = cur ? cur.sum : null;
    if (cur && cur.n > 0 && cur.n < 4) yearNow = cur.sum * (4 / cur.n);
    const fwdKind = growth == null ? "粗估略（成長異常）" : (growth !== growthRaw ? "粗估(限幅)" : "粗估");
    const epsYears = want.map(function (y) {
      if (y < nowY) {
        return { year: y, eps: actual[y] ? actual[y].sum : null, kind: "實際" };
      }
      if (y === nowY) {
        return { year: y, eps: yearNow, kind: cur && cur.n >= 4 ? "實際" : "年化粗估" };
      }
      if (growth == null || yearNow == null) {
        return { year: y, eps: null, kind: fwdKind };
      }
      if (y === nowY + 1) {
        return { year: y, eps: yearNow * (1 + growth), kind: fwdKind };
      }
      const next = yearNow * (1 + growth);
      return { year: y, eps: next * (1 + growth), kind: fwdKind };
    });

    const per = pers.length ? pers[pers.length - 1] : null;
    const volRows = prices.slice(-60).reverse().map(function (row) {
      return {
        date: row.date,
        lots: Math.round((num(row.Trading_Volume) || 0) / 1000),
        close: num(row.close),
        spread: num(row.spread)
      };
    });

    return {
      ok: true,
      stockId: stockId,
      quote: latestPrice ? {
        date: latestPrice.date,
        open: num(latestPrice.open),
        high: num(latestPrice.max),
        low: num(latestPrice.min),
        close: num(latestPrice.close),
        spread: num(latestPrice.spread),
        volume: num(latestPrice.Trading_Volume)
      } : null,
      chipDate: latestChip ? latestChip.date : "",
      chipCards: chipCards,
      ownership: {
        foreignPct: foreignPct,
        foreignRemain: foreignRemain,
        flow5: flow5
      },
      margins: margins,
      epsYears: epsYears,
      per: per ? { date: per.date, per: num(per.PER), pbr: num(per.PBR), yield: num(per.dividend_yield) } : null,
      volumes: volRows
    };
  }

  function retMap(bars) {
    const map = new Map();
    for (let i = 1; i < bars.length; i++) {
      const prev = bars[i - 1].c;
      const day = String(bars[i].t).slice(0, 10);
      if (prev > 0 && day) map.set(day, bars[i].c / prev - 1);
    }
    return map;
  }

  function scoreFromRet(r, scale) {
    if (r == null || !isFinite(r)) return null;
    const s = scale > 0 ? scale : 0.01;
    const x = Math.max(-3, Math.min(3, r / s));
    return Math.round(Math.tanh(x) * 100);
  }

