  // 廣度代理：櫃買報酬指數相對加權（上漲擴散）
  async function breadthProxySeries(days) {
    const key = "breadth|otc|" + days;
    if (cache.has(key)) return cache.get(key);
    const start = isoDaysAgo(Math.max(60, days + 40));
    const [taiex, otc] = await Promise.all([
      finMindRaw("TaiwanStockTotalReturnIndex", start, "TAIEX").catch(function () { return []; }),
      finMindRaw("TaiwanStockTotalReturnIndex", start, "TPEx").catch(function () { return []; })
    ]);
    const tMap = new Map();
    taiex.forEach(function (row) {
      const p = num(row.price);
      if (p > 0) tMap.set(row.date, p);
    });
    const oMap = new Map();
    otc.forEach(function (row) {
      const p = num(row.price);
      if (p > 0) oMap.set(row.date, p);
    });
    const daysSorted = Array.from(new Set([].concat(Array.from(tMap.keys()), Array.from(oMap.keys())))).sort();
    const out = [];
    let prevT = null;
    let prevO = null;
    daysSorted.forEach(function (d) {
      const t = tMap.get(d);
      const o = oMap.get(d);
      if (!(t > 0) || !(o > 0)) return;
      const tRet = prevT > 0 ? t / prevT - 1 : null;
      const oRet = prevO > 0 ? o / prevO - 1 : null;
      out.push({
        date: d,
        // 櫃買強於加權 → 廣度偏多
        spread: (tRet != null && oRet != null) ? (oRet - tRet) : null
      });
      prevT = t;
      prevO = o;
    });
    cache.set(key, out);
    return out;
  }

  function gradeOf(score) {
    if (score >= 60) return { label: "強勢看多", band: "+60～+100" };
    if (score >= 30) return { label: "偏多", band: "+30～+59" };
    if (score > -30) return { label: "盤整", band: "-29～+29" };
    if (score > -60) return { label: "偏空", band: "-30～-59" };
    return { label: "強勢看空", band: "-60～-100" };
  }

  async function twPredict(opts) {
    opts = opts || {};
    const horizonKey = opts.horizon || "1d";
    const histKey = opts.history || "3y";
    const horizon = { "1d": 1, "5d": 5, "20d": 20, "stock": 1 }[horizonKey] || 1;
    const need = { "1y": 280, "3y": 820, "5y": 1400, "10y": 2700 }[histKey] || 820;
    const targetSecid = horizonKey === "stock" ? opts.secid : "100.TWII";
    if (horizonKey === "stock" && !targetSecid) throw new Error("個股模式請先選標的");

    const seriesSpecs = [
      { id: "sox", label: "費半 SOX", group: "us", secid: "251.SOX", weight: 0.07, scale: 0.015 },
      { id: "ndx", label: "那斯達克100", group: "us", secid: "100.NDX", weight: 0.06, scale: 0.012 },
      { id: "spx", label: "標普500", group: "us", secid: "100.SPX", weight: 0.04, scale: 0.01 },
      { id: "dji", label: "道瓊", group: "us", secid: "100.DJIA", weight: 0.02, scale: 0.01 },
      { id: "nvda", label: "NVIDIA", group: "us", secid: "105.NVDA", weight: 0.03, scale: 0.025 },
      { id: "tsm", label: "台積電 ADR", group: "us", secid: "105.TSM", weight: 0.03, scale: 0.02 },
      { id: "n225", label: "日經225", group: "asia", secid: "100.N225", weight: 0.05, scale: 0.012 },
      { id: "ks11", label: "韓國KOSPI", group: "asia", secid: "100.KS11", weight: 0.05, scale: 0.012 },
      { id: "fx", label: "美元兌台幣", group: "fx", secid: "fx.USDTWD", weight: 0.1, scale: 0.004, invert: true },
      { id: "twii", label: "加權指數動能", group: "local", secid: "100.TWII", weight: 0.04, scale: 0.01 }
    ];
    if (horizonKey === "stock") {
      seriesSpecs.push({ id: "stock", label: opts.code || "個股", group: "local", secid: targetSecid, weight: 0.03, scale: 0.015 });
    }

    const loaded = await mapPool(seriesSpecs, 3, async function (spec) {
      try {
        let bars;
        if (spec.secid === "fx.USDTWD") bars = await yahooDailyBars("TWD=X", histKey);
        else bars = await kline(spec.secid, 101, need);
        if (!bars || bars.length < 40) throw new Error("樣本不足");
        return { spec: spec, bars: bars, rets: retMap(bars), ok: true };
      } catch (err) {
        return { spec: spec, bars: [], rets: new Map(), ok: false, reason: err.message || "讀取失敗" };
      }
    });

    let vixRets = new Map();
    let tnxRets = new Map();
    try {
      const vix = await yahooDailyBars("^VIX", histKey);
      vixRets = retMap(vix);
    } catch (err) { /* 可缺 */ }
    try {
      const tnx = await yahooDailyBars("^TNX", histKey);
      tnxRets = retMap(tnx);
    } catch (err) { /* 可缺 */ }

    let inst = [];
    try { inst = await institutionalSeries(need); } catch (err) { inst = []; }
    const foreignMap = new Map();
    const trustMap = new Map();
    const dealerMap = new Map();
    inst.forEach(function (row) {
      foreignMap.set(row.date, row.foreign);
      trustMap.set(row.date, row.trust);
      dealerMap.set(row.date, row.dealer);
    });

    const extra = await Promise.all([
      txFuturesSeries(need).catch(function () { return []; }),
      txForeignFutSeries(need).catch(function () { return []; }),
      txOptionPcrSeries(need).catch(function () { return []; }),
      marginSeries(need).catch(function () { return []; }),
      breadthProxySeries(need).catch(function () { return []; })
    ]);
    const txMap = new Map();
    const basisMap = new Map();
    (extra[0] || []).forEach(function (row) {
      if (row.ret != null) txMap.set(row.date, row.ret);
      if (row.basisPct != null) basisMap.set(row.date, row.basisPct / 100);
    });
    const futForeignMap = new Map();
    (extra[1] || []).forEach(function (row) {
      if (row.delta != null) futForeignMap.set(row.date, row.delta);
    });
    const pcrMap = new Map();
    (extra[2] || []).forEach(function (row) {
      if (row.pcr != null) pcrMap.set(row.date, row.pcr);
    });
    const marginMap = new Map();
    (extra[3] || []).forEach(function (row) {
      if (row.chg != null) marginMap.set(row.date, row.chg);
    });
    const breadthMap = new Map();
    (extra[4] || []).forEach(function (row) {
      if (row.spread != null) breadthMap.set(row.date, row.spread);
    });

    const target = loaded.find(function (row) {
      return row.spec.secid === (horizonKey === "stock" ? targetSecid : "100.TWII") && row.ok;
    }) || loaded.find(function (row) { return row.spec.id === "twii" && row.ok; });
    if (!target || !target.ok) throw new Error("加權指數行情讀不到，無法預測");

    const twBars = target.bars;
    const twDays = twBars.map(function (b) { return String(b.t).slice(0, 10); });

    function pushPart(parts, state, id, label, group, weight, score, ret) {
      if (score == null || !isFinite(score)) return;
      parts.push({ id: id, label: label, group: group, weight: weight, score: score, ret: ret });
      state.wSum += weight;
      state.sSum += weight * score;
    }

    function factorScoreOn(day, prevDay) {
      const parts = [];
      const state = { wSum: 0, sSum: 0 };
      loaded.forEach(function (row) {
        if (!row.ok) return;
        const r = row.rets.get(prevDay);
        if (r == null) return;
        const sc = scoreFromRet(row.spec.invert ? -r : r, row.spec.scale);
        pushPart(parts, state, row.spec.id, row.spec.label, row.spec.group, row.spec.weight, sc, r);
      });
      const fr = foreignMap.get(prevDay);
      const tr = trustMap.get(prevDay);
      const dr = dealerMap.get(prevDay);
      if (fr != null) pushPart(parts, state, "foreign", "外資現貨買賣超", "flow", 0.08, scoreFromRet(fr / 1e10, 0.8), fr);
      if (tr != null) pushPart(parts, state, "trust", "投信買賣超", "flow", 0.04, scoreFromRet(tr / 1e9, 0.8), tr);
      if (dr != null) pushPart(parts, state, "dealer", "自營商買賣超", "flow", 0.03, scoreFromRet(dr / 1e9, 0.8), dr);
      const vr = vixRets.get(prevDay);
      if (vr != null) pushPart(parts, state, "vix", "VIX（反向）", "risk", 0.04, scoreFromRet(-vr, 0.08), vr);
      const nr = tnxRets.get(prevDay);
      if (nr != null) pushPart(parts, state, "tnx", "美債10年（反向）", "risk", 0.04, scoreFromRet(-nr, 0.02), nr);

      // 期貨／選擇權／廣度／融資（原紅框項目）
      const txr = txMap.get(prevDay);
      if (txr != null) pushPart(parts, state, "tx", "台指期近月動能", "futures", 0.07, scoreFromRet(txr, 0.01), txr);
      const basis = basisMap.get(prevDay);
      if (basis != null) pushPart(parts, state, "basis", "台指期正逆價差", "futures", 0.05, scoreFromRet(basis, 0.008), basis);
      const ffd = futForeignMap.get(prevDay);
      if (ffd != null) pushPart(parts, state, "futForeign", "外資期貨淨部位變化", "futures", 0.05, scoreFromRet(ffd / 8000, 0.8), ffd);
      const pcr = pcrMap.get(prevDay);
      if (pcr != null) {
        // PCR 偏高偏避險；用 (1 - PCR) 方向：PCR↑ → 分數偏空
        pushPart(parts, state, "pcr", "選擇權 PCR", "futures", 0.03, scoreFromRet(1 - pcr, 0.25), pcr);
      }
      const br = breadthMap.get(prevDay);
      if (br != null) pushPart(parts, state, "breadth", "上漲擴散（櫃買相對加權）", "local", 0.04, scoreFromRet(br, 0.006), br);
      const mg = marginMap.get(prevDay);
      if (mg != null) pushPart(parts, state, "margin", "融資餘額變化", "local", 0.03, scoreFromRet(mg, 0.004), mg);

      if (!(state.wSum > 0)) return { score: 0, parts: [] };
      return { score: Math.round(state.sSum / state.wSum), parts: parts };
    }

    const lastDay = twDays[twDays.length - 1];
    const prevDay = twDays[twDays.length - 2] || lastDay;
    const now = factorScoreOn(lastDay, prevDay);
    const grade = gradeOf(now.score);

    const combos = [];
    function partScore(id) {
      const hit = now.parts.find(function (p) { return p.id === id; });
      return hit ? hit.score : null;
    }
    const sox = partScore("sox");
    const tsm = partScore("tsm");
    const nvda = partScore("nvda");
    const foreign = partScore("foreign");
    const fx = partScore("fx");
    const vix = partScore("vix");
    const tx = partScore("tx");
    const basis = partScore("basis");
    const futForeign = partScore("futForeign");
    const pcr = partScore("pcr");
    const breadth = partScore("breadth");
    const margin = partScore("margin");
    if (sox != null && tsm != null && sox > 20 && tsm > 20) combos.push("費半與台積電 ADR 同向偏多 → 隔日偏多假設");
    if (sox != null && nvda != null && sox < -20 && nvda < -20) combos.push("費半與 NVIDIA 同向偏空 → 隔日偏空假設");
    if (foreign != null && foreign > 20) combos.push("外資現貨偏買 → 資金流入假設");
    if (foreign != null && foreign < -20) combos.push("外資現貨偏賣 → 資金流出假設");
    if (fx != null && foreign != null && fx < -20 && foreign < -20) combos.push("美元升／台幣弱 + 外資賣超 → 匯出壓力假設");
    if (vix != null && sox != null && vix < -20 && sox < -20) combos.push("VIX 升、費半弱 → 風險資產壓力假設");
    if (tx != null && basis != null && tx > 20 && basis > 10) combos.push("台指期偏多且正價差 → 期貨動能偏多假設");
    if (tx != null && basis != null && tx < -20 && basis < -10) combos.push("台指期偏空且逆價差 → 期貨動能偏空假設");
    if (futForeign != null && foreign != null && futForeign > 20 && foreign > 20) combos.push("外資現貨＋期貨同向偏多 → 資金流入加強假設");
    if (futForeign != null && foreign != null && futForeign < -20 && foreign < -20) combos.push("外資現貨＋期貨同向偏空 → 資金流出加強假設");
    if (pcr != null && pcr < -20 && vix != null && vix < -10) combos.push("PCR 偏高且 VIX 升 → 避險升溫假設");
    if (breadth != null && breadth > 20 && margin != null && margin > 10) combos.push("上漲擴散＋融資增加 → 市場參與升溫假設");
    if (breadth != null && breadth < -20 && margin != null && margin < -10) combos.push("擴散轉弱＋融資收縮 → 風險偏好降溫假設");
    if (!combos.length) combos.push("組合條件尚未同時達標，先看總分與各因子");

    // 簡易回測：用前一日因子分數預測後 horizon 日的漲跌方向
    let hits = 0;
    let trials = 0;
    let longHits = 0;
    let longN = 0;
    let shortHits = 0;
    let shortN = 0;
    const sampleRows = [];
    for (let i = 60; i < twBars.length - horizon; i++) {
      const day = twDays[i];
      const prev = twDays[i - 1];
      const pack = factorScoreOn(day, prev);
      if (!pack.parts.length) continue;
      const future = twBars[i + horizon].c / twBars[i].c - 1;
      const predUp = pack.score >= 30;
      const predDown = pack.score <= -30;
      if (!predUp && !predDown) continue;
      const actualUp = future > 0;
      trials += 1;
      if (predUp) {
        longN += 1;
        if (actualUp) { hits += 1; longHits += 1; }
      } else {
        shortN += 1;
        if (!actualUp) { hits += 1; shortHits += 1; }
      }
      if (sampleRows.length < 12) {
        sampleRows.push({
          date: day,
          score: pack.score,
          pred: predUp ? "多" : "空",
          actual: actualUp ? "漲" : "跌",
          futurePct: future
        });
      }
    }

    const groups = {};
    now.parts.forEach(function (p) {
      if (!groups[p.group]) groups[p.group] = { score: 0, w: 0, items: [] };
      groups[p.group].score += p.score * p.weight;
      groups[p.group].w += p.weight;
      groups[p.group].items.push(p);
    });
    const groupRows = Object.keys(groups).map(function (g) {
      const names = {
        us: "美股／半導體（建議權重 25%）",
        asia: "亞股（建議權重 10%）",
        flow: "三大法人現貨（建議權重 15%）",
        futures: "期貨／選擇權（建議權重 20%）",
        fx: "匯率（建議權重 10%）",
        risk: "VIX／美債（建議權重 8%）",
        local: "台股內部／廣度／融資（建議權重 12%）"
      };
      return {
        group: g,
        label: names[g] || g,
        score: groups[g].w ? Math.round(groups[g].score / groups[g].w) : 0,
        items: groups[g].items
      };
    }).sort(function (a, b) { return Math.abs(b.score) - Math.abs(a.score); });

    return {
      horizon: horizonKey,
      horizonDays: horizon,
      history: histKey,
      target: horizonKey === "stock" ? (opts.code || targetSecid) : "加權指數",
      asOf: lastDay,
      score: now.score,
      grade: grade.label,
      band: grade.band,
      parts: now.parts.sort(function (a, b) { return Math.abs(b.score) - Math.abs(a.score); }),
      groups: groupRows,
      combos: combos,
      included: [
        "台指期近月動能、正逆價差（FinMind TaiwanFuturesDaily）",
        "外資期貨淨未平倉變化（FinMind TaiwanFuturesInstitutionalInvestors）",
        "選擇權 PCR（FinMind TaiwanOptionDaily TXO 彙總）",
        "上漲擴散代理：櫃買報酬指數相對加權（FinMind TotalReturnIndex）",
        "融資餘額變化（FinMind TaiwanStockTotalMarginPurchaseShortSale）"
      ],
      midTerm: [
        "產業基本面代理：費半 SOX、台積電 ADR 中期動能（已反映於美股／半導體類分數）",
        "總經代理：美元兌台幣、美債殖利率（PMI／出口訂單月頻資料不納入隔日評分，以上述日頻代理）"
      ],
      missing: [],
      weightsNote: "初始權重：美股25、期貨／選擇權20、法人15、匯率10、亞股10、VIX美債8、台股內部／廣度／融資12。缺資料時自動重分配。",
      backtest: {
        trials: trials,
        accuracy: trials ? hits / trials : null,
        longAccuracy: longN ? longHits / longN : null,
        shortAccuracy: shortN ? shortHits / shortN : null,
        longN: longN,
        shortN: shortN,
        samples: sampleRows
      },
      csv: null
    };
  }

  function twseNum(raw) {
    if (raw == null) return null;
    const s = String(raw).replace(/<[^>]+>/g, "").replace(/,/g, "").replace(/%/g, "").trim();
    if (!s || s === "--" || s === "---" || s === "X") return null;
    const n = Number(s);
    return isFinite(n) ? n : null;
  }

  function twseSign(raw) {
    const s = String(raw || "").replace(/<[^>]+>/g, "").trim();
    if (s.indexOf("-") >= 0 || s.indexOf("－") >= 0 || s.indexOf("跌") >= 0) return -1;
    if (s.indexOf("+") >= 0 || s.indexOf("＋") >= 0 || s.indexOf("漲") >= 0) return 1;
    return 0;
  }

  function ymdAddDays(ymd, delta) {
    const y = Number(String(ymd).slice(0, 4));
    const m = Number(String(ymd).slice(4, 6)) - 1;
    const d = Number(String(ymd).slice(6, 8));
    const dt = new Date(Date.UTC(y, m, d + delta));
    const yy = dt.getUTCFullYear();
    const mm = String(dt.getUTCMonth() + 1).padStart(2, "0");
    const dd = String(dt.getUTCDate()).padStart(2, "0");
    return "" + yy + mm + dd;
  }

  function taipeiYmd() {
    return new Intl.DateTimeFormat("en-CA", {
      timeZone: "Asia/Taipei",
      year: "numeric",
      month: "2-digit",
      day: "2-digit"
    }).format(new Date()).replace(/-/g, "");
  }

  async function twseFetchJson(path) {
    const abs = path.indexOf("http") === 0 ? path : ("https://www.twse.com.tw" + path);
    const urls = [
      abs,
      "https://corsproxy.io/?" + encodeURIComponent(abs),
      "https://api.allorigins.win/raw?url=" + encodeURIComponent(abs),
      "https://api.codetabs.com/v1/proxy?quest=" + encodeURIComponent(abs)
    ];
    let lastErr = null;
    for (let i = 0; i < urls.length; i++) {
      try {
        const ctrl = typeof AbortController !== "undefined" ? new AbortController() : null;
        const timer = ctrl ? setTimeout(function () { ctrl.abort(); }, 20000) : 0;
        const res = await fetch(urls[i], ctrl ? { signal: ctrl.signal } : undefined);
        if (timer) clearTimeout(timer);
        if (!res.ok) continue;
        const text = await res.text();
        const start = text.indexOf("{");
        const end = text.lastIndexOf("}");
        if (start < 0 || end <= start) continue;
        return JSON.parse(text.slice(start, end + 1));
      } catch (err) {
        lastErr = err;
      }
    }
    throw lastErr || new Error("證交所資料讀取失敗");
  }

  const twseMiCache = new Map();
  const twseT86Cache = new Map();

  async function twseMiIndex(dateYmd) {
    if (twseMiCache.has(dateYmd)) return twseMiCache.get(dateYmd);
    const json = await twseFetchJson(
      "/rwd/zh/afterTrading/MI_INDEX?response=json&date=" + encodeURIComponent(dateYmd) + "&type=ALLBUT0999"
    );
    if (!json || String(json.stat || "").toUpperCase() !== "OK") {
      const miss = { ok: false, date: dateYmd, stat: json && json.stat, rows: [], indices: [] };
      twseMiCache.set(dateYmd, miss);
      return miss;
    }
    const tables = json.tables || [];
    const priceTable = tables.find(function (t) {
      return t && t.title && /每日收盤行情/.test(t.title);
    });
    const indexTable = tables.find(function (t) {
      return t && t.title && /價格指數\(臺灣證券交易所\)|發行量加權/.test(t.title) && (t.data || []).length;
    }) || tables[0];
    const statsTable = tables.find(function (t) {
      return t && t.title && /大盤統計資訊/.test(t.title);
    });
    const breadthTable = tables.find(function (t) {
      return t && t.title && /漲跌證券數合計/.test(t.title);
    });
    function parseParenCount(text) {
      const s = String(text || "").replace(/,/g, "");
      const m = s.match(/^(\d+)/);
      return m ? Number(m[1]) : null;
    }
    let amount = null;
    ((statsTable && statsTable.data) || []).forEach(function (r) {
      const label = String(r[0] || "");
      if (/合計|總計/.test(label) || /^11\./.test(label)) amount = twseNum(r[1]);
    });
    if (amount == null) {
      let sum = 0;
      let hit = false;
      ((statsTable && statsTable.data) || []).forEach(function (r) {
        const label = String(r[0] || "");
        if (/一般股票|ETF/.test(label)) {
          const v = twseNum(r[1]);
          if (v != null) { sum += v; hit = true; }
        }
      });
      if (hit) amount = sum;
    }
    let up = null;
    let down = null;
    let flat = null;
    ((breadthTable && breadthTable.data) || []).forEach(function (r) {
      const label = String(r[0] || "");
      const stockCol = r[2] != null ? r[2] : r[1];
      if (/^上漲/.test(label)) up = parseParenCount(stockCol);
      else if (/^下跌/.test(label)) down = parseParenCount(stockCol);
      else if (/持平/.test(label)) flat = parseParenCount(stockCol);
    });
    const rows = ((priceTable && priceTable.data) || []).map(function (r) {
      const sign = twseSign(r[9]);
      const diff = twseNum(r[10]);
      const close = twseNum(r[8]);
      const chg = diff == null ? null : sign * Math.abs(diff);
      const pct = close > 0 && chg != null && close !== chg ? (chg / (close - chg)) * 100 : null;
      return {
        code: String(r[0] || "").trim(),
        name: String(r[1] || "").trim(),
        volume: twseNum(r[2]),
        amount: twseNum(r[4]),
        open: twseNum(r[5]),
        high: twseNum(r[6]),
        low: twseNum(r[7]),
        close: close,
        change: chg,
        pct: pct
      };
    }).filter(function (row) { return row.code; });
    const indices = ((indexTable && indexTable.data) || []).map(function (r) {
      const sign = twseSign(r[2]);
      const pts = twseNum(r[3]);
      return {
        name: String(r[0] || "").trim(),
        close: twseNum(r[1]),
        change: pts == null ? null : sign * Math.abs(pts),
        pct: twseNum(r[4])
      };
    }).filter(function (row) { return row.name; });
    const out = {
      ok: true,
      date: String(json.date || dateYmd),
      rows: rows,
      indices: indices,
      amount: amount,
      breadth: { up: up, down: down, flat: flat }
    };
    twseMiCache.set(dateYmd, out);
    return out;
  }

  async function twseT86(dateYmd) {
    if (twseT86Cache.has(dateYmd)) return twseT86Cache.get(dateYmd);
    const json = await twseFetchJson(
      "/rwd/zh/fund/T86?response=json&date=" + encodeURIComponent(dateYmd) + "&selectType=ALLBUT0999"
    );
    if (!json || String(json.stat || "") !== "OK") {
      const miss = { ok: false, date: dateYmd, stat: json && json.stat, rows: [] };
      twseT86Cache.set(dateYmd, miss);
      return miss;
    }
    const rows = (json.data || []).map(function (r) {
      const foreign = twseNum(r[4]);
      const foreignDealer = twseNum(r[7]);
      const trust = twseNum(r[10]);
      const dealer = twseNum(r[11]);
      const total = twseNum(r[18]);
      // 買進／賣出股數（外陸資＋外資自營＋投信＋自營自行＋自營避險）
      const buyShares = [r[2], r[5], r[8], r[12], r[15]].reduce(function (s, v) {
        const n = twseNum(v);
        return s + (n != null ? n : 0);
      }, 0);
      const sellShares = [r[3], r[6], r[9], r[13], r[16]].reduce(function (s, v) {
        const n = twseNum(v);
        return s + (n != null ? n : 0);
      }, 0);
      return {
        code: String(r[0] || "").trim(),
        name: String(r[1] || "").trim(),
        foreignNet: foreign == null && foreignDealer == null ? null : (foreign || 0) + (foreignDealer || 0),
        foreignOnly: foreign,
        trustNet: trust,
        dealerNet: dealer,
        instNet: total,
        instBuy: buyShares,
        instSell: sellShares
      };
    }).filter(function (row) { return row.code; });
    const out = { ok: true, date: String(json.date || dateYmd), rows: rows };
    twseT86Cache.set(dateYmd, out);
    return out;
  }

  let latestT86Pack = null;
  let latestT86At = 0;

  async function latestTwseT86(maxBack) {
    const now = Date.now();
    if (latestT86Pack && latestT86Pack.ok && now - latestT86At < 5 * 60 * 1000) return latestT86Pack;
    const candidates = twseWeekdayYmds(taipeiYmd(), Math.max(8, maxBack || 12));
    for (let i = 0; i < candidates.length; i++) {
      const hit = await twseT86(candidates[i]);
      if (hit && hit.ok && hit.rows && hit.rows.length) {
        latestT86Pack = hit;
        latestT86At = now;
        return hit;
      }
    }
    return latestT86Pack || { ok: false, date: "", rows: [] };
  }

  // 自選用：最近一個有公告的交易日，各代號外資／投信／自營買賣超（股）
  async function watchChips(items) {
    const list = items || [];
    const empty = { date: "", byCode: {} };
    if (!list.length) return empty;
    const pack = await latestTwseT86(12);
    if (!pack || !pack.ok) return empty;
    const byCode = {};
    (pack.rows || []).forEach(function (row) {
      if (row && row.code) byCode[String(row.code).toUpperCase()] = row;
    });
    return { date: pack.date || "", byCode: byCode };
  }

  function twseWeekdayYmds(endYmd, maxCal) {
    const out = [];
    for (let i = 0; i < maxCal; i++) {
      const d = ymdAddDays(endYmd, -i);
      const y = Number(d.slice(0, 4));
      const m = Number(d.slice(4, 6)) - 1;
      const day = Number(d.slice(6, 8));
      const wd = new Date(Date.UTC(y, m, day)).getUTCDay();
      if (wd === 0 || wd === 6) continue;
      out.push(d);
    }
    return out;
  }

  function pickTwii(indices) {
    return (indices || []).find(function (x) {
      return /發行量加權股價指數/.test(x.name);
    }) || null;
  }

  async function twseDailyReport(opts) {
    opts = opts || {};
    const want = String(opts.date || "").replace(/\D/g, "") || taipeiYmd();
    const days = Math.max(1, Math.min(180, Number(opts.days) || 1));
    const onProgress = typeof opts.onProgress === "function" ? opts.onProgress : null;

    // 先定位最近有行情的交易日
    let endYmd = want;
    let endMi = null;
    for (let i = 0; i < 12; i++) {
      const d = ymdAddDays(want, -i);
      const hit = await twseMiIndex(d);
      if (hit.ok && hit.rows.length) {
        endMi = hit;
        endYmd = hit.date;
        break;
      }
    }
    if (!endMi) throw new Error("最近交易日的每日收盤行情讀不到");

    let sessions = [];
    if (days === 1) {
      sessions = [endMi];
    } else {
      // 多抓一些平日候選，並行讀取後取最近 N 個有資料的交易日
      let span = Math.min(320, Math.ceil(days * 1.65) + 10);
      let candidates = twseWeekdayYmds(endYmd, span);
      if (onProgress) onProgress({ phase: "mi", done: 0, need: days });
      let hits = await mapPool(candidates, 4, async function (d, idx) {
        if (onProgress && idx % 4 === 0) onProgress({ phase: "mi", done: idx, need: candidates.length, date: d });
        return d === endYmd ? endMi : twseMiIndex(d);
      });
      let ok = hits.filter(function (h) { return h && h.ok && h.rows.length; })
        .sort(function (a, b) { return a.date < b.date ? 1 : a.date > b.date ? -1 : 0; });
      if (ok.length < days && span < 320) {
        span = Math.min(320, span + 80);
        candidates = twseWeekdayYmds(endYmd, span);
        hits = await mapPool(candidates, 4, async function (d) {
          return d === endYmd ? endMi : twseMiIndex(d);
        });
        ok = hits.filter(function (h) { return h && h.ok && h.rows.length; })
          .sort(function (a, b) { return a.date < b.date ? 1 : a.date > b.date ? -1 : 0; });
      }
      sessions = ok.slice(0, days).reverse();
    }

    if (!sessions.length) throw new Error("區間內沒有收盤行情");
    const startYmd = sessions[0].date;
    const miDate = sessions[sessions.length - 1].date;

    if (onProgress) onProgress({ phase: "fund", done: 0, need: sessions.length });
    const fundDays = await mapPool(sessions.map(function (s) { return s.date; }), 3, async function (d, idx) {
      if (onProgress) onProgress({ phase: "fund", done: idx + 1, need: sessions.length, date: d });
      return twseT86(d);
    });
    const fundOk = fundDays.filter(function (f) { return f && f.ok && f.rows.length; });
    const fundDateFrom = fundOk.length ? fundOk[0].date : "";
    const fundDateTo = fundOk.length ? fundOk[fundOk.length - 1].date : "";

    const book = {};
    sessions.forEach(function (sess) {
      sess.rows.forEach(function (row) {
        if (!book[row.code]) {
          book[row.code] = {
            code: row.code,
            name: row.name,
            firstClose: null,
            close: null,
            amount: 0,
            volume: 0,
            foreignNet: 0,
            trustNet: 0,
            dealerNet: 0,
            instNet: 0,
            hasForeign: false,
            hasInst: false
          };
        }
        const b = book[row.code];
        if (row.name) b.name = row.name;
        if (row.close != null) {
          if (b.firstClose == null) b.firstClose = row.close;
          b.close = row.close;
        }
        if (row.amount != null) b.amount += row.amount;
        if (row.volume != null) b.volume += row.volume;
      });
    });

    fundOk.forEach(function (fund) {
      fund.rows.forEach(function (row) {
        if (!book[row.code]) {
          book[row.code] = {
            code: row.code,
            name: row.name,
            firstClose: null,
            close: null,
            amount: 0,
            volume: 0,
            foreignNet: 0,
            trustNet: 0,
            dealerNet: 0,
            instNet: 0,
            hasForeign: false,
            hasInst: false
          };
        }
        const b = book[row.code];
        if (row.name) b.name = row.name;
        if (row.foreignNet != null) {
          b.foreignNet += row.foreignNet;
          b.hasForeign = true;
        }
        if (row.trustNet != null) b.trustNet += row.trustNet;
        if (row.dealerNet != null) b.dealerNet += row.dealerNet;
        if (row.instNet != null) {
          b.instNet += row.instNet;
          b.hasInst = true;
        }
      });
    });

    const merged = Object.keys(book).map(function (code) {
      const b = book[code];
      const change = b.close != null && b.firstClose != null ? b.close - b.firstClose : null;
      const pct = b.close != null && b.firstClose > 0 ? (b.close / b.firstClose - 1) * 100 : null;
      return {
        code: b.code,
        name: b.name || b.code,
        close: b.close,
        change: change,
        pct: pct,
        amount: b.amount || null,
        volume: b.volume || null,
        foreignNet: b.hasForeign ? b.foreignNet : null,
        trustNet: b.trustNet || null,
        dealerNet: b.dealerNet || null,
        instNet: b.hasInst ? b.instNet : null
      };
    }).filter(function (row) { return row.close != null; });

    const firstTwii = pickTwii(sessions[0].indices);
    const lastTwii = pickTwii(sessions[sessions.length - 1].indices);
    let twii = lastTwii;
    if (firstTwii && lastTwii && firstTwii.close > 0 && lastTwii.close != null) {
      const chg = lastTwii.close - firstTwii.close;
      twii = {
        name: lastTwii.name,
        close: lastTwii.close,
        change: chg,
        pct: chg / firstTwii.close * 100
      };
    }

    return {
      date: miDate,
      startDate: startYmd,
      days: sessions.length,
      wantDays: days,
      fundDate: fundDateTo || "",
      fundDateFrom: fundDateFrom || "",
      twii: twii,
      indices: sessions[sessions.length - 1].indices || [],
      rows: merged,
      source: {
        mi: "TWSE MI_INDEX ALLBUT0999",
        fund: fundOk.length ? "TWSE T86 ALLBUT0999" : ""
      }
    };
  }

  function sortDailyReportRows(rows, mode) {
    const list = (rows || []).slice();
    const key = mode || "pctDown";
    function cmpNum(a, b, dir) {
      const av = a == null || !isFinite(a) ? (dir > 0 ? Infinity : -Infinity) : a;
      const bv = b == null || !isFinite(b) ? (dir > 0 ? Infinity : -Infinity) : b;
      return dir > 0 ? av - bv : bv - av;
    }
    list.sort(function (a, b) {
      if (key === "pctUp") return cmpNum(a.pct, b.pct, 1);
      if (key === "pctDown") return cmpNum(a.pct, b.pct, -1);
      if (key === "foreignBuy") return cmpNum(a.foreignNet, b.foreignNet, -1);
      if (key === "foreignSell") return cmpNum(a.foreignNet, b.foreignNet, 1);
      if (key === "instBuy") return cmpNum(a.instNet, b.instNet, -1);
      if (key === "instSell") return cmpNum(a.instNet, b.instNet, 1);
      if (key === "amount") return cmpNum(a.amount, b.amount, -1);
      return cmpNum(a.pct, b.pct, -1);
    });
    return list;
  }

  // 個股綜合研判：基本面＋籌碼＋技術／K線買賣點（規則試算，非投資建議）
  function twSessionClock() {
    const parts = new Intl.DateTimeFormat("en-US", {
      timeZone: "Asia/Taipei",
      weekday: "short",
      hour: "2-digit",
      minute: "2-digit",
      hour12: false
    }).formatToParts(new Date());
    const map = {};
    parts.forEach(function (p) { map[p.type] = p.value; });
    const wd = map.weekday || "";
    const hh = Number(map.hour);
    const mm = Number(map.minute);
    const mins = hh * 60 + mm;
    const weekday = ["Mon", "Tue", "Wed", "Thu", "Fri"].indexOf(wd) >= 0;
    const open = weekday && mins >= 9 * 60 && mins <= 13 * 60 + 30;
    return { open: open, weekday: weekday, hh: hh, mm: mm, label: (map.hour || "") + ":" + (map.minute || "") };
  }

  // 自選列輕量診斷：即時報價＋日 K 支撐壓力（不另拉 1 分 K）
  function watchSessionDiagnose(quote, levels, opts) {
    opts = opts || {};
    quote = quote || {};
    levels = levels || {};
    const price = num(quote.price);
    if (!(price > 0)) return { ok: false, reason: "無現價" };
    const dayOpen = num(quote.open);
    let dayHigh = num(quote.high);
    let dayLow = num(quote.low);
    if (!(dayHigh > 0)) dayHigh = price;
    if (!(dayLow > 0)) dayLow = price;
    const atrNow = price * 0.015;
    const support = levels.support || null;
    const breakout = levels.breakout || null;
    const supFocus = support && support.focus != null ? support.focus : dayLow;
    const brkFocus = breakout && breakout.focus != null ? breakout.focus : dayHigh;
    const cost = opts.cost != null && isFinite(Number(opts.cost)) && Number(opts.cost) > 0
      ? Number(opts.cost) : null;
    const pct = num(quote.pct);
    const amp = dayHigh > dayLow && price > 0 ? ((dayHigh - dayLow) / price) * 100 : null;
    // 無分 K 量能時，用振幅／漲跌幅粗估縮量／放量
    const shrink = (amp != null && amp < 1.2 && Math.abs(pct || 0) < 1.2) ||
      (amp == null && Math.abs(pct || 0) < 0.8);
    const surge = Math.abs(pct || 0) >= 2.2 || (amp != null && amp >= 3);
    const nearSup = Math.abs(price - supFocus) <= Math.max(atrNow * 0.55, tickSize(price) * 3);
    const belowSup = price < (support && support.low != null ? support.low : supFocus) - tickSize(price);
    const brokeDayLow = price <= dayLow + tickSize(price) && (pct != null && pct < -1);
    const pokedHigh = dayHigh >= brkFocus - tickSize(price);
    const failedBreak = pokedHigh && price < brkFocus - Math.max(atrNow * 0.25, tickSize(price) * 2);
    const reclaiming = dayOpen > 0 && price > dayOpen && price > (dayLow + (dayHigh - dayLow) * 0.55);
    const holdAboveSup = price > supFocus + tickSize(price);

    let stateId = "range";
    let stateLabel = "區間震盪";
    let stateTone = "";
    if (belowSup || (brokeDayLow && price < (dayOpen || price))) {
      stateId = "weak_break";
      stateLabel = "弱勢破底";
      stateTone = "down";
    } else if (failedBreak) {
      stateId = "fake_break";
      stateLabel = "假突破誘多";
      stateTone = "down";
    } else if (nearSup && shrink && holdAboveSup) {
      stateId = "dry_base";
      stateLabel = "量縮打底";
      stateTone = "";
    } else if (surge && reclaiming && holdAboveSup && !failedBreak) {
      stateId = "vol_turn";
      stateLabel = "帶量轉強";
      stateTone = "up";
    }

    const defense = roundPx(Math.min(
      belowSup ? (support && support.low != null ? support.low : supFocus) : supFocus,
      dayLow + tickSize(price)
    ));
    const buyLevel = roundPx(Math.max(supFocus, dayLow));
    const sellLevel = roundPx(brkFocus);
    return {
      ok: true,
      stateId: stateId,
      stateLabel: stateLabel,
      stateTone: stateTone,
      price: roundPx(price),
      cost: cost != null ? roundPx(cost) : null,
      defense: defense,
      buyLevel: buyLevel,
      sellLevel: sellLevel,
      stopPoint: defense,
      support: support,
      breakout: breakout
    };
  }

  // 盤中 1 分 K＋日 K 支撐壓力＋自選成本 → 狀態診斷與操作建議
  async function intradaySessionDiagnose(secid, code, opts) {
    opts = opts || {};
    const sid = String(secid || "");
    const isTwii = sid === "100.TWII" || String(code || "").toUpperCase() === "TWII";
    const stockId = twStockId(secid, code) || (isTwii ? "TWII" : "");
    if (!stockId) return { ok: false, reason: "目前僅支援台股盤中診斷。" };
    const clock = twSessionClock();
    let intra = [];
    try { intra = await yahooOneMinBars(secid); } catch (err) { intra = []; }
    if (!intra.length) {
      try { intra = await fiveMinBars(secid); } catch (err2) { intra = []; }
    }
    let daily = [];
    try { daily = await bars(secid, "180d"); } catch (err) {
      if (!isTwii) {
        try { daily = await historyBars(secid, stockId, 180); } catch (e2) { daily = []; }
      } else daily = [];
    }
    if (!intra.length && !daily.length) {
      return { ok: false, reason: "盤中 K／日 K 暫讀不到。" };
    }
    const levels = findLevels(daily.length ? daily : intra);
    const atrArr = daily.length ? atr(daily, 14) : [];
    let atrNow = null;
    for (let i = atrArr.length - 1; i >= 0; i--) {
      if (atrArr[i] != null && isFinite(atrArr[i])) { atrNow = atrArr[i]; break; }
    }
    const lastIntra = intra.length ? intra[intra.length - 1] : null;
    const lastDaily = daily.length ? daily[daily.length - 1] : null;
    let price = lastIntra ? num(lastIntra.c) : null;
    if (!(price > 0) && lastDaily) price = num(lastDaily.c);
    if (!(price > 0)) return { ok: false, reason: "沒有可用現價。" };
    if (!(atrNow > 0)) atrNow = price * 0.015;

    let dayOpen = intra.length ? num(intra[0].o || intra[0].c) : null;
    let dayHigh = -Infinity;
    let dayLow = Infinity;
    let volSum = 0;
    const vols = [];
    intra.forEach(function (b) {
      const h = num(b.h); const l = num(b.l); const v = num(b.v) || 0;
      if (h > dayHigh) dayHigh = h;
      if (l < dayLow) dayLow = l;
      volSum += v;
      vols.push(v);
    });
    if (!isFinite(dayHigh)) dayHigh = price;
    if (!isFinite(dayLow)) dayLow = price;
    const avgVol = vols.length ? volSum / vols.length : 0;
    const recentN = Math.min(20, Math.max(5, Math.floor(vols.length / 4) || 5));
    const recentVol = vols.length
      ? vols.slice(-recentN).reduce(function (a, b) { return a + b; }, 0) / recentN
      : 0;
    const volRatio = avgVol > 0 ? recentVol / avgVol : 1;
    const shrink = volRatio < 0.72;
    const surge = volRatio > 1.25;

    const support = levels.support;
    const breakout = levels.breakout;
    const supFocus = support && support.focus != null ? support.focus : dayLow;
    const brkFocus = breakout && breakout.focus != null ? breakout.focus : dayHigh;
    const cost = opts.cost != null && isFinite(Number(opts.cost)) && Number(opts.cost) > 0
      ? Number(opts.cost) : null;
    const shares = opts.shares != null && isFinite(Number(opts.shares)) ? Number(opts.shares) : null;
    const vsCost = cost != null ? price - cost : null;
    const underWater = vsCost != null && vsCost < 0;
    const nearSup = Math.abs(price - supFocus) <= Math.max(atrNow * 0.55, tickSize(price) * 3);
    const belowSup = price < (support && support.low != null ? support.low : supFocus) - tickSize(price);
    const brokeDayLow = intra.length > 30 && price <= dayLow + tickSize(price) &&
      dayLow < (lastDaily ? num(lastDaily.l) : dayLow) + atrNow * 0.15;
    const pokedHigh = dayHigh >= brkFocus - tickSize(price);
    const failedBreak = pokedHigh && price < brkFocus - Math.max(atrNow * 0.25, tickSize(price) * 2);
    const reclaiming = dayOpen > 0 && price > dayOpen && price > (dayLow + (dayHigh - dayLow) * 0.55);
    const holdAboveSup = price > supFocus + tickSize(price);

    let stateId = "range";
    let stateLabel = "區間震盪";
    let stateTone = "";
    const why = [];

    if (belowSup || (brokeDayLow && price < (dayOpen || price))) {
      stateId = "weak_break";
      stateLabel = "弱勢破底";
      stateTone = "down";
      why.push(belowSup
        ? ("現價跌破日 K 支撐約 " + formatLevelPx(supFocus) + (support && support.why ? "（" + support.why + "）" : ""))
        : "盤中接近／刷新當日低點，偏弱");
      if (surge) why.push("破底過程量能偏熱，追價風險高");
      else if (shrink) why.push("量能未明顯放大，但仍失守關鍵價");
    } else if (failedBreak) {
      stateId = "fake_break";
      stateLabel = "假突破誘多";
      stateTone = "down";
      why.push("盤中曾觸及壓力約 " + formatLevelPx(brkFocus) + " 後拉回");
      if (!surge) why.push("突破段量能不足，誘多機率較高");
      else why.push("衝高後轉弱，宜防假突破");
    } else if (nearSup && shrink && holdAboveSup) {
      stateId = "dry_base";
      stateLabel = "量縮打底";
      stateTone = "";
      why.push("貼近支撐約 " + formatLevelPx(supFocus) + " 且近段量縮");
      why.push("尚未轉強，先當整理／打底看待");
    } else if (surge && reclaiming && holdAboveSup && !failedBreak) {
      stateId = "vol_turn";
      stateLabel = "帶量轉強";
      stateTone = "up";
      why.push("近段量能放大，價格守在開盤與支撐之上");
      if (price >= brkFocus - atrNow * 0.3) why.push("接近壓力 " + formatLevelPx(brkFocus) + "，留意能否站穩");
    } else {
      stateId = "range";
      stateLabel = "區間震盪";
      stateTone = "";
      why.push("位於支撐 " + formatLevelPx(supFocus) + " 與壓力 " + formatLevelPx(brkFocus) + " 之間");
      if (shrink) why.push("量能偏縮，方向未明");
    }

    if (cost != null) {
      why.push("自選成本 " + formatLevelPx(cost) +
        (vsCost >= 0 ? "（目前浮盈約 " + formatLevelPx(vsCost) + "）" : "（目前浮虧約 " + formatLevelPx(Math.abs(vsCost)) + "）"));
    }

    const defense = roundPx(Math.min(
      belowSup ? (support && support.low != null ? support.low : supFocus) : supFocus,
      dayLow + tickSize(price)
    ));
    const bounceSell = roundPx(Math.min(brkFocus, Math.max(price, dayOpen || price) + atrNow * 0.8));
    const trialBuy = roundPx(Math.max(supFocus, dayLow));

    let action = "續抱觀察";
    let actionSteps = [];
    let buyPoints = [];
    let sellPoints = [];
    const stopPoint = defense;
    if (stateId === "weak_break") {
      action = underWater ? "反彈減碼／設停損" : "反彈減碼優先";
      actionSteps = [
        "反彈靠近 " + formatLevelPx(bounceSell) + " 或成本附近優先減碼，不抄底攤平",
        "盤中若有效跌破防守價 " + formatLevelPx(defense) + " 且站不回，執行停損／清倉紀律",
        "若僅長下影後迅速站回 " + formatLevelPx(supFocus) + "，改為續抱觀察，但加碼暫緩"
      ];
      buyPoints = ["破底中不買、不攤平；僅長下影後迅速站回 " + formatLevelPx(supFocus) + " 才可極小試單"];
      sellPoints = [
        "反彈靠近 " + formatLevelPx(bounceSell) + (cost != null ? "／成本 " + formatLevelPx(cost) : "") + " 分批減碼",
        "帶量跌破防守 " + formatLevelPx(defense) + " 且站不回 → 停損出場"
      ];
    } else if (stateId === "fake_break") {
      action = "反彈減碼、不追高";
      actionSteps = [
        "假突破後不追壓力 " + formatLevelPx(brkFocus) + " 之上",
        "反彈至 " + formatLevelPx(roundPx((price + dayHigh) / 2)) + "～" + formatLevelPx(dayHigh) + " 分批減碼",
        "若跌破防守 " + formatLevelPx(defense) + "，轉為停損／減碼到底"
      ];
      buyPoints = ["假突破後暫不低接；等回測 " + formatLevelPx(supFocus) + " 且量縮止跌再小試"];
      sellPoints = [
        "反彈 " + formatLevelPx(roundPx((price + dayHigh) / 2)) + "～" + formatLevelPx(dayHigh) + "／壓力 " + formatLevelPx(brkFocus) + " 分批減",
        "破防守 " + formatLevelPx(defense) + " → 停損／減到底"
      ];
    } else if (stateId === "dry_base") {
      action = underWater ? "續抱觀察，低接僅小試" : "續抱觀察／支撐試單";
      actionSteps = [
        "守住 " + formatLevelPx(supFocus) + " 可續抱；量縮打底不宜追價",
        "僅在 " + formatLevelPx(trialBuy) + " 附近小量低接試單，破 " + formatLevelPx(defense) + " 立刻停損試單部位",
        cost != null && underWater
          ? "成本 " + formatLevelPx(cost) + " 上方反彈先減虧，勿一次攤平"
          : "帶量站上 " + formatLevelPx(roundPx((supFocus + brkFocus) / 2)) + " 再考慮加碼"
      ];
      buyPoints = [
        "買點約 " + formatLevelPx(trialBuy) + "：須量縮不破低／下影止跌後才試單，正在下跌勿接"
      ];
      sellPoints = [
        cost != null && underWater
          ? "反彈近成本 " + formatLevelPx(cost) + " 先減虧"
          : "反彈近壓力 " + formatLevelPx(brkFocus) + " 分批減，不貪突破",
        "破防守 " + formatLevelPx(defense) + " → 立刻停損試單部位"
      ];
    } else if (stateId === "vol_turn") {
      action = "續抱，回檔可試單";
      actionSteps = [
        "帶量轉強中，先續抱；回檔不破 " + formatLevelPx(supFocus) + " 可加碼／試單",
        "盯緊防守 " + formatLevelPx(defense) + "，跌破且量縮轉弱則先減碼保利",
        "接近壓力 " + formatLevelPx(brkFocus) + " 先別追高，等站穩再加"
      ];
      buyPoints = ["回檔不破 " + formatLevelPx(supFocus) + "～" + formatLevelPx(trialBuy) + " 可試單／加碼"];
      sellPoints = [
        "接近壓力 " + formatLevelPx(brkFocus) + " 先別追；量縮遇壓可先減部分保利",
        "跌破防守 " + formatLevelPx(defense) + " → 減碼保利／停損加碼單"
      ];
    } else {
      action = "區間操作（低買高賣）";
      actionSteps = [
        "買在下緣止跌：回測 " + formatLevelPx(trialBuy) + " 須見量縮不破低／下影／站回均價才試單，正在下跌勿接",
        "賣在上緣遇壓：反彈近 " + formatLevelPx(brkFocus) + " 且量能無法放大就分批了結，不貪一次突破",
        "破底即停損：帶量跌破下緣／防守 " + formatLevelPx(defense) + " 立刻停損，禁止向下攤平"
      ];
      buyPoints = [
        "區間下緣約 " + formatLevelPx(trialBuy) + "（支撐 " + formatLevelPx(supFocus) + "）：止跌訊號出現後小量試單"
      ];
      sellPoints = [
        "區間上緣約 " + formatLevelPx(brkFocus) + "：遇壓量縮即分批賣出／減碼",
        cost != null
          ? ("對照成本 " + formatLevelPx(cost) + "：浮盈可規畫減碼比例，浮虧勿急攤")
          : "無成本時嚴格依上緣減碼、下緣停損"
      ];
      if (why.indexOf("區間操作前提：下緣未破、上緣不過；帶量破下緣立刻停止低接並停損") < 0) {
        why.push("區間操作前提：下緣未破、上緣不過；帶量破下緣立刻停止低接並停損");
      }
    }

    const mid = roundPx((supFocus + brkFocus) / 2);
    const weekLow = roundPx(supFocus - atrNow * 0.8);
    const weekHigh = roundPx(brkFocus + atrNow * 0.5);
    let tomorrow = { label: "續抱觀察", steps: [] };
    let days5 = { label: "波段觀望", steps: [] };
    if (stateId === "weak_break") {
      tomorrow = {
        label: "反彈減碼／停損優先",
        steps: [
          "開盤若低開或翻黑，先看能否站回 " + formatLevelPx(defense) + "；站不回則執行停損",
          "反彈至 " + formatLevelPx(bounceSell) + (cost != null ? "／成本 " + formatLevelPx(cost) : "") + " 分批減碼，不攤平",
          "唯有帶量長陽收復 " + formatLevelPx(supFocus) + " 才改續抱，加碼仍暫緩"
        ]
      };
      days5 = {
        label: "偏空控險",
        steps: [
          "5 日內以反彈減碼為主，目標壓在 " + formatLevelPx(mid) + "～" + formatLevelPx(brkFocus),
          "日線若連破 " + formatLevelPx(weekLow) + "，倉位降到輕倉或清倉",
          cost != null && underWater
            ? "成本 " + formatLevelPx(cost) + " 上方反彈先減虧，勿一次回補攤平"
            : "未站回日 K 支撐前，只允許極小試單且嚴設停損"
        ]
      };
    } else if (stateId === "fake_break") {
      tomorrow = {
        label: "不追高、反彈減",
        steps: [
          "開高不追；若再測 " + formatLevelPx(brkFocus) + " 量能不足則減碼",
          "回落守 " + formatLevelPx(defense) + " 可續抱觀察，破則停損／減到底",
          "反彈 " + formatLevelPx(roundPx((price + dayHigh) / 2)) + "～" + formatLevelPx(dayHigh) + " 先出部分"
        ]
      };
      days5 = {
        label: "壓力區高賣低等",
        steps: [
          "5 日內壓力盯 " + formatLevelPx(brkFocus) + "，假突破後宜高賣低等",
          "收復並站穩壓力之上再轉偏多；否則區間上緣減碼",
          "防守失守 " + formatLevelPx(supFocus) + " 後，等回測確認再決定是否回補"
        ]
      };
    } else if (stateId === "dry_base") {
      tomorrow = {
        label: "續抱／支撐小試",
        steps: [
          "開盤量縮震盪以續抱為主，不追價",
          "回測 " + formatLevelPx(trialBuy) + " 可小量低接，破 " + formatLevelPx(defense) + " 立刻停試單",
          cost != null && underWater
            ? "反彈靠近成本 " + formatLevelPx(cost) + " 先減虧一部分"
            : "帶量站上 " + formatLevelPx(mid) + " 再考慮加碼"
        ]
      };
      days5 = {
        label: "打底等待轉強",
        steps: [
          "5 日內守 " + formatLevelPx(supFocus) + " 當底；量縮盤整可續抱",
          "帶量突破 " + formatLevelPx(brkFocus) + " 才轉偏多加碼，目標上看 " + formatLevelPx(weekHigh),
          "日線失守 " + formatLevelPx(defense) + " 則改偏空，反彈減碼"
        ]
      };
    } else if (stateId === "vol_turn") {
      tomorrow = {
        label: "續抱、回檔試單",
        steps: [
          "開盤偏強可續抱；回檔不破 " + formatLevelPx(supFocus) + " 可試單／加碼",
          "接近 " + formatLevelPx(brkFocus) + " 先別追，等站穩再加",
          "若翻弱跌破 " + formatLevelPx(defense) + "，先減碼保利"
        ]
      };
      days5 = {
        label: "偏多抱股控回檔",
        steps: [
          "5 日偏多：回檔買在 " + formatLevelPx(supFocus) + "～" + formatLevelPx(mid),
          "站穩 " + formatLevelPx(brkFocus) + " 後再往 " + formatLevelPx(weekHigh) + " 看漲",
          "日線轉弱跌破 " + formatLevelPx(defense) + " 則降倉，等量縮再接"
        ]
      };
    } else {
      tomorrow = {
        label: "區間低買高賣",
        steps: [
          "開盤先對照下緣 " + formatLevelPx(supFocus) + "／上緣 " + formatLevelPx(brkFocus),
          "回測下緣須止跌才接；靠近上緣量縮就減，不追突破",
          "破 " + formatLevelPx(defense) + " 立刻停損，禁止攤平"
        ]
      };
      days5 = {
        label: "箱型高賣低買",
        steps: [
          "5 日以 " + formatLevelPx(supFocus) + "～" + formatLevelPx(brkFocus) + " 做區間，部位不宜過重",
          "有效跌破 " + formatLevelPx(weekLow) + " 改偏空停低接；站穩 " + formatLevelPx(weekHigh) + " 才改追多",
          "大盤劇烈震盪日：只做有止跌訊號的下緣試單，其餘空手等"
        ]
      };
    }

    return {
      ok: true,
      code: stockId,
      sessionOpen: clock.open,
      asOf: clock.label,
      source: intra.length && String(intra[0].t || "").indexOf(":") >= 0 ? "1m/5m" : "daily",
      price: roundPx(price),
      dayOpen: dayOpen != null ? roundPx(dayOpen) : null,
      dayHigh: roundPx(dayHigh),
      dayLow: roundPx(dayLow),
      volRatio: Math.round(volRatio * 100) / 100,
      cost: cost != null ? roundPx(cost) : null,
      shares: shares,
      support: support,
      breakout: breakout,
      defense: defense,
      buyPoints: buyPoints,
      sellPoints: sellPoints,
      stopPoint: stopPoint,
      buyLevel: trialBuy,
      sellLevel: brkFocus,
      stateId: stateId,
      stateLabel: stateLabel,
      stateTone: stateTone,
      why: why,
      action: action,
      actionSteps: actionSteps,
      tomorrow: tomorrow,
      days5: days5,
      tip: "規則依盤中分 K＋日 K 支撐壓力試算，非投資建議；盤中籌碼可能尚未公告。"
    };
  }

  async function stockAdvice(secid, code) {
    const stockId = twStockId(secid, code);
    if (!stockId) return { ok: false, reason: "目前僅支援台股綜合研判。" };
    const detail = await stockDetail(secid, code).catch(function () { return { ok: false }; });
    let tech = null;
    try { tech = await technical(secid); } catch (err) { tech = null; }
    let daily = [];
    try {
      daily = await bars(secid, "180d");
    } catch (err) {
      try { daily = await historyBars(secid, stockId, 180); } catch (e2) { daily = []; }
    }
    const patterns = kPatterns(daily).slice(0, 10);
    const close = tech && tech.close != null
      ? tech.close
      : (detail.quote && detail.quote.close != null ? detail.quote.close : (daily.length ? daily[daily.length - 1].c : null));
    const atrArr = daily.length ? atr(daily, 14) : [];
    let atrNow = null;
    for (let i = atrArr.length - 1; i >= 0; i--) {
      if (atrArr[i] != null && isFinite(atrArr[i])) { atrNow = atrArr[i]; break; }
    }
    if (!(atrNow > 0) && close > 0) atrNow = close * 0.02;

    const m = (detail && detail.margins) || {};
    const per = detail && detail.per;
    const own = (detail && detail.ownership) || {};
    const chips = detail && detail.chipCards ? detail.chipCards : [];
    const chipDate = detail && detail.chipDate ? detail.chipDate : "";

    let fundScore = 0;
    const fundNotes = [];
    if (m.grossTrend && m.grossTrend.cls === "up") { fundScore += 1; fundNotes.push("毛利率較上季上升"); }
    else if (m.grossTrend && m.grossTrend.cls === "down") { fundScore -= 1; fundNotes.push("毛利率較上季下降"); }
    if (m.opTrend && m.opTrend.cls === "up") { fundScore += 1; fundNotes.push("營益率上升"); }
    else if (m.opTrend && m.opTrend.cls === "down") { fundScore -= 1; fundNotes.push("營益率下降"); }
    if (m.netTrend && m.netTrend.cls === "up") { fundScore += 1; fundNotes.push("淨利率上升"); }
    else if (m.netTrend && m.netTrend.cls === "down") { fundScore -= 1; fundNotes.push("淨利率下降"); }
    if (per && per.per != null && isFinite(per.per)) {
      if (per.per > 0 && per.per <= 20) { fundScore += 1; fundNotes.push("本益比 " + per.per.toFixed(1) + " 偏低檔區"); }
      else if (per.per > 40) { fundScore -= 1; fundNotes.push("本益比 " + per.per.toFixed(1) + " 偏高"); }
      else fundNotes.push("本益比 " + per.per.toFixed(1));
    } else fundNotes.push("本益比暫無");
    if (!fundNotes.length) fundNotes.push("財務資料不足");

    let chipScore = 0;
    const chipNotes = [];
    const foreignCard = chips.find(function (c) { return c.name === "外資"; });
    const trustCard = chips.find(function (c) { return c.name === "投信"; });
    const totalCard = chips.find(function (c) { return c.name === "法人"; });
    function lotsOf(net) {
      if (net == null || !isFinite(net)) return null;
      return Math.round(net / 1000);
    }
    if (foreignCard && foreignCard.net != null) {
      const lots = lotsOf(foreignCard.net);
      chipNotes.push("外資 " + (lots > 0 ? "+" : "") + lots + " 張");
      if (foreignCard.net > 0) chipScore += 1;
      else if (foreignCard.net < 0) chipScore -= 1;
    }
    if (trustCard && trustCard.net != null) {
      const lots = lotsOf(trustCard.net);
      chipNotes.push("投信 " + (lots > 0 ? "+" : "") + lots + " 張");
      if (trustCard.net > 0) chipScore += 1;
      else if (trustCard.net < 0) chipScore -= 1;
    }
    if (own.flow5 && own.flow5.total != null) {
      const lots = lotsOf(own.flow5.total);
      chipNotes.push("近5日法人合計 " + (lots > 0 ? "+" : "") + lots + " 張");
      if (own.flow5.total > 0) chipScore += 1;
      else if (own.flow5.total < 0) chipScore -= 1;
    }
    if (own.foreignPct != null) chipNotes.push("外資持股 " + Number(own.foreignPct).toFixed(1) + "%");
    if (!chipNotes.length) chipNotes.push(chipDate ? "籌碼日 " + chipDate + " 無明細" : "籌碼暫無");

    let techScore = 0;
    if (tech) {
      if (tech.verdict === "買進") techScore += 2;
      else if (tech.verdict === "賣出") techScore -= 2;
      (tech.steps || []).forEach(function (s) {
        if (s.pass) techScore += 0.5;
        else techScore -= 0.25;
      });
    }
    const bullishK = /大陽|晨星|紅三兵|懷抱|曙光|探底|三川|鍋底|上升三法|U字/;
    const bearishK = /大陰|夜星|黑三兵|覆蓋|烏雲|吊首|三山|半圓天井|下降三法/;
    let kScore = 0;
    patterns.slice(0, 5).forEach(function (p) {
      if (p.bias === "多" || bullishK.test(p.name)) kScore += 1;
      else if (p.bias === "空" || bearishK.test(p.name)) kScore -= 1;
    });

    const total = fundScore + chipScore + techScore + kScore;
    let advice = "觀望";
    if (total >= 4 && (!tech || tech.verdict !== "賣出")) advice = "建議買進";
    else if (total >= 2) advice = "偏多觀望";
    else if (total <= -4 || (tech && tech.verdict === "賣出")) advice = "偏賣／減碼";
    else if (total <= -2) advice = "偏空觀望";

    const supports = (tech && tech.supports) || [];
    const resistances = (tech && tech.resistances) || [];
    const buyLevel = supports.length ? supports[supports.length - 1] : (close > 0 && atrNow ? roundPx(close - atrNow) : null);
    const sellLevel = resistances.length ? resistances[0] : (close > 0 && atrNow ? roundPx(close + 1.5 * atrNow) : null);
    const stopLevel = close > 0 && atrNow ? roundPx(close - 1.5 * atrNow) : null;
    const recentBull = patterns.find(function (p) { return p.bias === "多" || bullishK.test(p.name); });
    const recentBear = patterns.find(function (p) { return p.bias === "空" || bearishK.test(p.name); });

    const buyPoints = [];
    if (buyLevel != null) buyPoints.push("回檔近支撐／買點約 " + buyLevel + (atrNow ? "（約 1×ATR）" : ""));
    if (recentBull) buyPoints.push("近期偏多型態「" + recentBull.name + "」（" + recentBull.date + "）：" + recentBull.detail);
    if (tech && tech.verdict === "買進") buyPoints.push("日週線條件偏多，可等拉回不破支撐再分批。");
    if (!buyPoints.length) buyPoints.push("暫無明確買點，先等支撐或偏多K型態。");

    const sellPoints = [];
    if (sellLevel != null) sellPoints.push("壓力／賣點約 " + sellLevel);
    if (stopLevel != null) sellPoints.push("防守停損約 " + stopLevel + "（約 1.5×ATR）");
    if (recentBear) sellPoints.push("近期偏空型態「" + recentBear.name + "」（" + recentBear.date + "）：" + recentBear.detail);
    if (tech && tech.verdict === "賣出") sellPoints.push("日週線偏空，反彈接近壓力優先減碼。");
    if (!sellPoints.length) sellPoints.push("暫無明確賣點，嚴格用停損控風險。");

    return {
      ok: true,
      name: (tech && tech.name) || (detail && detail.stockId) || stockId,
      code: stockId,
      close: close != null ? roundPx(close) : null,
      advice: advice,
      score: Math.round(total * 10) / 10,
      fund: {
        score: fundScore,
        notes: fundNotes,
        margins: m,
        per: per
      },
      chip: {
        score: chipScore,
        date: chipDate,
        notes: chipNotes,
        cards: chips
      },
      tech: tech,
      patterns: patterns,
      buyPoints: buyPoints,
      sellPoints: sellPoints,
      atr: atrNow != null ? roundPx(atrNow) : null
    };
  }

  // K 線型態：酒田戰法 78 式（sakata.js）。回傳由新到舊。
  function kPatterns(bars) {
    if (global.SJSakata && typeof global.SJSakata.detect === "function") {
      return global.SJSakata.detect(bars);
    }
    return [];
  }

  function sakataCatalog() {
    return (global.SJSakata && global.SJSakata.CATALOG) || [];
  }

  // 酒田術語 → 白話一句
  function plainSakataLine(name, detail, bias) {
    const n = String(name || "");
    const d = String(detail || "");
    if (/晨星|探底|三川|曙光|鍋底|U字/.test(n)) {
      return "看起來像「跌不下去、想反攻」：先殺低再快速拉回，表面止跌。";
    }
    if (/夜星|烏雲|覆蓋|黑三兵|吊首|三山|半圓天井|下降三法/.test(n)) {
      return "高檔轉弱訊號：漲完開始吐、空方接手，不宜再追高。";
    }
    if (/懷抱|吞沒/.test(n) || /吞沒|懷抱/.test(d)) {
      return bias === "空" || /黑吞|空/.test(d + n)
        ? "大黑K把前面紅K整個吃掉，常是「拉高出貨」：追高容易套在山頂。"
        : "大紅K吃掉前面黑K，短線偏多，但仍要看後面有沒有續攻量。";
    }
    if (/大陰|捉腰帶|迫切|切入/.test(n) || /禿頭禿腳|一路殺/.test(d)) {
      return "開高或反彈後一路殺到底、幾乎不回頭，賣方主導、買盤擋不住。";
    }
    if (/大陽|紅三兵|升勢/.test(n)) {
      return "連續紅K推升，買方較積極；若後面量縮遇壓，先別追太深。";
    }
    if (/跳空/.test(n) || /跳空/.test(d)) {
      return /下|空|賣/.test(d + n)
        ? "向下跳空：賣壓突然變大，短線偏弱。"
        : "向上跳空：買盤突然湧入，短線偏強但要防假突破。";
    }
    if (/極短|連續線|交錯/.test(n)) {
      return "震幅很小或多空收盤差不多，方向未明，先觀望等突破。";
    }
    if (/錘|吊人|十字/.test(n)) {
      return bias === "空"
        ? "高檔猶豫／反轉警訊，反彈宜減碼。"
        : "低檔試探止跌，需下一根確認才算數。";
    }
    // 後備：把原文縮成白話口吻
    if (d) return "（" + n + "）" + d.replace(/酒田|戰法/g, "").trim();
    return n + (bias ? "（偏" + bias + "）" : "");
  }

  // 解讀使用者框選的一段 K 線（白話狀態＋操作）
  function explainKRange(bars, name, opts) {
    opts = opts || {};
    const rows = (bars || []).filter(function (b) {
      return b && isFinite(b.o) && isFinite(b.h) && isFinite(b.l) && isFinite(b.c);
    });
    if (!rows.length) return null;
    const first = rows[0];
    const last = rows[rows.length - 1];
    let hi = -Infinity;
    let lo = Infinity;
    let upN = 0;
    let downN = 0;
    rows.forEach(function (b) {
      hi = Math.max(hi, b.h);
      lo = Math.min(lo, b.l);
      if (b.c > b.o) upN += 1;
      else if (b.c < b.o) downN += 1;
    });
    const base = first.o > 0 ? first.o : first.c;
    const chg = base > 0 ? last.c / base - 1 : 0;
    const span = hi > 0 && lo < Infinity ? (hi - lo) / hi : 0;
    const pats = kPatterns(rows);
    const topNames = [];
    const seen = {};
    pats.forEach(function (p) {
      if (!seen[p.name]) { seen[p.name] = true; topNames.push(p.name); }
    });

    let tone = "整理觀望";
    let meaning = "";
    let actions = [];
    const names = topNames.join(",");
    const hasBull = /晨星|探底|曙光|紅三兵|三川|鍋底|U字/.test(names);
    const hasBear = /夜星|烏雲|覆蓋|黑三兵|吊首|三山|半圓天井|下降三法|懷抱/.test(names) &&
      pats.some(function (p) { return p.bias === "空" || /黑吞|空|轉賣|出貨/.test(String(p.detail || "") + p.name); });
    const midHiThenWeak = hi > 0 && last.c < hi * 0.985 && (hasBear || downN >= upN);

    if (chg >= 0.04 && midHiThenWeak) {
      tone = "拉高後轉弱";
      meaning = "這段先衝高再吐回去，裡面常混著「看起來很強、其實有人趁高出貨」。框選若剛好停在反彈段，容易誤判成止跌。";
      actions = [
        "不要追框選內的最高價；反彈靠近高點先減碼",
        "破這段低點 " + formatLevelPx(lo) + " 且站不回，當轉弱／停損看待",
        "未重新站穩這段高點前，不做攤平低接"
      ];
    } else if (chg >= 0.08 && downN > upN && /夜星|烏雲|覆蓋|黑三兵|吊首|三山|半圓天井/.test(names)) {
      tone = "衝高轉弱";
      meaning = "這段先漲後出現轉弱型態，白話就是「漲完開始賣」。高檔不宜再追。";
      actions = [
        "反彈靠近高點 " + formatLevelPx(hi) + " 分批減碼",
        "破低點 " + formatLevelPx(lo) + " 執行停損／減倉",
        "不在高檔加碼"
      ];
    } else if (chg <= -0.06 || (downN >= upN + 2 && span >= 0.05)) {
      tone = "賣壓主導";
      meaning = "這段黑K／下殺偏多，賣方力氣比較大，短線偏續弱。";
      actions = [
        "反彈先減碼，不抄底攤平",
        "守不住低點 " + formatLevelPx(lo) + " 就停損",
        "等量縮止跌再談低接試單"
      ];
    } else if (chg >= 0.06 && upN > downN && !midHiThenWeak) {
      tone = "買盤推升";
      meaning = "這段紅K偏多、買方較積極；但只要後面開始量縮遇壓，就要改保守。";
      actions = [
        "回檔不破低點 " + formatLevelPx(lo) + " 可續抱／小試",
        "靠近高點 " + formatLevelPx(hi) + " 先別追，等站穩再加",
        "跌破低點改減碼"
      ];
    } else if (span < 0.03) {
      tone = "窄幅盤整";
      meaning = "上下震不大，多空膠著，方向還沒出來。";
      actions = [
        "等有效突破高點或跌破低點再動手",
        "區間內高賣低買、部位宜輕",
        "破低點 " + formatLevelPx(lo) + " 停損試單"
      ];
    } else if (hasBull && hasBear) {
      tone = "假反彈風險";
      meaning = "同時看到止跌／探底，也看到吞沒、大陰等轉弱訊號：白話是「有人想拉，但拉完可能出貨」。只看偏多那幾句會誤判。";
      actions = [
        "把這段當反彈觀察，不當進場追高理由",
        "反彈減碼優先；破低點 " + formatLevelPx(lo) + " 停損",
        "未站回高點前不做攤平"
      ];
    } else if (hasBull) {
      tone = "止跌試探";
      meaning = "出現探底／晨星一類訊號，表面像跌不下去想反攻；仍要下一根確認，且別只看框選、忽略後面走勢。";
      actions = [
        "僅小量試單，破低點 " + formatLevelPx(lo) + " 立刻停",
        "沒帶量站穩前，不加碼攤平",
        "反彈到前高附近先減部分"
      ];
    } else {
      tone = chg >= 0 ? "偏多整理" : "偏空整理";
      meaning = "這段沒有單一極端訊號，先當整理：用高低點紀律進出。";
      actions = [
        "上緣 " + formatLevelPx(hi) + " 附近減碼，下緣 " + formatLevelPx(lo) + " 附近才考慮試單",
        "破低點停損，不向下攤平",
        "方向不明時部位不宜過重"
      ];
    }

    // 框選只是當日一段、後面其實更弱 → 標盲點
    const all = (opts.allBars || []).filter(function (b) {
      return b && isFinite(b.c);
    });
    let warning = "";
    if (all.length > rows.length + 3) {
      const dayLast = all[all.length - 1];
      const dayClose = num(dayLast.c);
      if (dayClose > 0 && hi > 0 && dayClose < hi * 0.97 && dayClose < last.c * 0.985) {
        warning = "注意：你框的是其中一段。後面實際走到 " + formatLevelPx(dayClose) +
          "，比框選收盤更弱——框選若顯示「止跌／偏多」，可能只是早盤假反彈，要以完整走勢與防守價為準。";
        if (tone === "止跌試探" || tone === "買盤推升" || tone === "偏多整理") {
          tone = "假反彈後轉弱";
          meaning = "框選那段看起來像止跌反攻，但後面又明顯轉弱／破底。白話：拉高誘多後賣壓出手，不能只信框選內的偏多酒田。";
          actions = [
            "防守優先：破當日低點或框選低點 " + formatLevelPx(Math.min(lo, dayClose)) + " 執行停損",
            "反彈到框選中段～高點先減碼，不要等回成本才賣",
            "未打底站穩前，禁止低接攤平"
          ];
        }
      }
    }

    const plainPats = pats.slice(0, 10).map(function (p) {
      return {
        name: p.name,
        date: p.date,
        bias: p.bias,
        detail: p.detail,
        plain: plainSakataLine(p.name, p.detail, p.bias)
      };
    });

    const from = String(first.t || "").slice(0, 16);
    const to = String(last.t || "").slice(0, 16);
    return {
      name: name || "",
      from: from,
      to: to,
      bars: rows.length,
      open: roundPx(first.o),
      close: roundPx(last.c),
      high: roundPx(hi),
      low: roundPx(lo),
      change: chg,
      tone: tone,
      meaning: meaning,
      actions: actions,
      warning: warning,
      patterns: plainPats,
      upN: upN,
      downN: downN
    };
  }

  async function yahooSymbolQuote(symbol) {
    const queries = ["interval=1m&range=1d", "interval=1d&range=5d"];
    for (let q = 0; q < queries.length; q++) {
      try {
        const json = await yahooChart(symbol, queries[q]);
        const result = json && json.chart && json.chart.result && json.chart.result[0];
        if (!result) continue;
        const meta = result.meta || {};
        const closes = ((((result.indicators || {}).quote || [])[0] || {}).close || [])
          .filter(function (v) { return v != null && isFinite(Number(v)) && Number(v) > 0; })
          .map(Number);
        const lastBar = closes.length ? closes[closes.length - 1] : null;
        const price = (q === 0 && lastBar > 0 ? lastBar : null) ||
          num(meta.regularMarketPrice) || num(meta.postMarketPrice) || lastBar;
        if (!(price > 0)) continue;
        const prev = num(meta.previousClose) || num(meta.chartPreviousClose);
        let pct = prev ? (price / prev - 1) * 100 : num(meta.regularMarketChangePercent);
        let change = prev ? price - prev : num(meta.regularMarketChange);
        return {
          symbol: symbol,
          price: price,
          change: change,
          pct: pct,
          name: toTW(meta.shortName || meta.symbol || symbol)
        };
      } catch (err) { /* next */ }
    }
    return null;
  }

  async function txNightLatest() {
    try {
      const rows = await finMindRaw("TaiwanFuturesDaily", isoDaysAgo(10), "TX");
      const byDay = {};
      rows.forEach(function (row) {
        const close = num(row.close);
        const vol = num(row.volume) || 0;
        if (!(close > 0)) return;
        if (String(row.contract_date || "").indexOf("/") >= 0) return;
        const session = String(row.trading_session || "");
        // 夜盤優先
        const pref = session === "after_market" ? 2 : session === "regular" ? 1 : 0;
        const cur = byDay[row.date];
        if (!cur || pref > cur.pref || (pref === cur.pref && vol > cur.volume)) {
          byDay[row.date] = {
            date: row.date,
            close: close,
            volume: vol,
            pref: pref,
            session: session || "—",
            basisPct: num(row.spread_per),
            contract: row.contract_date
          };
        }
      });
      const days = Object.keys(byDay).sort();
      if (!days.length) return null;
      const last = byDay[days[days.length - 1]];
      const prev = days.length > 1 ? byDay[days[days.length - 2]] : null;
      const change = prev && prev.close ? last.close - prev.close : null;
      const pct = prev && prev.close ? (last.close / prev.close - 1) * 100 : null;
      return {
        date: last.date,
        close: last.close,
        change: change,
        pct: pct,
        session: last.session,
        basisPct: last.basisPct,
        contract: last.contract,
        isNight: last.session === "after_market"
      };
    } catch (err) {
      return null;
    }
  }

  function pulseTone(pct, goodIsUp) {
    if (pct == null || !isFinite(pct)) return { label: "—", cls: "" };
    const up = goodIsUp !== false;
    if (Math.abs(pct) < 0.15) return { label: "中立", cls: "" };
    if (pct > 0) return { label: up ? "偏多" : "偏空", cls: up ? "up" : "down" };
    return { label: up ? "偏空" : "偏多", cls: up ? "down" : "up" };
  }

  async function twPulse() {
    const usList = [
      { key: "dji", symbol: "^DJI", name: "道瓊" },
      { key: "spx", symbol: "^GSPC", name: "標普500" },
      { key: "ndx", symbol: "^NDX", name: "那斯達克100" },
      { key: "sox", symbol: "^SOX", name: "費半" },
      { key: "nvda", symbol: "NVDA", name: "輝達" },
      { key: "tsm", symbol: "TSM", name: "台積電ADR" }
    ];
    const got = await Promise.all([
      Promise.all(usList.map(async function (item) {
        const q = await yahooSymbolQuote(item.symbol).catch(function () { return null; });
        return {
          key: item.key,
          name: item.name,
          symbol: item.symbol,
          price: q && q.price,
          pct: q && q.pct,
          change: q && q.change,
          tone: pulseTone(q && q.pct, true)
        };
      })),
      txNightLatest().catch(function () { return null; }),
      twiiQuote().catch(function () { return null; }),
      misQuotes(["O00"]).then(function (board) {
        const q = board && board.O00;
        if (q && q.price > 0) return q;
        return yahooSymbolQuote("^TWOII");
      }).catch(function () { return yahooSymbolQuote("^TWOII").catch(function () { return null; }); }),
      yahooQuote("fx.USDTWD").catch(function () { return null; }),
      latestTwseT86(12).catch(function () { return { ok: false }; }),
      txForeignFutSeries(40).catch(function () { return []; }),
      marginSeries(40).catch(function () { return []; }),
      (async function () {
        const end = taipeiYmd();
        const candidates = twseWeekdayYmds(end, 8);
        for (let i = 0; i < candidates.length; i++) {
          const hit = await twseMiIndex(candidates[i]);
          if (hit && hit.ok) return hit;
        }
        return { ok: false };
      })(),
      foreignNets().catch(function () { return {}; }),
      breadthProxySeries(20).catch(function () { return []; })
    ]);

    const us = got[0];
    const night = got[1];
    const twii = got[2];
    const otcQ = got[3];
    const fx = got[4];
    const t86 = got[5];
    const futOi = got[6] || [];
    const margins = got[7] || [];
    const mi = got[8] || {};
    const foreign = got[9] || {};
    const breadth = got[10] || [];

    let foreignSpot = null;
    if (t86 && t86.ok && t86.rows && t86.rows.length) {
      foreignSpot = t86.rows.reduce(function (a, r) {
        return a + (num(r.foreignNet) || 0);
      }, 0);
    } else if (foreign["1d"] != null) {
      foreignSpot = foreign["1d"] * 1e8;
    }

    const lastFut = futOi.length ? futOi[futOi.length - 1] : null;
    const lastMargin = margins.length ? margins[margins.length - 1] : null;
    const prevMargin = margins.length > 1 ? margins[margins.length - 2] : null;
    const marginDeltaAmt = lastMargin && prevMargin
      ? lastMargin.balance - prevMargin.balance
      : null;

    const amount = mi.amount;
    // 近 5 日量能（用加權成交金額近似：有多日 MI 才準；此版用當日＋備註）
    const up = mi.breadth && mi.breadth.up;
    const down = mi.breadth && mi.breadth.down;
    const adl = (up != null && down != null) ? (up - down) : null;

    const otcPct = otcQ && otcQ.pct;
    const twPct = twii && twii.pct;
    const structure = {
      pullWeighted: (twPct != null && otcPct != null && twPct > 0.3 && otcPct < -0.2),
      broadUp: (twPct != null && otcPct != null && twPct > 0 && otcPct > 0),
      note: ""
    };
    if (structure.pullWeighted) structure.note = "加權漲、櫃買弱 → 留意權值拉積盤";
    else if (structure.broadUp) structure.note = "加權與櫃買同向偏多 → 結構較健康";
    else if (twPct != null && otcPct != null && twPct < 0 && otcPct < 0) structure.note = "加權與櫃買同弱";
    else structure.note = "結構中性／待觀察";

    let chipBias = "中性";
    let chipNote = "";
    const futNet = lastFut && lastFut.netOi;
    const futDelta = lastFut && lastFut.delta;
    if (foreignSpot != null && futNet != null) {
      const spotBuy = foreignSpot > 0;
      const futLong = futNet > 0;
      if (spotBuy && futLong && (futDelta == null || futDelta >= 0)) {
        chipBias = "雙多";
        chipNote = "外資現貨偏買且期貨淨多單偏多／增持";
      } else if (spotBuy && futNet < -20000) {
        chipBias = "避險警訊";
        chipNote = "現貨買、期貨淨空單偏高，留意拉回";
      } else if (!spotBuy && !futLong) {
        chipBias = "偏空";
        chipNote = "現貨與期貨同偏空";
      } else {
        chipBias = "分歧";
        chipNote = "現貨與期貨方向不一致";
      }
    }

    let marginBias = "—";
    let marginNote = "公開免費源暫無融資維持率％，改看融資餘額變化。";
    if (lastMargin && lastMargin.chg != null) {
      if (lastMargin.chg < -0.02) {
        marginBias = "洗盤／去槓桿";
        marginNote = "融資餘額明顯下降，接近恐慌去槓桿區時反而常是反彈觀察點（非投資建議）。";
      } else if (lastMargin.chg > 0.015) {
        marginBias = "融資增溫";
        marginNote = "融資餘額上升，散戶追價意味較濃。";
      } else {
        marginBias = "平穩";
        marginNote = "融資餘額變化不大。";
      }
    }

    const sox = us.find(function (x) { return x.key === "sox"; });
    const tsm = us.find(function (x) { return x.key === "tsm"; });
    const preBiasScore =
      (sox && sox.pct != null ? sox.pct * 1.2 : 0) +
      (tsm && tsm.pct != null ? tsm.pct * 1.0 : 0) +
      (night && night.pct != null ? night.pct * 1.4 : 0);
    const preBias = pulseTone(preBiasScore, true);

    return {
      ok: true,
      updatedAt: Date.now(),
      pre: {
        us: us,
        night: night,
        bias: preBias,
        tip: "費半／台積電 ADR／台指期夜盤偏多 → 開高機率升；反之開低機率升。"
      },
      session: {
        twii: twii,
        otc: otcQ ? { price: otcQ.price, pct: otcQ.pct, change: otcQ.change, name: "櫃買" } : null,
        fx: fx ? {
          price: fx.price,
          pct: fx.pct,
          change: fx.change,
          // TWD=X 數字變大＝台幣貶（匯出）
          tone: pulseTone(fx.pct, false),
          tip: "匯率數字變小＝台幣升值／熱錢偏流入；變大＝貶值／偏匯出。"
        } : null,
        amount: amount,
        amountYi: amount != null ? amount / 1e8 : null,
        breadth: { up: up, down: down, flat: mi.breadth && mi.breadth.flat, adl: adl },
        structure: structure,
        miDate: mi.date || "",
        tip: "上漲要看櫃買與漲跌家數是否同步；只漲權值、櫃買／下跌家數偏多＝賺指數賠差價風險。"
      },
      chips: {
        date: (t86 && t86.date) || (lastFut && lastFut.date) || "",
        foreignSpot: foreignSpot,
        foreignSpotYi: foreignSpot != null ? foreignSpot / 1e8 : null,
        foreignFutNet: futNet,
        foreignFutDelta: futDelta,
        bias: chipBias,
        note: chipNote,
        marginBalance: lastMargin && lastMargin.balance,
        marginChg: lastMargin && lastMargin.chg,
        marginDelta: marginDeltaAmt,
        marginBias: marginBias,
        marginNote: marginNote,
        tip: "雙多（現貨買＋期貨淨多）最穩；現貨買但淨空單擴大＝避險警訊。"
      },
      note: "規則試算，非投資建議。夜盤／法人以 FinMind／證交所為主；盤中櫃買若 Yahoo 代號異動可能暫缺。"
    };
  }

