  function parseCmoneyForumMarkdown(text, stockId) {
    const out = [];
    const seen = {};
    const re = /\[([^\]]+)\]\(https:\/\/www\.cmoney\.tw\/forum\/article\/(\d+)\)/g;
    let m;
    const lines = String(text || "").split(/\r?\n/);
    while ((m = re.exec(text))) {
      const label = String(m[1] || "").trim();
      const id = m[2];
      if (seen[id]) continue;
      const isTime = /前$|昨天|剛剛|^\d{1,2}:\d{2}$|^\d{4}[\/\-]\d{1,2}/.test(label);
      let title = isTime ? "" : label;
      if (!title || title.length < 4) {
        const idx = text.slice(0, m.index).split(/\r?\n/).length - 1;
        for (let i = idx; i >= Math.max(0, idx - 8); i--) {
          const ln = (lines[i] || "").trim();
          const hm = ln.match(/^#{1,3}\s+(.+)/);
          if (hm && hm[1] && !/看過 .+ 的人也會看/.test(hm[1])) {
            title = hm[1].trim();
            break;
          }
        }
      }
      if (!title || title.length < 2) continue;
      if (/發文者頭像|頭像|通知|追蹤|登入/.test(title)) continue;
      seen[id] = true;
      out.push({
        title: title.slice(0, 120),
        url: "https://www.cmoney.tw/forum/article/" + id,
        source: "CMoney 爆料同學會",
        date: isTime ? label : "",
        kind: "cmoney"
      });
      if (out.length >= 12) break;
    }
    return out;
  }

  async function fetchCmoneyForumNews(stockId) {
    const page = "https://www.cmoney.tw/forum/stock/" + encodeURIComponent(stockId);
    try {
      const res = await fetch("https://r.jina.ai/" + page);
      if (!res.ok) return [];
      const text = await res.text();
      return parseCmoneyForumMarkdown(text, stockId);
    } catch (err) {
      return [];
    }
  }

  async function fetchFinMindNews(stockId) {
    const starts = [isoDaysAgo(14), isoDaysAgo(60), isoDaysAgo(180)];
    for (let i = 0; i < starts.length; i++) {
      try {
        const rows = await finMind("TaiwanStockNews", stockId, starts[i]);
        if (rows && rows.length) {
          return rows.slice().reverse().slice(0, 15).map(function (row) {
            return {
              title: row.title || "",
              url: row.link || "",
              source: row.source || "媒體",
              date: String(row.date || "").slice(0, 16),
              kind: "media"
            };
          }).filter(function (row) { return row.title && row.url; });
        }
      } catch (err) { /* next window */ }
    }
    return [];
  }

  async function stockNews(stockId) {
    const id = String(stockId || "").trim();
    if (!id) return { ok: false, items: [], links: mopsLinks("") };
    const links = mopsLinks(id);
    const got = await Promise.all([
      fetchCmoneyForumNews(id),
      fetchFinMindNews(id)
    ]);
    const cmoney = got[0] || [];
    const media = got[1] || [];
    const items = cmoney.concat(media).slice(0, 20);
    return {
      ok: items.length > 0,
      items: items,
      links: {
        forum: links.cmoneyForum,
        stock: links.cmoneyStock,
        noteRef: links.cmoneyNoteRef
      },
      note: "新聞以 CMoney 爆料同學會為主，並輔以 FinMind 彙整媒體標題；教學參考文見 CMoney 筆記。"
    };
  }

  function revenueYoYMoM(rows) {
    const list = (rows || []).slice().sort(function (a, b) {
      const ya = Number(a.revenue_year) * 100 + Number(a.revenue_month);
      const yb = Number(b.revenue_year) * 100 + Number(b.revenue_month);
      return ya - yb;
    });
    return list.map(function (row, i) {
      const rev = num(row.revenue);
      const ym = Number(row.revenue_year) * 100 + Number(row.revenue_month);
      let mom = null;
      let yoy = null;
      if (i > 0) {
        const prev = num(list[i - 1].revenue);
        if (prev > 0 && rev != null) mom = (rev / prev - 1) * 100;
      }
      for (let j = i - 1; j >= 0; j--) {
        const p = list[j];
        const pym = Number(p.revenue_year) * 100 + Number(p.revenue_month);
        if (pym === ym - 100 || (Number(row.revenue_month) === Number(p.revenue_month) &&
          Number(row.revenue_year) === Number(p.revenue_year) + 1)) {
          const prevY = num(p.revenue);
          if (prevY > 0 && rev != null) yoy = (rev / prevY - 1) * 100;
          break;
        }
      }
      return {
        year: row.revenue_year,
        month: row.revenue_month,
        date: row.date,
        revenue: rev,
        mom: mom,
        yoy: yoy
      };
    }).reverse();
  }

  async function stockDisclose(secid, code) {
    const stockId = twStockId(secid, code);
    if (!stockId) return { ok: false, reason: "目前僅支援台股代號。" };
    const links = mopsLinks(stockId);
    const startRev = isoDaysAgo(800);
    const startFin = isoDaysAgo(2000);
    const startDiv = isoDaysAgo(2500);
    const startOwn = isoDaysAgo(400);
    const got = await Promise.all([
      finMind("TaiwanStockMonthRevenue", stockId, startRev).catch(function () { return []; }),
      finMind("TaiwanStockFinancialStatements", stockId, startFin).catch(function () { return []; }),
      finMind("TaiwanStockBalanceSheet", stockId, startFin).catch(function () { return []; }),
      finMind("TaiwanStockDividend", stockId, startDiv).catch(function () { return []; }),
      finMind("TaiwanStockDividendResult", stockId, startDiv).catch(function () { return []; }),
      finMind("TaiwanStockShareholding", stockId, startOwn).catch(function () { return []; }),
      stockNews(stockId).catch(function () { return null; })
    ]);
    const newsPack = got[6];
    const revRows = revenueYoYMoM(got[0]).slice(0, 18);
    const fin = quarterBag(got[1]);
    const lastQ = fin.length ? fin[fin.length - 1] : null;
    const prevQ = fin.length > 1 ? fin[fin.length - 2] : null;
    const prev2Q = fin.length > 2 ? fin[fin.length - 3] : null;
    function marginOf(row, key) {
      if (!row || !(row.Revenue > 0) || row[key] == null) return null;
      return row[key] / row.Revenue * 100;
    }
    function marginHistOf(key) {
      return [marginOf(lastQ, key), marginOf(prevQ, key), marginOf(prev2Q, key)];
    }
    const balByDate = {};
    (got[2] || []).forEach(function (row) {
      if (!balByDate[row.date]) balByDate[row.date] = { date: row.date };
      balByDate[row.date][row.type] = num(row.value);
    });
    const balDates = Object.keys(balByDate).sort();
    const lastBal = balDates.length ? balByDate[balDates[balDates.length - 1]] : null;
    let debtRatio = null;
    if (lastBal) {
      const assets = lastBal.TotalAssets || lastBal.Assets;
      const liab = lastBal.TotalLiabilities || lastBal.Liabilities;
      if (assets > 0 && liab != null) debtRatio = liab / assets * 100;
    }
    const grossHistQ = lastQ ? marginHistOf("GrossProfit") : null;
    const opHistQ = lastQ ? marginHistOf("OperatingIncome") : null;
    const netHistQ = lastQ ? marginHistOf("IncomeAfterTaxes") : null;
    const margins = lastQ ? {
      date: lastQ.date,
      gross: grossHistQ[0],
      op: opHistQ[0],
      net: netHistQ[0],
      grossHist: grossHistQ,
      opHist: opHistQ,
      netHist: netHistQ,
      eps: lastQ.EPS != null ? num(lastQ.EPS) : null
    } : null;
    const divRows = (got[3] || []).slice().sort(function (a, b) {
      return String(b.date || "").localeCompare(String(a.date || ""));
    }).slice(0, 8).map(function (row) {
      return {
        date: row.date,
        year: row.year,
        cash: num(row.CashEarningsDistribution) || num(row.CashStatutorySurplus),
        stock: num(row.StockEarningsDistribution) || num(row.StockStatutorySurplus),
        exCash: row.CashExDividendTradingDate || "",
        payCash: row.CashDividendPaymentDate || "",
        exStock: row.StockExDividendTradingDate || ""
      };
    });
    const divResult = (got[4] || []).slice().sort(function (a, b) {
      return String(b.date || "").localeCompare(String(a.date || ""));
    }).slice(0, 6);
    const own = (got[5] || []).slice().sort(function (a, b) {
      return String(a.date).localeCompare(String(b.date));
    });
    const lastOwn = own.length ? own[own.length - 1] : null;

    return {
      ok: true,
      stockId: stockId,
      links: links,
      material: {
        ready: false,
        note: "重訊全文改版後以 MOPS 為準；此區先提供深連結，後續接 CSV／摘要 API。",
        items: []
      },
      revenue: {
        ready: !!revRows.length,
        rows: revRows,
        note: revRows.length
          ? "來源 FinMind 月營收；觀察 YoY／MoM 是否連創高。"
          : "月營收暫無資料（可能需 FinMind token 或代號無申報）。"
      },
      financial: {
        ready: !!margins,
        date: margins && margins.date,
        gross: margins && margins.gross,
        op: margins && margins.op,
        net: margins && margins.net,
        grossHist: margins && margins.grossHist,
        opHist: margins && margins.opHist,
        netHist: margins && margins.netHist,
        eps: margins && margins.eps,
        grossTrend: margins ? rateTrend(margins.gross, margins.grossHist[1]) : null,
        opTrend: margins ? rateTrend(margins.op, margins.opHist[1]) : null,
        netTrend: margins ? rateTrend(margins.net, margins.netHist[1]) : null,
        debtRatio: debtRatio,
        note: "損益／資產負債來自 FinMind；完整四大表與會計師意見請開 MOPS／XBRL。"
      },
      ir: {
        ready: false,
        note: "法說會日期／直播／簡報 PDF 規劃接 MOPS 與公司 IR；目前提供觀測站入口。",
        items: []
      },
      insider: {
        ready: !!lastOwn,
        foreignPct: lastOwn ? num(lastOwn.ForeignInvestmentSharesRatio) : null,
        date: lastOwn && lastOwn.date,
        note: "外資持股占比可作籌碼參考；董監轉讓預告／質押／庫藏股進度請開 MOPS（後續自動化）。"
      },
      dividend: {
        ready: !!(divRows.length || divResult.length),
        rows: divRows,
        results: divResult.map(function (row) {
          return {
            date: row.date,
            before: num(row.before_price),
            after: num(row.after_price),
            stockAndCash: num(row.stock_and_cache_dividend) || num(row.stock_and_cash_dividend)
          };
        }),
        note: divRows.length || divResult.length
          ? "股利政策／除權息結果來自 FinMind。"
          : "尚無股利資料。"
      },
      news: newsPack || {
        ok: false,
        items: [],
        links: {
          forum: links.cmoneyForum,
          stock: links.cmoneyStock,
          noteRef: links.cmoneyNoteRef
        },
        note: "新聞暫讀不到。"
      },
      tip: "規則彙整公開資訊，非投資建議。重訊與法說以公司依法公告為準。"
    };
  }

  let directorHoldCache = null;
  let directorHoldAt = 0;

  function buildDirectorHoldMap(rows) {
    const map = {};
    (rows || []).forEach(function (row) {
      const code = String(row["公司代號"] || row.code || "").trim();
      const title = String(row["職稱"] || row.title || "");
      if (!code) return;
      if (title && (!/董事|監察/.test(title) || /代表人/.test(title))) return;
      const shares = num(row["目前持股"] != null ? row["目前持股"] : row.shares);
      if (!(shares > 0)) return;
      map[code] = (map[code] || 0) + shares;
    });
    return map;
  }

  async function fetchOpenTwseJson(dataset) {
    const abs = "https://openapi.twse.com.tw/v1/opendata/" + dataset;
    const urls = [
      abs,
      "https://corsproxy.io/?" + encodeURIComponent(abs),
      "https://api.allorigins.win/raw?url=" + encodeURIComponent(abs),
      "https://api.codetabs.com/v1/proxy?quest=" + encodeURIComponent(abs)
    ];
    let lastErr = null;
    for (let i = 0; i < urls.length; i++) {
      try {
        const ctrl = typeof AbortController !== "undefined" ? new AbortController() : null;
        const timer = ctrl ? setTimeout(function () { ctrl.abort(); }, 20000) : 0;
        const res = await fetch(urls[i], ctrl ? { signal: ctrl.signal } : undefined);
        if (timer) clearTimeout(timer);
        if (!res.ok) continue;
        const text = await res.text();
        const start = text.indexOf("[");
        const end = text.lastIndexOf("]");
        if (start < 0 || end <= start) continue;
        const data = JSON.parse(text.slice(start, end + 1));
        if (Array.isArray(data)) return data;
      } catch (err) {
        lastErr = err;
      }
    }
    throw lastErr || new Error("證交所開放資料讀取失敗");
  }

  async function directorHoldSharesMap() {
    const now = Date.now();
    if (directorHoldCache && now - directorHoldAt < 24 * 60 * 60 * 1000) return directorHoldCache;
    // 優先讀站內精簡檔（GitHub Pages 同源，避免 9MB OpenAPI CORS／逾時）
    try {
      const local = await fetch("data/director-holds.json?v=120", { cache: "force-cache" });
      if (local.ok) {
        const json = await local.json();
        const holds = json && json.holds ? json.holds : null;
        if (holds && typeof holds === "object") {
          const map = {};
          Object.keys(holds).forEach(function (code) {
            const n = num(holds[code]);
            if (n > 0) map[code] = n;
          });
          if (Object.keys(map).length) {
            directorHoldCache = map;
            directorHoldAt = now;
            return map;
          }
        }
      }
    } catch (err) { /* fall through */ }
    const rows = await fetchOpenTwseJson("t187ap11_L");
    const map = buildDirectorHoldMap(rows);
    directorHoldCache = map;
    directorHoldAt = now;
    return map;
  }

  // 線圖持股占比：外資／董監官方；ETF(投信)／自營／券商(避險)以買賣超÷發行股累計粗估；散戶＝其餘
  async function stockHoldLines(secid, code, startDate) {
    const stockId = twStockId(secid, code);
    if (!stockId) return { ok: false, reason: "目前僅台股有持股占比線。" };
    const start = startDate && String(startDate).length >= 10
      ? String(startDate).slice(0, 10)
      : isoDaysAgo(400);
    const lookback = isoDaysAgo(Math.max(420, Math.ceil((Date.now() - Date.parse(start)) / 86400000) + 80));
    const got = await Promise.all([
      finMind("TaiwanStockShareholding", stockId, lookback).catch(function () { return []; }),
      finMind("TaiwanStockInstitutionalInvestorsBuySell", stockId, lookback).catch(function () { return []; }),
      directorHoldSharesMap().catch(function () { return {}; })
    ]);
    const shares = (got[0] || []).slice().sort(function (a, b) {
      return String(a.date).localeCompare(String(b.date));
    });
    const chips = got[1] || [];
    const dirMap = got[2] || {};
    if (!shares.length && !chips.length) {
      return { ok: false, reason: "持股／法人資料暫讀不到。" };
    }

    const foreignByDate = {};
    const issuedByDate = {};
    shares.forEach(function (row) {
      const d = String(row.date || "").slice(0, 10);
      if (!d) return;
      const pct = num(row.ForeignInvestmentSharesRatio);
      const issued = num(row.NumberOfSharesIssued);
      if (pct != null && isFinite(pct)) foreignByDate[d] = pct;
      if (issued > 0) issuedByDate[d] = issued;
    });
    const issuedDates = Object.keys(issuedByDate).sort();
    let lastIssued = issuedDates.length ? issuedByDate[issuedDates[issuedDates.length - 1]] : null;

    const dayFlow = {};
    chips.forEach(function (row) {
      const d = String(row.date || "").slice(0, 10);
      if (!d) return;
      if (!dayFlow[d]) dayFlow[d] = { etf: 0, dealer: 0, broker: 0 };
      const net = (num(row.buy) || 0) - (num(row.sell) || 0);
      const name = String(row.name || "");
      if (name === "Investment_Trust") dayFlow[d].etf += net;
      else if (name === "Dealer_self" || name === "Dealer") dayFlow[d].dealer += net;
      else if (name === "Dealer_Hedging") dayFlow[d].broker += net;
    });

    const allDates = Array.from(new Set(
      Object.keys(foreignByDate).concat(Object.keys(dayFlow)).concat(Object.keys(issuedByDate))
    )).sort();
    let etfCum = 0;
    let dealerCum = 0;
    let brokerCum = 0;
    let lastForeign = null;
    const byDate = {};
    const directorShares = num(dirMap[stockId]);
    allDates.forEach(function (d) {
      if (issuedByDate[d] > 0) lastIssued = issuedByDate[d];
      const flow = dayFlow[d];
      if (flow) {
        etfCum += flow.etf;
        dealerCum += flow.dealer;
        brokerCum += flow.broker;
      }
      if (foreignByDate[d] != null) lastForeign = foreignByDate[d];
      if (d < start) return;
      if (!(lastIssued > 0) && lastForeign == null && !flow) return;
      const issued = lastIssued > 0 ? lastIssued : null;
      const etf = issued ? Math.max(0, etfCum / issued * 100) : null;
      const dealer = issued ? Math.max(0, dealerCum / issued * 100) : null;
      const broker = issued ? Math.max(0, brokerCum / issued * 100) : null;
      const director = (issued && directorShares > 0) ? Math.max(0, directorShares / issued * 100) : null;
      const foreign = lastForeign;
      let retail = null;
      if (foreign != null || etf != null || dealer != null || broker != null || director != null) {
        retail = 100
          - (foreign != null ? foreign : 0)
          - (etf != null ? etf : 0)
          - (dealer != null ? dealer : 0)
          - (broker != null ? broker : 0)
          - (director != null ? director : 0);
        if (retail < 0) retail = 0;
        if (retail > 100) retail = 100;
      }
      byDate[d] = {
        foreign: foreign,
        etf: etf,
        dealer: dealer,
        broker: broker,
        director: director,
        retail: retail
      };
    });

    return {
      ok: true,
      stockId: stockId,
      byDate: byDate,
      keys: [
        { id: "foreign", name: "外資", color: "#60a5fa" },
        { id: "etf", name: "ETF/投信", color: "#c084fc" },
        { id: "dealer", name: "自營", color: "#fbbf24" },
        { id: "broker", name: "券商", color: "#34d399" },
        { id: "director", name: "董監", color: "#ff4fd8", dash: [6, 4] },
        { id: "retail", name: "散戶", color: "#94a3b8" }
      ],
      directorShares: directorShares > 0 ? directorShares : null,
      note: directorShares > 0
        ? ("外資為官方持股占比；董監為證交所最新餘額÷發行股（約 " +
          (lastIssued > 0 ? (directorShares / lastIssued * 100).toFixed(1) + "%" : "—") +
          "）；ETF(投信)／自營／券商(避險)為買賣超÷發行股累計粗估；散戶＝其餘。")
        : "外資為官方持股占比；董監資料暫無（上櫃／未列名可能缺）；ETF(投信)／自營／券商為粗估；散戶＝其餘。"
    };
  }

  function alignHoldLines(pack, axis) {
    if (!pack || !pack.ok || !pack.byDate || !axis || !axis.length) return null;
    const keys = pack.keys || [];
    const series = keys.map(function (k) {
      return {
        id: k.id,
        name: k.name,
        color: k.color,
        dash: k.dash || null,
        values: axis.map(function () { return null; })
      };
    });
    let last = null;
    axis.forEach(function (label, i) {
      const day = String(label || "").slice(0, 10);
      if (pack.byDate[day]) last = pack.byDate[day];
      if (!last) return;
      series.forEach(function (s) {
        const v = last[s.id];
        s.values[i] = v != null && isFinite(v) ? v : null;
      });
    });
    return {
      note: pack.note || "",
      series: series.filter(function (s) {
        return s.values.some(function (v) { return v != null && isFinite(v); });
      })
    };
  }

